import type { WordEntry } from '../game/types'

export const generatedWords: WordEntry[] = [
  { word: 'BAMBAATAA', category: 'historia', difficulty: 'easy', knowledge: { title: 'Afrika Bambaataa', description: 'Afrika Bambaataa (Kevin Donovan, nacido el 17 de abril de 1957 en el Bronx; fallecido el 9 de abril de 2026 en Pensilvania) fue un DJ y productor estadounidense, hijo de migrantes jamaiquinos y barbadenses, considerado uno de los "padrinos" del Hip Hop junto a DJ Kool Herc y Grandmaster Flash. Fundó la organización Universal Zulu Nation, popularizó el DJing de breaks en el Bronx y produjo "Planet Rock" (1982), un himno del electro que marcó la música Hip Hop.', importance: 'Bambaataa conectó el DJing de breaks con una visión organizativa y espiritual del Hip Hop: la idea de que la cultura podía sacar a la juventud de la violencia de las pandillas. Su música amplió el sonido del Hip Hop hacia la electrónica y su organización inspiró a generaciones de artistas en todo el mundo.', funFact: '"Planet Rock" (1982), de Afrika Bambaataa & Soulsonic Force, sampleó "Trans-Europe Express" de Kraftwerk y usó la caja de ritmos Roland TR-808: es uno de los primeros grandes éxitos del Hip Hop y del electro, y su influencia se extiende al house, el techno y el pop electrónico.', related: ['BLOCK_PARTY', 'BREAK', 'DJ_KOOL_HERC', 'FLASH', 'HIP_HOP', 'ZULU_NATION'] } },
  { word: 'SEDGWICK73', category: 'historia', difficulty: 'easy', knowledge: { title: 'Block Party del 11 de agosto de 1973 (1520 Sedgwick Avenue)', description: 'El 11 de agosto de 1973, Cindy Campbell organizó en el salón de fiestas del edificio 1520 Sedgwick Avenue, en el Bronx, una fiesta para recaudar dinero para su ropa de vuelta a clases: el "Back To School Jam". Su hermano Clive Campbell, conocido como DJ Kool Herc, puso los discos. El flyer de la fiesta, conservado en la colección del Smithsonian, es el registro más temprano y difundido de una fiesta del Hip Hop naciente.', importance: 'Esta fiesta concentra el mito fundacional del Hip Hop: el DJ que repite los breaks, el salón del barrio como escenario y la comunidad como organizadora. Aunque la historiografía matiza que la cultura se gestó en varios lugares y momentos, el 11 de agosto de 1973 es la fecha que el mundo celebra como el aniversario del nacimiento del Hip Hop, y el edificio es conocido como su "lugar de nacimiento".', funFact: 'El flyer del "Back To School Jam" anuncia la entrada a 25 centavos para las damas y 50 centavos para los caballeros, y el horario de 9 p. m. a 4 a. m. El original no se conserva: según Christie\'s (2022) y Cindy Campbell, la versión que circula es una recreación artística; una copia está en la colección del Smithsonian NMAAHC.', related: ['BLOCK_PARTY', 'BREAK', 'DJ_KOOL_HERC', 'HERCULOIDS', 'HIP_HOP'] } },
  { word: 'BLOCK_PARTY', category: 'historia', difficulty: 'easy', knowledge: { title: 'Block Party', description: 'La block party es la fiesta de barrio que se hacía en la calle, un patio, una cancha o un parque, con un equipo de sonido potente y un DJ al mando. En el Bronx de los años 70, estas fiestas fueron el laboratorio donde nació el Hip Hop: DJs, MCs, breakers y writers se encontraron por primera vez alrededor de la música.', importance: 'La block party es el formato donde se juntaron las piezas de la cultura: el DJ con sus breaks, el MC animando por el micrófono, los breakers bailando en el círculo y los writers dejando su firma en el barrio. Entenderla es entender por qué el Hip Hop es una cultura de barrio y no un género musical que "bajó" de la industria.', funFact: 'En una block party no había escenario ni separación entre artista y público: todo pasaba en el mismo espacio de la calle, y cualquiera podía entrar al círculo.', related: ['BREAK', 'CINDYCAMP', 'DJ_KOOL_HERC', 'HIP_HOP'] } },
  { word: 'BREAK', category: 'historia', difficulty: 'easy', knowledge: { title: 'Break', description: 'El break es la sección de un disco —generalmente de funk o soul— donde la base se adelgaza y quedan la batería y el bajo solos, en un momento rítmico intenso y bailable. En el nacimiento del Hip Hop, el break fue la materia prima de los DJs: la parte que todos esperaban para bailar.', importance: 'El break es el puente entre tres disciplinas: el DJ lo extiende, el breaker lo baila y el productor lo samplea. Sin el concepto de break no se entiende ninguna de las tres, ni el Hip Hop como cultura nacida de la música.', funFact: 'Un mismo break puede durar pocos segundos en el disco original, pero con el merry-go-round de Herc se convertía en la base de toda una fiesta.', related: ['BLOCK_PARTY', 'B_BOY', 'DJ_KOOL_HERC', 'HIP_HOP'] } },
  { word: 'BRONX', category: 'historia', difficulty: 'easy', knowledge: { title: 'Bronx', description: 'El Bronx es el distrito (borough) más al norte de la ciudad de Nueva York y el único que no es una isla: está conectado al resto del continente. En los años 70 fue el territorio donde nació el Hip Hop: DJs, MCs, breakers y writers construyeron la cultura en sus salones, parques, canchas y calles, en medio de una de las crisis urbanas más duras de la historia de Estados Unidos.', importance: 'El Bronx es el territorio fundacional del Hip Hop: todas las disciplinas de la cultura —DJing, MCing, breaking, writing— se gestaron en sus espacios entre 1973 y la primera mitad de los 80. Entender el Bronx de los 70 es entender por qué el Hip Hop nació como respuesta cultural de una comunidad abandonada por el Estado, y no como producto de la industria musical.', funFact: 'El 1520 Sedgwick Avenue, edificio donde se celebró la fiesta del 11 de agosto de 1973, es conocido como el "lugar de nacimiento del Hip Hop": el propio DJ Kool Herc lo llamó "el Belén de la cultura Hip Hop". Aun así, la historiografía documenta que el Hip Hop se gestó en varios puntos del Bronx a la vez, no en un solo edificio.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'DJ_KOOL_HERC', 'FLASH', 'HERCULOIDS', 'HIP_HOP', 'SEDGWICK73'] } },
  { word: 'CONSOLIDA80', category: 'historia', difficulty: 'medium', knowledge: { title: 'Consolidación del Hip Hop en los 80', description: 'La consolidación del Hip Hop en los 80 es el proceso por el que el rap pasó de ser música de fiestas de barrio a industria: sellos discográficos, discos de oro, videos en MTV y estrellas de alcance nacional. Es la etapa en que el Hip Hop construyó su estructura comercial y musical, sobre todo entre 1984 y 1988, y en la que nacieron muchos de los modelos que la cultura usa hasta hoy.', importance: 'La consolidación de los 80 definió la relación entre el Hip Hop y la industria que sigue vigente: sellos propios, producción basada en sampling, videos como herramienta y el rap como música de masas. También mostró las tensiones de la cultura con el mercado —qué se comercializa y quién gana—, tensiones que son parte central de la historia del Hip Hop.', funFact: 'En 1988, en menos de tres meses, salieron *It Takes a Nation of Millions to Hold Us Back* (junio) y *Straight Outta Compton* (8 de agosto), y el 6 de agosto de ese mismo año MTV estrenó *Yo! MTV Raps*: el rap ya era industria, fenómeno nacional y cultura mediática a la vez.', related: ['EXPANSION80S', 'HIP_HOP', 'RAPDELIGHT', 'RUN_DMC'] } },
  { word: 'CREWS_70S', category: 'historia', difficulty: 'easy', knowledge: { title: 'Crews de los 70', description: 'Las crews de los 70 son los grupos juveniles del Bronx que pasaron de ser pandillas territoriales a crews culturales del Hip Hop: primero los Black Spades, los Savage Skulls y los Ghetto Brothers dominaban las calles; después, muchos de esos mismos jóvenes fundaron las crews de DJs, MCs, breakers y writers que hicieron las fiestas. La crew es el formato de organización social del Hip Hop: un grupo con nombre propio, identidad y lealtad.', importance: 'Las crews de los 70 explican la estructura social del Hip Hop: la cultura no la hicieron artistas individuales sino grupos con identidad, nombre y territorio simbólico. La crew es el puente entre la pandilla y la cultura: la lealtad, la competencia y el orgullo se mantuvieron, pero el campo de batalla cambió de la calle a la jam, al cypher y al escenario.', funFact: 'La tregua de Hoe Avenue (diciembre de 1971), convocada por los Ghetto Brothers tras el asesinato de su ministro de paz, reunió a unas doscientas personas de decenas de pandillas del Bronx y es considerada un punto de inflexión: con la violencia en baja, las fiestas y jams donde nació el Hip Hop pudieron crecer.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'BREAKERS70', 'BRONX', 'DJ_KOOL_HERC', 'HERCULOIDS', 'HIP_HOP', 'JAM', 'ROCKSTEADY', 'ZULU_NATION'] } },
  { word: 'DJ_KOOL_HERC', category: 'historia', difficulty: 'easy', knowledge: { title: 'DJ Kool Herc', description: 'DJ Kool Herc (Clive Campbell, nacido en Kingston, Jamaica, en 1955) es el DJ jamaiquino-estadounidense al que la historia del Hip Hop reconoce como uno de los fundadores de la cultura. En sus fiestas del Bronx desarrolló la técnica de repetir los breaks de los discos —el "merry-go-round"— que dio origen al break dancing y al Hip Hop como lo conocemos.', importance: 'Herc es el eslabón que conecta la tradición jamaiquina de los sound systems con la cultura neoyorquina: sin su técnica de extender breaks no existiría el break dancing, y sin su uso del micrófono no existiría el rap como se desarrolló después. Es la figura central del nacimiento de la cultura.', funFact: 'La fiesta del 11 de agosto de 1973 en el 1520 Sedgwick Avenue es el hito más citado del nacimiento del Hip Hop, respaldado por el testimonio de Cindy Campbell, pero no la "primera fiesta de Hip Hop": Herc ya hacía fiestas antes según su testimonio, y no se conserva un flyer original contemporáneo (la imagen famosa es muy probablemente una recreación posterior).', related: ['BLOCK_PARTY', 'BREAK', 'B_BOY', 'CINDYCAMP', 'HIP_HOP'] } },
  { word: 'EXPANSION70S', category: 'historia', difficulty: 'easy', knowledge: { title: 'Expansión del Hip Hop en los 70', description: 'La expansión del Hip Hop en los 70 es el proceso por el cual la cultura salió de las fiestas de barrio del Bronx y se extendió por toda la ciudad de Nueva York a fines de la década: más DJs, más crews, más territorios, clubes propios y, al final, las primeras grabaciones comerciales. Es el paso de la fiesta local al movimiento de ciudad.', importance: 'La expansión de los 70 convirtió al Hip Hop de un fenómeno de barrio en una cultura de ciudad con proyección nacional: demostró que no era una moda local, que tenía público, competencia y lenguaje propio. Sin este crecimiento dentro de Nueva York, las grabaciones de 1979 no habrían tenido a quién llegar ni de dónde salir.', funFact: 'En 1979, el mismo año en que la disco estaba en su pico comercial, "Rapper\'s Delight" del Sugarhill Gang —construida sobre el groove de "Good Times" de Chic— llevó el rap a la radio comercial y marcó el final de la etapa de expansión dentro de Nueva York y el inicio de la industria del rap.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'BRONX', 'DJ_KOOL_HERC', 'FLASH', 'GRABACIONES', 'HIP_HOP', 'JAM', 'NUEVA_YORK', 'PRIMEROSDJS', 'RAPDELIGHT'] } },
  { word: 'EXPANSION80S', category: 'historia', difficulty: 'easy', knowledge: { title: 'Expansión del Hip Hop en los 80', description: 'A comienzos de los 80, el Hip Hop dejó de ser un fenómeno del Bronx y se convirtió en una cultura de alcance mundial. Las películas, la radio, la televisión y los propios protagonistas que viajaron llevaron el rap, el breaking, el graffiti y el DJing a Europa, Japón y el resto del planeta, en un proceso que cambió para siempre la escala de la cultura.', importance: 'La expansión de los 80 probó que el Hip Hop no era una moda local: era una cultura con lenguaje propio capaz de cruzar fronteras. Gracias a este proceso, las escenas de Europa, Japón y luego el resto del mundo empezaron a producir su propio Hip Hop, y hoy la cultura se cuenta por países, no solo por barrios de Nueva York. Esta entrada es la puerta de entrada a la historia de esa difusión (ver área 10 del repositorio).', funFact: 'En 1983, el mismo año en que se estrenaron *Wild Style* y *Flashdance*, Crazy Legs llevó el breaking a Londres y París: la expansión del Hip Hop fue protagonizada por la primera generación, no solo por las pantallas.', related: ['HIP_HOP', 'RAPDELIGHT', 'ROCKSTEADY'] } },
  { word: 'FLASH', category: 'historia', difficulty: 'easy', knowledge: { title: 'Grandmaster Flash', description: 'Grandmaster Flash (Joseph Robert Saddler, nacido el 1 de enero de 1958 en Bridgetown, Barbados, y criado en el Bronx) es un DJ estadounidense de origen barbadense, considerado uno de los tres "padrinos" del DJing del Hip Hop junto a DJ Kool Herc y Afrika Bambaataa. Desarrolló técnicas de precisión como la quick mix theory y el backspin, y con su grupo The Furious Five grabó "The Message" (1982), uno de los primeros grandes clásicos del rap con contenido social.', importance: 'Flash transformó al DJ de animador de fiestas en un instrumentista: sus técnicas de precisión son la base del turntablism, el arte de tocar el tocadiscos como instrumento musical. Su obra con los Furious Five demostró que el rap podía tener profundidad social y éxito comercial.', funFact: 'Grandmaster Flash & The Furious Five fueron el primer grupo de Hip Hop en ingresar al Rock and Roll Hall of Fame (2007), y "The Message" (1982) está considerada una de las canciones más influyentes de la historia del rap.', related: ['BAMBAATAA', 'BREAK', 'DJ_KOOL_HERC', 'HIP_HOP', 'MERRYGOROUND'] } },
  { word: 'HERCULOIDS', category: 'historia', difficulty: 'easy', knowledge: { title: 'Herculoids', description: 'Los Herculoids fueron la crew (equipo) de DJ Kool Herc en el Bronx de los años 70: el grupo de amigos que lo acompañaba a las fiestas, animaba al público y ayudaba con el equipo de sonido. Su miembro más recordado es Coke La Rock, a quien la tradición oral de la escena reconoce como uno de los primeros MCs del Hip Hop.', importance: 'Los Herculoids representan el modelo de crew del Hip Hop temprano: la idea de que la cultura se construye en equipo, con el DJ al centro y los MCs y colaboradores alrededor. Su historia muestra que el MCing nació como una función práctica —animar al público— antes de convertirse en un arte con nombre propio.', funFact: 'Coke La Rock, miembro de los Herculoids, es considerado por la tradición oral de la escena el primer MC del Hip Hop: según esa versión, sus saludos por el micrófono en las fiestas de Herc inspiraron a toda una generación de raperos. No existe registro contemporáneo que lo confirme como "el primero".', related: ['COKE_LA_ROCK', 'DJ_KOOL_HERC', 'HIP_HOP', 'PRIMEROSMCS', 'SEDGWICK73'] } },
  { word: 'NUEVA_YORK', category: 'historia', difficulty: 'easy', knowledge: { title: 'Nueva York', description: 'Nueva York es la ciudad más grande de Estados Unidos y, en los años 70, el escenario donde nació el Hip Hop: la cultura surgió en sus barrios, sobre todo en el Bronx, y desde ahí se expandió por el resto de la ciudad y el mundo. En esa década la ciudad atravesó una de sus peores crisis económicas y sociales, y precisamente de esa crisis nació una de sus mayores contribuciones a la cultura mundial.', importance: 'Nueva York es la ciudad matriz del Hip Hop: la cultura nació en sus barrios en los 70 y se expandió desde ahí a todo el planeta. Entender la Nueva York de los 70 —crisis fiscal, apagones, incendios, pandillas y, al mismo tiempo, una creatividad juvenil desbordante— es entender las condiciones que hicieron posible el nacimiento del Hip Hop.', funFact: 'En 1977, el año del gran apagón, Nueva York estaba considerada una ciudad en crisis terminal: el apagón del 13-14 de julio dejó a oscuras a 8 millones de personas y provocó más de 1 000 incendios. Ese mismo año, en los barrios de la ciudad, el Hip Hop ya era una cultura en plena ebullición.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'DJ_KOOL_HERC', 'FLASH', 'HERCULOIDS', 'HIP_HOP', 'SEDGWICK73'] } },
  { word: 'GRABACIONES', category: 'historia', difficulty: 'easy', knowledge: { title: 'Primeras Grabaciones de Rap', description: 'Las primeras grabaciones de rap son los discos que, entre los años 60 y 1979, llevaron la palabra hablada con ritmo al vinilo: primero como spoken word político (The Last Poets, Gil Scott-Heron) y luego como el rap de fiesta del Bronx que explotó comercialmente en 1979 con "Rapper\'s Delight". Son el momento en que la cultura de las jams (ver `jam`) se convirtió en industria.', importance: 'Las primeras grabaciones transformaron el Hip Hop: lo sacaron del barrio y lo pusieron en la radio, el vinilo y la lista de éxitos. Sin ellas, el rap habría seguido siendo una cultura local; con ellas, la industria descubrió un negocio y el mundo descubrió el sonido del Bronx. También marcaron el inicio de las tensiones entre la cultura de la calle y la industria que acompañan al Hip Hop hasta hoy.', funFact: '"King Tim III (Personality Jock)" de The Fatback Band salió antes que "Rapper\'s Delight" y es considerado el primer single comercial con rap, pero fue "Rapper\'s Delight" (septiembre de 1979) la primera canción de rap en entrar al Billboard Hot 100 y la que explotó comercialmente a nivel mundial.', related: ['EXPANSION70S', 'HIP_HOP', 'JAM', 'PRIMEROSMCS', 'RAPDELIGHT', 'SEDGWICK73'] } },
  { word: 'BREAKERS70', category: 'historia', difficulty: 'easy', knowledge: { title: 'Primeros Breakers', description: 'Los primeros breakers son los bailarines que, en las fiestas del Bronx de los años 70, salían al centro del círculo a bailar durante el break de los discos: la parte de la canción donde quedaba solo la percusión. Con pasos de tierra, giros y poses congeladas, inventaron el breaking, la disciplina de baile del Hip Hop.', importance: 'Los primeros breakers demostraron que el Hip Hop también es una cultura del cuerpo: el baile nació en el mismo momento y lugar que el DJing y el MCing, dentro del círculo de la jam. La competencia de estilo, el respeto por lo original y la idea de que cualquiera puede entrar al círculo son valores que los breakers fundaron y que la cultura mantiene hasta hoy.', funFact: 'El break no era solo música: era la señal de que la fiesta cambiaba de modo. Cuando sonaba el break, los breakers entraban al círculo; el resto de la fiesta los miraba y juzgaba. Por eso el b-boy (ver `b-boy`) lleva ese nombre: baila en el break.', related: ['BLOCK_PARTY', 'BREAK', 'B_BOY', 'CYPHER', 'DJ_KOOL_HERC', 'HIP_HOP', 'JAM', 'ROCKSTEADY', 'ZULU_NATION'] } },
  { word: 'PRIMEROSDJS', category: 'historia', difficulty: 'easy', knowledge: { title: 'Primeros DJs', description: 'Los primeros DJs son los pioneros que pusieron los discos en las fiestas de barrio del Bronx a mediados de los años 70 y convirtieron el oficio de pinchar música en la base musical del Hip Hop. Con tocadiscos, parlantes y un puñado de discos de funk, soul y disco, descubrieron que la gente enloquecía con la parte más rítmica de la canción: el break.', importance: 'Los primeros DJs establecieron el principio fundacional del Hip Hop: el DJ como autoridad musical y creador, no como simple reproductor de discos. Inventaron las técnicas —extender breaks, cortar, mezclar— sobre las que se construyó toda la música posterior, y crearon el espacio físico (la jam, ver `jam`) donde nacieron el MCing, el breaking y el writing.', funFact: 'La técnica del merry-go-round de Kool Herc es la base documentada por la historia oral de la escena: al repetir el break, el DJ creó el momento musical exacto en el que los bailarines desarrollaron el breaking.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'BREAK', 'BRONX', 'DJ_KOOL_HERC', 'FLASH', 'HERCULOIDS', 'HIP_HOP', 'JAM', 'MERRYGOROUND'] } },
  { word: 'PRIMEROSMCS', category: 'historia', difficulty: 'easy', knowledge: { title: 'Primeros MCs', description: 'Los primeros MCs (maestros de ceremonia) son los pioneros que tomaron el micrófono en las fiestas del Bronx a mediados de los años 70 para animar a la gente: saludar, presentar, lanzar frases rítmicas y responder al público. Su oficio evolucionó hasta convertirse en el rap: la palabra hablada con ritmo sobre la música del DJ.', importance: 'Los primeros MCs convirtieron la voz en un instrumento del Hip Hop y fundaron la disciplina que hoy conocemos como rap o MCing. Demostraron que la cultura no era solo música de fiesta: tenía voz, humor, competencia y palabra. El saludo, la presentación y la rima nacieron en el micrófono de estas fiestas.', funFact: 'Coke La Rock, considerado por tradición oral el primer MC, nunca grabó un disco: su legado vive en los testimonios de la escena y en el reconocimiento del propio DJ Kool Herc, que siempre lo acreditó como el primero en el micrófono.', related: ['BLOCK_PARTY', 'CYPHER', 'DJ_KOOL_HERC', 'FLASH', 'HERCULOIDS', 'HIP_HOP', 'JAM', 'PRIMEROSDJS'] } },
  { word: 'WRITERS70', category: 'historia', difficulty: 'easy', knowledge: { title: 'Primeros Writers', description: 'Los primeros writers son los pioneros del writing (escritura de graffiti), la disciplina visual del Hip Hop: jóvenes que pintaban su nombre o apodo —el "tag"— en las paredes, puertas y vagones de metro de Nueva York y Filadelfia a fines de los 60 y durante los 70. Lo que empezó como una forma de dejar la marca propia en la ciudad se convirtió en un arte con estilos, códigos y competencia.', importance: 'El writing es la disciplina visual del Hip Hop y demostró que la cultura también se expresaba con la mirada: la ciudad entera como galería. Estableció valores que el resto del Hip Hop comparte —la fama, el estilo propio, la competencia por ser el mejor— y dio voz visual a los jóvenes de barrios que no aparecían en ningún otro lugar.', funFact: 'TAKI 183 tiene el registro documentado más famoso del writing: el artículo del New York Times del 21 de julio de 1971, donde el propio TAKI reconoce que su formato (nombre + número de calle) venía de Julio 204, que escribía antes que él.', related: ['BLOCK_PARTY', 'BRONX', 'HIP_HOP', 'JAM', 'NUEVA_YORK'] } },
  { word: 'RAPDELIGHT', category: 'historia', difficulty: 'easy', knowledge: { title: 'Rapper\'s Delight', description: '"Rapper\'s Delight" es el single debut de Sugarhill Gang, publicado en 1979 por Sugar Hill Records y producido por Sylvia Robinson. Fue la primera canción de rap en entrar al Top 40 del Billboard Hot 100, y por eso se la considera la puerta por la que el rap llegó a la radio y a la industria musical masiva. No fue, en cambio, la primera grabación de rap: ese lugar lo ocupa "King Tim III (Personality Jock)" de The Fatback Band, lanzada poco antes.', importance: '"Rapper\'s Delight" demostró que el rap podía venderse como música grabada y sonar en la radio. Abrió el camino comercial por el que entraron las grabaciones de la escena neoyorquina y, más tarde, la industria que se consolidó en los 80 (ver `consolidacion-80s`). Además, su famosa frase "I said a hip-hop, the hippie, the hippie, to the hip, hip-hop and you don\'t stop the rockin\'" es uno de los primeros momentos en que la palabra "hip hop" llega al público masivo (ver entrada `hip-hop`).', funFact: 'La versión larga del 12 pulgadas dura 14 minutos con 37 segundos, y todo se grabó en una sola toma: la banda en vivo tocando la base de "Good Times" mientras los tres MCs rapeaban sin parar.', related: ['EXPANSION80S', 'GRABACIONES', 'HIP_HOP'] } },
  { word: 'ROXANNE', category: 'historia', difficulty: 'hard', knowledge: { title: 'Roxanne Wars', description: 'Las Roxanne Wars fueron una serie de discos de respuesta (answer records) y disputas del rap de mediados de los años 80 (1984–1985), desatada por el tema "Roxanne, Roxanne" de UTFO y la respuesta "Roxanne\'s Revenge" de Roxanne Shanté. Wikipedia las describe como el origen del primer diss record del rap y como una de las primeras disputas (beef) del género, además de la fuente de quizá la mayor cantidad de answer records de la historia de la música (ver `diss`, `beef`, `battle-rap`).', importance: 'Las Roxanne Wars consolidaron a Roxanne Shanté, The Real Roxanne y Sparky D como figuras del rap —incluidas las primeras MCs femeninas destacadas de la escena—, fijaron el answer record como arma de la cultura (la respuesta grabada como forma de batalla, ver `battle-rap`) y son el caso documentado más temprano del diss comercial y del beef como espectáculo grabado (ver `diss`, `beef`). La película *Roxanne Roxanne* (2017) llevó la historia de Shanté al cine.', funFact: '"Roxanne\'s Revenge" (1984) fue grabada por Lolita Shante Gooden —Roxanne Shanté— a los 14 años, improvisada en una sola toma de unos siete minutos sobre la instrumental de "Roxanne, Roxanne" de UTFO, producida por Marley Marl: es el answer record documentado como el primer diss record del rap, y desató una cadena de al menos 30 discos de respuesta (más de 100 según algunas afirmaciones).', related: ['BATTLE_RAP', 'BEEF', 'DISS', 'FREESTYLE', 'GRABACIONES', 'MARLEYMARL', 'MC'] } },
  { word: 'ZULU_NATION', category: 'historia', difficulty: 'medium', knowledge: { title: 'Universal Zulu Nation', description: 'La Universal Zulu Nation es la organización cultural fundada por Afrika Bambaataa (Kevin Donovan) en el Bronx, que transformó una pandilla callejera en una comunidad de paz, unidad y cultura. Es la institución más antigua del Hip Hop y la que difundió los valores que la cultura asocia a sus orígenes.', importance: 'La Zulu Nation es la prueba de que el Hip Hop nació también como proyecto social: usar la cultura para sacar a la juventud de la violencia de las pandillas. Los valores que difundió —paz, unidad, amor, diversión— son la base del "Knowledge" que la tradición de la cultura reconoce como uno de sus elementos.', funFact: 'Afrika Bambaataa, el fundador de la Zulu Nation, era un DJ que pasó de liderar una pandilla (Black Spades) a organizar block parties masivas donde las pandillas competían bailando en vez de pelear.', related: ['BLOCK_PARTY', 'HIP_HOP'] } },
  { word: 'AD_LIB', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Ad-lib', description: 'El ad-lib es la exclamación corta que el MC suelta alrededor de sus versos: un "¡yeah!", un "¡uh!", un "¡what!", un "¡ayy!" o una palabra de marca personal que aparece entre línea y línea, o detrás de la voz principal como eco. No forma parte de la letra principal ni del hook (ver `hook`): es un grito de energía, una firma de voz o un comentario en caliente. En grabación se registra como capa aparte de la voz; en vivo es el momento en que el MC suelta la fiesta.', importance: 'El ad-lib es la firma sonora del MC: hace reconocible a un rapero en pocos segundos, llena la canción de energía y conecta la grabación con la función original del MC como animador de la fiesta. También es un puente cultural documentado: el grito del toaster jamaiquino, el saludo del MC del Bronx y el ad-lib de estudio son eslabones de la misma cadena.', funFact: 'La palabra viene del latín ad libitum, "a voluntad": en música indica que algo se puede hacer libremente, y en el rap designa las exclamaciones que el MC suelta libremente alrededor de la letra, muchas veces improvisadas incluso dentro del estudio.', related: ['DJ_KOOL_HERC', 'FLOW', 'FREESTYLE', 'HOOK', 'MC', 'PRIMEROSMCS'] } },
  { word: 'BATTLE_RAP', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Battle rap', description: 'El battle rap es el formato de competencia de los MCs: dos raperos se enfrentan cara a cara con rimas, ante un público que aplaude, abuchea y decide quién ganó. Los contendientes pueden improvisar (ver `freestyle`) o llevar versos escritos, y el objetivo es superar al rival con ingenio, punchlines (ver `punchline`) y presencia escénica. No hay golpes ni armas: las palabras son el único arsenal, y el círculo o el escenario son la arena (ver `cypher`).', importance: 'El battle rap es el laboratorio del MCing: allí se prueban el flow (ver `flow`), la métrica (ver `metrica`), los punchlines y la capacidad de improvisar bajo presión. Muchos de los mejores raperos se formaron batallando, y el battle alimentó la cultura del freestyle y del diss. Además, condensa un valor central del Hip Hop: el respeto se gana en público, frente a los pares, sin escenario que proteja.', funFact: 'El enfrentamiento entre Kool Moe Dee y Busy Bee Starski en Harlem World (diciembre de 1981) es ampliamente citado como el battle que cambió el rap: Kool Moe Dee usó rimas escritas y dirigidas contra su rival, un formato que hasta entonces no era lo habitual.', related: ['BATTLE', 'BEEF', 'BLOCK_PARTY', 'CYPHER', 'DISS', 'FLOW', 'FREESTYLE', 'HARLEMWORLD', 'JAM', 'MC', 'PUNCHLINE', 'RIMA', 'SEDGWICK73'] } },
  { word: 'BEEF', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Beef', description: 'Un beef es un conflicto prolongado entre artistas de rap (o entre grupos, crews o sellos): una rivalidad con historia, que se manifiesta en canciones, entrevistas, apariciones públicas y, a veces, en la calle. La palabra inglesa *beef* significa "carne de res", pero en el slang designa una queja, una disputa o un pleito. El beef suele expresarse en disses (ver `diss`): canciones de ataque que responden a otras canciones, y puede terminar en reconciliación, en silencio o en tragedia.', importance: 'El beef ha definido eras del rap, lanzado carreras y movido la industria, pero también ha costado vidas: el caso East Coast–West Coast mostró el límite trágico de la rivalidad. Entender el beef es entender la doble cara de la competencia en el Hip Hop: motor creativo del diss y del battle, y riesgo real cuando sale del escenario.', funFact: '"Beef" como queja o disputa está documentado en el slang de habla inglesa desde finales del siglo XIX (expresiones como "cry beef", c. 1860): el Hip Hop no inventó la palabra, pero la adoptó y la globalizó como nombre del conflicto entre artistas.', related: ['BATTLE_RAP', 'CYPHER', 'DISS', 'EXPANSION80S', 'HIP_HOP', 'MC', 'PUNCHLINE', 'WORDPLAY'] } },
  { word: 'DISS', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Diss track', description: 'Un diss track es una canción cuyo propósito es atacar a otro artista: burlarse de él, responderle o humillarlo con rimas. La palabra viene del inglés *disrespect* (falta de respeto). Puede nacer como respuesta directa a otra canción, como golpe dentro de un `beef` (conflicto prolongado) o simplemente como estrategia para generar atención. Es la versión grabada del desafío que en vivo se juega en el `battle-rap`.', importance: 'El diss track es el arma principal del beef y uno de los motores de la historia del rap: definió rivalidades, movió ventas y atención, y empujó a los MCs a escribir sus rimas más afiladas (ver `punchline` y `wordplay`). Entender el diss es entender cómo la competencia del Hip Hop se trasladó del círculo a la industria.', funFact: '"Roxanne, Roxanne" de UTFO (1984) provocó una de las primeras guerras de disses grabados de la historia: Roxanne Shanté, de 14 años, respondió con "Roxanne\'s Revenge" y el intercambio inspiró más de 35 discos-respuesta en tres años.', related: ['BATTLE_RAP', 'BEEF', 'CONSOLIDA80', 'EXPANSION80S', 'MC', 'PUNCHLINE', 'RAPDELIGHT', 'RIMA', 'WORDPLAY'] } },
  { word: 'FLOW', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Flow', description: 'El flow es el flujo rítmico del rap: cómo la voz del MC se mueve sobre el beat. Incluye cuántas sílabas entran en cada compás, dónde caen los acentos, cómo se sincopa, cuándo respira y cómo articula cada palabra. Se siente como una corriente: hay MCs con flow lento y pesado, otros rápidos y cortados, y otros que fluyen como agua. Se mide analizando los acentos, las sílabas por compás y la ubicación de las rimas.', importance: 'El flow es la firma sonora del MC: lo que hace reconocible a un rapero en tres segundos y lo que convierte una letra escrita en música. Es la técnica que conecta la palabra con el beat y, por eso, la base del MCing moderno.', funFact: 'Según el análisis de Kyle Adams (2009), el flow se puede medir: se analiza la ubicación de las sílabas acentuadas, la ubicación de las sílabas rimadas, la cantidad de sílabas por pulso y la articulación (legato o staccato) —los acentos pueden caer en el tiempo fuerte o sincopados, desplazados respecto al pulso.', related: ['BREAKBEAT', 'FREESTYLE', 'MC', 'METRICA', 'RIMA', 'RIMA_INTERNA'] } },
  { word: 'FREESTYLE', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Freestyle', description: 'El freestyle es el rap improvisado: rimar en el momento, sin letra escrita, sobre una base. Se ve así: el MC toma el micrófono y va construyendo los versos mientras suenan —buscando la rima en tiempo real, repitiendo una palabra para ganar tiempo, soltando la línea justo cuando el beat lo pide. El público escucha el proceso en vivo, y esa exposición sin red es la esencia de la técnica.', importance: 'El freestyle es la prueba viva de la destreza del MC: demuestra rapidez mental, vocabulario, control del flow (ver `flow`) y presencia escénica sin red de protección. Es, junto con el cypher, el espacio donde la cultura se mide cara a cara, y la puerta de entrada de muchos MCs a la escena.', funFact: 'No hay una definición única de freestyle: la escuela clásica (Kool Moe Dee) lo define como una rima escrita "libre de estilo", y la escuela actual (LL Cool J, DMX) como improvisación pura "off the top" —las dos versiones conviven y se discuten en la escena.', related: ['BATTLE_RAP', 'CYPHER', 'FLOW', 'JAM', 'MC', 'PUNCHLINE', 'RIMA'] } },
  { word: 'HOOK', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Hook', description: 'El hook (estribillo) es la parte de la canción que se repite y "engancha": la sección pegajosa, casi siempre cantada o con una frase fácil de recordar, que vuelve varias veces entre los versos. En el rap, los versos cuentan la historia y el hook la resume en una frase musical que todos pueden cantar. Si el verso es la conversación, el hook es el grito que une a la gente.', importance: 'El hook es la puerta de entrada de la canción: es lo que hace que un tema se recuerde, se baile y se coree, y muchas veces decide si una canción llega al público. También es el punto de encuentro entre el MC y el oyente que no es rapero: aunque no sigas la letra del verso, el hook te atrapa.', funFact: 'En la estructura típica del rap, el verso dura unos 16 compases y el hook unos 8: el hook ocupa la mitad del espacio de un verso, pero se repite tres o cuatro veces por tema, por eso termina siendo la parte que más suena en la canción.', related: ['AD_LIB', 'FLOW', 'MC', 'POSSE_CUT', 'RAPDELIGHT', 'RIMA'] } },
  { word: 'MC', category: 'mcing', difficulty: 'easy', knowledge: { title: 'MC', description: 'El MC —sigla de "master of ceremonies", maestro de ceremonias— es la figura que toma el micrófono en el Hip Hop: anima, presenta, lanza frases rítmicas y, con el tiempo, rapea. Es el rol que dio origen al rapero: la voz que conecta la música del DJ con el público. En la práctica, hoy "MC" y "rapero" se usan como sinónimos.', importance: 'El MC es la voz del Hip Hop: convirtió la palabra en instrumento y fundó el MCing, una de las cuatro disciplinas originales de la cultura junto al DJing, el breaking y el writing. Sin el MC no existirían el freestyle, las batallas ni el rap comercial: toda la música rap actual desciende de esa figura que tomó el micrófono para animar una fiesta.', funFact: '"MC" viene de "master of ceremonies" (maestro de ceremonias) y el término se documenta aplicado a los raperos desde fines de los años 70: muchos artistas lo incorporaron directamente a su nombre artístico, como MC Hammer y MC Lyte.', related: ['BLOCK_PARTY', 'CYPHER', 'DJ_KOOL_HERC', 'FLASH', 'FLOW', 'FREESTYLE', 'HERCULOIDS', 'HIP_HOP', 'JAM', 'PRIMEROSMCS', 'RAPDELIGHT', 'RIMA'] } },
  { word: 'METRICA', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Métrica', description: 'La métrica es la estructura rítmica medible del verso de rap: el esqueleto de compases, tiempos, sílabas y acentos sobre el que se monta la voz. En el Hip Hop, el compás (bar, en inglés) estándar tiene cuatro tiempos —compás de 4/4— y en cada compás entran una cantidad determinada de sílabas. La métrica es lo que permite predecir dónde va a caer la rima (ver `rima`) y escribir versos que "caigan" en el beat.', importance: 'La métrica es la ingeniería del rap: la parte que se puede contar, medir y enseñar. Entenderla permite a un MC escribir con precisión —sabiendo cuántas sílabas entran por compás y dónde caerá la rima— y a un oyente, apreciar por qué un verso suena ajustado o descolgado del beat.', funFact: 'El compás estándar del rap tiene cuatro tiempos (4/4), un verso típico ronda los 16 compases y un estribillo los 8: contar sílabas por compás y ubicar las rimas en los tiempos fuertes es la base de la métrica del MCing.', related: ['BREAKBEAT', 'FLOW', 'MC', 'RIMA', 'RIMA_INTERNA'] } },
  { word: 'POSSE_CUT', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Posse cut', description: 'Un posse cut es una canción de rap en la que cuatro o más raperos se turnan para rapear sus versos, casi siempre miembros de una misma crew (ver `crew`), sello o escena. La palabra *posse* (grupo) viene del slang: en el rap de los 80, el posse era el grupo de acompañantes y colaboradores de un MC. El formato permite mostrar a toda la familia junta: cada rapero entra con su estilo, y el hook (ver `hook`) une los versos.', importance: 'El posse cut es la carta de presentación de una crew o de una escena: en una sola canción muestra identidad colectiva, jerarquías de estilo y nivel de cada MC. Además, documenta cómo el Hip Hop piensa en grupo: la crew no es solo un respaldo, es parte de la obra.', funFact: 'El diccionario de slang Green\'s define el posse cut como una canción de rap en la que cuatro o más raperos se turnan versos; "The Symphony" de Marley Marl (1988) es el ejemplo clásico más citado, con Big Daddy Kane, Craig G, Kool G Rap y Masta Ace.', related: ['BLOCK_PARTY', 'CREW', 'CYPHER', 'FLOW', 'FREESTYLE', 'HERCULOIDS', 'HOOK', 'JAM', 'MC', 'RIMA', 'ZULU_NATION'] } },
  { word: 'PUNCHLINE', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Punchline', description: 'La punchline (línea de remate) es la barra que cierra una idea con un giro: primero la preparación (setup) construye una dirección, y el remate la cambia de golpe, generando la reacción del público —el "¡aaah!" de la gente que reconoce el golpe. Se siente así: el MC suelta dos barras, la primera parece decir una cosa y la segunda la reinterpreta con un juego de palabras o una comparación inesperada. Es la técnica de impacto del rap.', importance: 'La punchline es el golpe del MCing: convierte una rima correcta en un momento memorable y define al MC como escritor ingenioso. Es la técnica que conecta la escritura (ver `rima` y `wordplay`) con la competencia en vivo, y por eso es el corazón del battle rap.', funFact: 'La estructura clásica de la punchline es setup + remate: la primera barra prepara la dirección y la segunda la cambia con un giro —su eficacia se mide por la reacción inmediata del público.', related: ['BATTLE_RAP', 'DISS', 'FLOW', 'MC', 'RIMA', 'RIMAMULTI', 'WORDPLAY'] } },
  { word: 'RIMA_INTERNA', category: 'mcing', difficulty: 'hard', knowledge: { title: 'Rima interna', description: 'La rima interna es la que ocurre dentro de un mismo verso, no solo al final: el MC hace rimar palabras en el medio de la línea, muchas veces en cadena, y remata con la rima final. Es un recurso que viene de la poesía, pero en el rap se convirtió en una marca de destreza: cuantas más rimas caben en una línea, más denso y veloz suena el flujo. Un ejemplo sencillo de elaboración propia: "Estoy contento: mi argumento es que el momento no es lamento, es instrumento".', importance: 'La rima interna convierte cada verso en un entramado: multiplica los puntos de rima, permite rapear más rápido sin perder el ritmo y eleva el estándar de escritura del MCing. Es una de las herramientas que separa al MC técnico del que solo rima en los finales de línea, y la base sobre la que se construyen la rima multisilábica (ver `rima-multisilabica`) y las punchlines más celebradas.', funFact: 'En una sola línea pueden caber varias rimas internas encadenadas: en el ejemplo "Estoy contento: mi argumento es que el momento no es lamento, es instrumento", cinco palabras riman dentro del mismo verso (contento, argumento, momento, lamento, instrumento) antes de llegar a la rima final. Esa densidad es la firma del rap técnico moderno.', related: ['FLOW', 'MC', 'METRICA', 'RIMA', 'RIMAMULTI'] } },
  { word: 'RIMAMULTI', category: 'mcing', difficulty: 'hard', knowledge: { title: 'Rima multisilábica', description: 'La rima multisilábica (también llamada "multis") hace rimar grupos de dos o más sílabas completas, no solo la última sílaba de la palabra: "sabiendo", "aprendiendo" y "entendiendo" riman en su terminación de varias sílabas ("-iendo"), y el MC encadena esas unidades a lo largo del verso. Mientras la rima simple une finales de palabra, la multisilábica exige construir frases enteras que suenen casi igual, por eso muchas veces suena como un trabalenguas. Un ejemplo sencillo de elaboración propia: "Nadie nace sabiendo: el que va aprendiendo va entendiendo".', importance: 'La rima multisilábica es la prueba de fuego del lirismo: exige vocabulario, sintaxis flexible y dominio absoluto de la métrica. Elevó el estándar del rap técnico y alimentó la cultura de la punchline (ver `punchline`) y del rap de competencia, donde una frase multisilábica bien resuelta es un golpe difícil de superar.', funFact: 'El pasaje de "Twinz (Deep Cover \'98)" de Big Pun (1998) es citado por la prensa y por las anotaciones de letras como uno de los ejemplos más celebrados de rima multisilábica del rap. La valoración de que es "la más compleja de la historia" es subjetiva y no verificable, pero el verso es un hito documentado del recurso.', related: ['FLOW', 'MC', 'METRICA', 'PUNCHLINE', 'RIMA', 'RIMA_INTERNA'] } },
  { word: 'RIMA', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Rima', description: 'La rima es la repetición de sonidos entre dos o más palabras, desde la última vocal acentuada en adelante: "juego" rima con "fuego", "sirena" con "llena". En el rap es el pegamento de las líneas: une los versos entre sí, los ancla al ritmo y hace que la letra se recuerde. Sin rima no hay rap como lo conocemos —es el elemento más reconocible del MCing (ver `mc`).', importance: 'La rima es la unidad básica del rap: organiza el sonido, la memoria y el golpe de cada línea. Entender la rima es entender cómo se construye una barra, cómo se prepara una punchline (ver `punchline`) y por qué algunos versos se quedan grabados en la cabeza.', funFact: 'Según el análisis de Kyle Adams (2009), en el rap de los 80 las sílabas rimadas caían típicamente en los cuartos tiempos sucesivos del compás: la rima no solo decora, también ancla el verso al ritmo. Ejemplos de rima (originales de esta enciclopedia): - Rima final consonante: "Sube la apuesta, entra al juego: / mi rima es llama, la tuya es fuego." - Rima interna y final: "La sirena suena, mi rima llena el vacío: / el frío se va cuando sube el brío." - Rima multisilábica: "La vida es aparente y la muerte es diferente: / rima que se siente, verso que no miente."', related: ['FLOW', 'MC', 'METRICA', 'PUNCHLINE', 'RIMAMULTI', 'RIMA_INTERNA'] } },
  { word: 'STORYTELLING', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Storytelling', description: 'El storytelling (rap narrativo) es la técnica de contar una historia completa dentro de un rap: con personajes, escena, conflicto y desenlace, como un cuento o una película en miniatura. El MC no solo describe, narra: mete al oyente dentro de la situación (una noche en la calle, un golpe, una historia de amor o de fantasía) y la desarrolla a lo largo de los versos. Se diferencia del rap descriptivo o de opinión porque tiene trama: algo pasa, y la historia avanza.', importance: 'El storytelling demostró que el rap podía ser literatura oral: probó la profundidad del MCing, amplió los temas (del elogio de la fiesta al relato social, la crónica callejera y la ficción) y creó el formato que después explotarían generaciones enteras, del rap narrativo de los 90s al hip hop conceptual actual.', funFact: '"La Di Da Di" (1985), de Slick Rick y Doug E. Fresh, es uno de los temas narrativos más influyentes del rap: décadas después de su lanzamiento, el propio Slick Rick lo homenajea citando el título dentro de un tema con Mos Def ("Auditorium", del álbum *The Ecstatic*, 2009), un gesto documentado en la ficha del tema original.', related: ['FLOW', 'HOOK', 'MC', 'PUNCHLINE', 'RIMA', 'WORDPLAY'] } },
  { word: 'WORDPLAY', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Wordplay', description: 'El wordplay (juego de palabras) es el uso ingenioso del lenguaje para que las palabras signifiquen más de lo que parecen: dobles sentidos, homónimos, parónimos, refranes torcidos y metáforas que funcionan en dos niveles a la vez. En el rap es la materia prima de las frases memorables (ver `punchline`): una línea con wordplay suena bien, pero además esconde un segundo significado que el oyente descubre al escucharla de nuevo. Un ejemplo sencillo de elaboración propia: "Cambié la calle por el estudio: ahora estudio la calle".', importance: 'El wordplay convirtió al MC en poeta popular: demostró que el rap podía ser inteligente y divertido a la vez, y creó el estándar de que una buena línea debe pensarse, no solo oírse. Es la base de la punchline, del diss y de la rejugabilidad: una canción con wordplay se escucha de nuevo para cazar el segundo significado que se escapó la primera vez.', funFact: 'El término double entendre significa literalmente "oír doble" en francés, y los diccionarios lo definen como una expresión construida para entenderse de dos maneras: en el rap, una misma línea puede ser a la vez un elogio, una amenaza o un chiste, según cómo se lea.', related: ['BATTLE_RAP', 'DISS', 'METRICA', 'PUNCHLINE', 'RIMA', 'RIMAMULTI'] } },
  { word: 'BACKSPIN', category: 'djing', difficulty: 'medium', knowledge: { title: 'Backspin', description: 'El backspin es la técnica de girar el disco de vinilo hacia atrás con la mano —en contra del sentido de giro del plato— para volver al inicio de un fragmento y repetirlo. El sonido característico es el "swoosh" inverso de la aguja recorriendo el surco hacia atrás. Es el gesto que permite al DJ decir "esto se repite": volver al break una y otra vez sin soltar el pulso de la fiesta.', importance: 'El backspin es el gesto de la repetición: convierte un fragmento único en un loop y le da al DJ el poder de "rebobinar" la música en vivo. Sin backspin no habría breaks extendidos fluidos, y el breakbeat (ver `breakbeat`) como base del Hip Hop sería impensable.', funFact: 'En el baile y la fiesta jamaiquina el gesto equivalente es el "rewind" del selector: girar el disco hacia atrás cuando el público pide repetir un tema. En el Hip Hop, el backspin pasó de ser un gesto funcional a un sonido rítmico más del DJ.', related: ['BREAKBEAT', 'CUTTING', 'DJ_KOOL_HERC', 'EXTENDBREAK', 'FLASH', 'MERRYGOROUND', 'SCRATCHING', 'TURNTABLE'] } },
  { word: 'BEATJUGGLING', category: 'djing', difficulty: 'hard', knowledge: { title: 'Beat Juggling', description: 'El beat juggling es la técnica de manipular dos discos a la vez para recomponer los ritmos en vivo: el DJ no se limita a repetir un break, sino que combina fragmentos de batería de dos vinilos —unos segundos del kick de uno, la caja del otro, un hi-hat de un tercer punto— para construir patrones rítmicos nuevos que no existen en ningún disco. Es como armar un rompecabezas musical con las manos en pleno directo, a la velocidad de la fiesta.', importance: 'El beat juggling demostró que el DJ puede ser compositor: con dos discos y un crossfader crea música que ningún productor grabó. Es la prueba definitiva de que el tocadiscos es un instrumento, y el evento central de las batallas de turntablism modernas.', funFact: 'Steve Dee ganó la batalla del New Music Seminar en 1990 —el mismo año en que el término "turntablist" empezaba a circular— y su técnica de recomponer beats marcó a toda la generación de DJs de batalla de los 90.', related: ['BACKSPIN', 'BREAKBEAT', 'CUTTING', 'DJ_KOOL_HERC', 'FLASH', 'MIXER', 'TURNTABLE', 'TURNTABLISM'] } },
  { word: 'BLENDING', category: 'djing', difficulty: 'hard', knowledge: { title: 'Blending', description: 'El blending (fusión, mezcla armónica) es la variante avanzada del mixing que fusiona dos temas en armonía: además de sincronizar los tempos, el DJ elige discos en tonalidades compatibles para que, durante el cruce, ambos suenen como una sola pieza y no como dos canciones peleándose. Es lo que hace que una transición se sienta "natural" o incluso emocionante, en vez de simplemente correcta.', importance: 'El blending eleva la transición a composición: convierte al DJ en alguien que no solo encadena música, sino que la armoniza. Es la técnica que separa al DJ funcional del DJ que construye un viaje sonoro, y en el Hip Hop conecta el oficio del plato con el arte del remix y el mashup.', funFact: 'La rueda de Camelot (Mixed In Key, 2007) codifica las 24 tonalidades con un número y una letra para que el DJ combine temas sin saber teoría musical: mismo número y misma letra = compatibilidad total; subir o bajar un número = movimiento suave; el mismo número cambiando A/B = relativo mayor o menor.', related: ['DJ', 'DVS', 'MIXER', 'MIXING', 'MIXTAPE', 'TURNTABLE'] } },
  { word: 'BREAKBEAT', category: 'djing', difficulty: 'medium', knowledge: { title: 'Breakbeat', description: 'El breakbeat es la técnica de DJing que usa el break de un disco —la sección donde quedan la batería y el bajo solos— como base rítmica: en vez de tocar la canción completa, el DJ aísla ese fragmento y lo convierte en el suelo de la fiesta. Por extensión, también se llama breakbeat a la música construida sobre esos breaks. No hay que confundirlo con el break: el break es la sección del disco; el breakbeat es la técnica que la aprovecha.', importance: 'El breakbeat es el puente rítmico de toda la cultura: el MC rima sobre breakbeats, el b-boy baila breakbeats y el productor los samplea para construir beats. Es la técnica que convirtió al DJ en creador de música y, con el tiempo, el origen del sampling (ver `break` y `merry-go-round`).', funFact: 'El Amen break —unos seis segundos de batería de Gregory Coleman en "Amen, Brother" (The Winstons, 1969)— es uno de los fragmentos más sampleados de la historia: más de 1.800 usos documentados solo hasta 2015, y sus autores no recibieron un centavo en regalías.', related: ['BEATJUGGLING', 'BLOCK_PARTY', 'BREAK', 'DJ', 'DJ_KOOL_HERC', 'EXTENDBREAK', 'MERRYGOROUND', 'TURNTABLISM'] } },
  { word: 'CHIRP', category: 'djing', difficulty: 'hard', knowledge: { title: 'Chirp', description: 'El chirp es un scratch de dos movimientos por gesto: el disco avanza y retrocede, y en cada movimiento el crossfader se abre y se cierra dos veces, produciendo dos ráfagas cortas de sonido por pasada —un "chirp-chirp" agudo y seco, como el gorjeo de un pájaro o el sonido de un juguete. Se ejecuta con el fader en una mano y el vinilo en la otra, coordinando dos clics del fader por cada barrido del disco. Es uno de los scratches más veloces y precisos del turntablism.', importance: 'El chirp es la prueba de que el crossfader puede tocar a la velocidad de la mano: duplica las notas del scratch sin mover más el disco. Es un pilar del vocabulario del turntablism y la puerta a los scratches compuestos (combinaciones de chirp con flare, crab y transform).', funFact: 'El análisis espectrográfico del chirp (Hansen, 2010) confirma su estructura: dos clics del crossfader por cada barrido del disco, en repeticiones rápidas —el sonido "chirp-chirp" es literalmente el doble de notas por gesto.', related: ['FLARE', 'MIXER', 'SCRATCHING', 'TRANSFORM', 'TURNTABLE', 'TURNTABLISM'] } },
  { word: 'CUTTING', category: 'djing', difficulty: 'hard', knowledge: { title: 'Cutting', description: 'El cutting es la técnica de cortar el sonido del disco con el crossfader de la consola mientras el vinilo se mueve a mano: el DJ abre y cierra el paso de la señal en fracciones de segundo, partiendo el sonido del scratch en ráfagas rítmicas. Es el corte quirúrgico que da forma musical al scratch: sin el crossfader, el scratch es un rasguido; con el corte, se convierte en frase rítmica. Es la base técnica de la mayoría de los scratches modernos.', importance: 'El cutting es la otra mitad del scratch: el gesto de la mano crea el sonido, pero el crossfader le da ritmo, fraseo y articulación. Es la técnica que separa al DJ que solo mueve un disco del DJ que compone música en vivo, y la puerta de entrada a todo el vocabulario avanzado del turntablism.', funFact: '"Wheels of Steel" (1981), la grabación de Grandmaster Flash, es esencialmente un ejercicio de cutting: cortes quirúrgicos entre discos que demuestran que el crossfader puede ser tan musical como cualquier instrumento.', related: ['BACKSPIN', 'FLASH', 'MIXER', 'SCRATCHING', 'TRANSFORM', 'TURNTABLE', 'TURNTABLISM'] } },
  { word: 'DJ', category: 'djing', difficulty: 'easy', knowledge: { title: 'DJ', description: 'El DJ (disc jockey) es la persona que selecciona, pone y transforma música con tocadiscos y un mixer (mezclador). En el Hip Hop es la figura fundadora: de sus platos salen los breaks que bailan los b-boys y sobre los que riman los MCs. No es lo mismo que un beatmaker: el DJ actúa en vivo con discos, mientras que el beatmaker compone en estudio.', importance: 'El DJ es la columna vertebral del Hip Hop: sin DJ no hay break extendido, sin break no hay b-boy ni MC. Fue la primera disciplina de la cultura y la que les dio música a todas las demás, por eso los DJs pioneros están documentados como figuras fundacionales (ver `primeros-djs`).', funFact: 'El término "disc jockey" lo acuñó la prensa en 1935 para describir al locutor de radio Martin Block, que hacía creer a su audiencia que transmitía desde un salón de baile real: la figura del DJ nació como una ilusión de fiesta, décadas antes de que existiera el Hip Hop.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'BREAKBEAT', 'DJ_KOOL_HERC', 'FLASH', 'HERCULOIDS', 'HIP_HOP', 'MIXER', 'MIXING', 'PRIMEROSDJS', 'SEDGWICK73', 'TURNTABLE', 'TURNTABLISM', 'VINILO'] } },
  { word: 'DVS', category: 'djing', difficulty: 'hard', knowledge: { title: 'DVS (Sistema de vinilo digital)', description: 'Un DVS (Digital Vinyl System, sistema de vinilo digital) es un sistema que permite controlar archivos de música digital —MP3, WAV— usando tocadiscos y mixer de vinilo (ver `turntable`, `mixer`). En lugar de música, el disco lleva un timecode (código de tiempo): una señal grabada que le indica al computador dónde está la aguja, a qué velocidad gira y en qué dirección se mueve. El computador reproduce el archivo digital como si estuviera presionado en ese vinilo: el DJ hace exactamente lo de siempre —mezclar, frenar, raspar (ver `scratching`)— pero con una biblioteca digital entera al alcance de la mano.', importance: 'El DVS salvó al vinilo como instrumento en la era digital: sin él, el turntablism habría quedado limitado a una discoteca física finita. Democratizó el acceso a la música, cambió la logística del oficio —de cargar cajas de discos a llevar una laptop— y permitió que las técnicas del plato (ver `mixing`) sobrevivieran a la digitalización.', funFact: 'Final Scratch, el primer DVS comercializado, fue desarrollado por la empresa neerlandesa N2IT con la colaboración de los DJs Richie Hawtin y John Acquaviva, y salió al mercado a través de Stanton a comienzos de los años 2000.', related: ['DJ', 'MIXER', 'SCRATCHING', 'TURNTABLE', 'TURNTABLISM', 'VINILO'] } },
  { word: 'EXTENDBREAK', category: 'djing', difficulty: 'medium', knowledge: { title: 'Extended break', description: 'El extended break (break extendido) es la técnica de DJing que alarga la duración de un break: el DJ repite la misma sección rítmica del disco una y otra vez para que la base dure más que los pocos segundos que ocupa en el tema original. Es el primer "loop" de la historia del Hip Hop y se hace en vivo, sin grabación: con dos copias del mismo disco, los dedos y el crossfader del mixer (mezclador).', importance: 'El extended break es la técnica que creó la materia prima de la cultura: sin breaks extendidos no habría b-boys bailando minutos enteros, ni MCs rimando sobre una base estable, ni sampling posterior. Es el puente entre el DJ y el breaker, y el antepasado directo del loop en la producción musical.', funFact: 'Con dos copias del mismo disco y un crossfader, un break de pocos segundos podía repetirse indefinidamente: el público del Bronx bailaba sobre la misma sección rítmica durante minutos, mucho más de lo que dura en el tema original.', related: ['BEATJUGGLING', 'BLOCK_PARTY', 'BREAK', 'BREAKBEAT', 'DJ', 'DJ_KOOL_HERC', 'FLASH', 'MERRYGOROUND', 'TURNTABLISM'] } },
  { word: 'FLARE', category: 'djing', difficulty: 'hard', knowledge: { title: 'Flare', description: 'El flare es una técnica de scratch (raspado de disco) que combina el movimiento de la mano sobre el vinilo con golpes rápidos del crossfader del mixer (ver `mixer`). A diferencia del transform (ver `transform`), que empieza con el sonido cerrado y lo va abriendo, el flare empieza con el sonido abierto y lo corta en ráfagas, rebotando el fader contra el borde de su ranura. Cada golpe del fader se llama "clic", y los flares se nombran según cuántos clics haga el DJ en un solo movimiento del disco: flare de un clic, de dos clics, de tres…', importance: 'El flare elevó el scratch de efecto sonoro a lenguaje rítmico: con los flares, el DJ puede tocar patrones veloces y articulados, casi como un instrumento de percusión. Es una de las técnicas base del turntablism competitivo y de las rutinas de scratch de la generación de los 90 en adelante.', funFact: 'Los flares se nombran por la cantidad de clics: un flare de un clic produce dos sonidos en un solo movimiento del disco (sonido abierto, corte, cierre), y cada clic adicional multiplica las notas por movimiento de mano.', related: ['CHIRP', 'MIXER', 'SCRATCHING', 'TRANSFORM', 'TURNTABLISM'] } },
  { word: 'MERRYGOROUND', category: 'djing', difficulty: 'medium', knowledge: { title: 'Merry-Go-Round', description: 'El merry-go-round es la técnica de DJing que la escena atribuye a DJ Kool Herc: usar dos copias del mismo disco para repetir el break —la sección instrumental donde quedan la batería y el bajo— una y otra vez, sin que la música se detenga. Con ella, un break de pocos segundos se convertía en la base de toda la fiesta, y el público podía bailar el break el tiempo que quisiera.', importance: 'El merry-go-round es la técnica fundacional del DJing del Hip Hop: convirtió al DJ en creador de música —no solo reproductor de discos— y creó la materia prima del break dancing, ya que los b-boys bailaban sobre esos breaks extendidos. Sin el merry-go-round no existiría el breakbeat como base del Hip Hop, ni el turntablism posterior.', funFact: 'El merry-go-round convirtió un break de unos segundos en un loop infinito: el público del Bronx bailaba sobre la misma sección rítmica durante minutos. Es la técnica que conecta al DJ con el b-boy: el break extendido es lo que los bailarines esperaban para entrar al círculo.', related: ['BREAK', 'B_BOY', 'DJ_KOOL_HERC', 'FLASH', 'HIP_HOP'] } },
  { word: 'MIXER', category: 'djing', difficulty: 'easy', knowledge: { title: 'Mixer de DJ', description: 'El mixer (mezcladora) es la consola que recibe la señal de los tocadiscos (ver `turntable`) u otros reproductores, la combina y la envía a los parlantes. Sus controles básicos son los canales (uno por plato), los faders de volumen de cada canal, los controles de tono (bajos, medios y agudos) y el crossfader: la palanca que cruza el sonido de un canal al otro y permite cortar entre dos discos con un movimiento de muñeca. Sin mixer no hay DJing: es el puente entre los platos y el público, y el instrumento donde el DJ "toca".', importance: 'El mixer es lo que distingue al DJ de alguien que simplemente pone discos: permite mezclar sin cortes, dar forma al sonido y ejecutar las técnicas de scratch. Es el instrumento que hace posible el turntablism como disciplina.', funFact: 'El crossfader es la palanca que hace posible el scratching: técnicas como el transform o el flare consisten, en esencia, en abrir y cerrar ese fader en sincronía con el movimiento del disco.', related: ['DVS', 'FLASH', 'MIXING', 'SCRATCHING', 'TURNTABLE', 'TURNTABLISM'] } },
  { word: 'MIXING', category: 'djing', difficulty: 'medium', knowledge: { title: 'Mixing', description: 'El mixing (mezcla de discos) es la técnica básica del DJ: hacer pasar un disco a otro sin que la música se corte ni se rompa el ritmo. Para lograrlo, el DJ sincroniza el tempo de los dos temas —el beatmatching—, escucha el disco entrante con audífonos, lo suelta en el momento justo y desliza el crossfader del mixer (mezclador) para que el público solo perciba un cambio suave. Es la habilidad que convierte una lista de canciones en un set continuo.', importance: 'El mixing es la gramática mínima del DJ: sin él no hay set continuo, no hay blending ni transiciones, y la fiesta depende de silencios. En el Hip Hop, además, fue la puerta de entrada a las técnicas que definen la disciplina: el mismo gesto de sincronizar y cruzar discos permitió extender breaks y, más tarde, hacer beat juggling.', funFact: 'Francis Grasso popularizó el beatmatching en Nueva York hacia 1969: con dos tocadiscos y el control de velocidad, sincronizaba el tempo de dos discos para que la música nunca se detuviera, décadas antes de que existiera cualquier software.', related: ['BEATJUGGLING', 'BLENDING', 'BLOCK_PARTY', 'DJ', 'DVS', 'FLASH', 'MIXER', 'MIXTAPE', 'TURNTABLE'] } },
  { word: 'MIXTAPE', category: 'djing', difficulty: 'medium', knowledge: { title: 'Mixtape', description: 'Un mixtape es una grabación —originalmente en cassette— que compila música y muestra el arte del DJ: mezclas de temas, scratches, freestyles de MCs invitados y presentaciones habladas, todo enlazado sin cortes. Nació como producto callejero, grabado, copiado y vendido o regalado en la calle, y se convirtió en la tarjeta de presentación de los DJs (ver `dj`); con la digitalización pasó a distribuirse en línea. No es lo mismo que el álbum de un rapero: el mixtape lo protagoniza el DJ, o funciona como plataforma callejera de un MC, no sigue la estructura de un álbum de estudio y tradicionalmente no se vendía en tiendas.', importance: 'El mixtape fue el medio de difusión del DJing: llevó la jam a la calle, documentó las técnicas del oficio (mezclas, ver `mixing`; scratches) y fue la escalera de entrada de DJs y MCs a la industria. En la era digital sigue siendo el formato de la calle: lanzamiento directo, sin el filtro de la industria discográfica.', funFact: 'DJ Kid Capri lanzó "The Tape" a comienzos de los 90: una grabación de sus mezclas que se considera una de las mixtapes clásicas del hip hop de Nueva York (The Source la fecha el 19 de febrero de 1991).', related: ['DJ', 'DJ_KOOL_HERC', 'EXPANSION80S', 'FLASH', 'GRABACIONES', 'JAM', 'MIXING'] } },
  { word: 'SCRATCHING', category: 'djing', difficulty: 'medium', knowledge: { title: 'Scratching', description: 'El scratching es la técnica de mover un disco de vinilo hacia adelante y hacia atrás con la mano, mientras la aguja permanece en el surco, para producir un sonido rítmico rasgado: el famoso "wikka-wikka" del Hip Hop. El DJ convierte el tocadiscos en un instrumento de percusión, usando el crossfader de la consola para abrir y cerrar el paso del sonido y darle forma rítmica. Es la firma sonora del DJ y la base de todo el turntablism.', importance: 'El scratching cambió el rol del DJ: dejó de ser un reproductor de discos y se convirtió en instrumentista. Es el puente entre la reproducción y la creación musical, el gesto que convirtió al tocadiscos en un instrumento y que dio origen al turntablism (ver `turntablism`) como arte en sí mismo.', funFact: 'La primera grabación comercial en mostrar el scratching se atribuye a "The Adventures of Grandmaster Flash on the Wheels of Steel" (1981), un collage de técnicas de DJ que hizo visible al scratch para el público masivo; años antes, el sonido ya se escuchaba en las fiestas del Bronx.', related: ['BACKSPIN', 'CUTTING', 'FLASH', 'MIXER', 'THEODORE', 'TURNTABLE', 'TURNTABLISM', 'VINILO'] } },
  { word: 'TRANSFORM', category: 'djing', difficulty: 'hard', knowledge: { title: 'Transform', description: 'El transform es un scratch que suena como un robot transformándose: mientras el disco se mueve hacia adelante y hacia atrás, el DJ abre y cierra el crossfader varias veces en cada movimiento, partiendo el sonido en ráfagas cortas y mecánicas —el clásico "ch-ch-ch-ch". Es uno de los scratches más reconocibles del Hip Hop y el favorito de las batallas por su efecto dramático. Se ejecuta con el fader en una mano y el disco en la otra, en sincronía absoluta.', importance: 'El transform demostró que el crossfader puede tocar melodías rítmicas: transformó el scratch de efecto sonoro a frase musical estructurada. Es el scratch que llevó el DJing de Filadelfia a la fama mundial y la base de toda una familia de técnicas avanzadas.', funFact: 'El nombre del scratch viene de la caricatura The Transformers: el sonido "ch-ch-ch" del disco cortado por el fader imita el ruido de los robots al transformarse, y millones lo escucharon en el tema de apertura de "The Fresh Prince of Bel-Air".', related: ['CHIRP', 'CUTTING', 'FLASH', 'MIXER', 'SCRATCHING', 'TURNTABLE', 'TURNTABLISM'] } },
  { word: 'TURNTABLE', category: 'djing', difficulty: 'easy', knowledge: { title: 'Tocadiscos', description: 'El tocadiscos (turntable o plato) es el aparato que hace girar el vinilo (ver `vinilo`) y lo convierte en sonido: el plato gira a velocidad constante —33⅓ o 45 revoluciones por minuto—, la aguja lee los surcos del disco y el brazo transmite la vibración al equipo de sonido. Para el DJ, el plato no es un reproductor pasivo sino un instrumento: se puede frenar con la mano, hacerlo girar hacia atrás, empujarlo para acelerarlo y moverlo adelante y atrás para producir el scratch (ver `scratching`).', importance: 'El tocadiscos convirtió al DJ en músico: gracias al plato, la música grabada se volvió manipulable en vivo —repetir breaks, mezclar dos discos, raspar el vinilo—. Es el instrumento que define la disciplina del DJing y la base física del turntablism (ver `turntablism`).', funFact: 'El Technics SL-1200 salió a la venta en octubre de 1972; su versión MK2 (1979) se convirtió en el tocadiscos estándar de los DJs durante décadas. El motor de arrastre directo permite que el plato siga girando a velocidad constante aunque el DJ mueva el disco con la mano.', related: ['BREAK', 'DJ', 'DJ_KOOL_HERC', 'FLASH', 'MERRYGOROUND', 'MIXING', 'SCRATCHING', 'TURNTABLISM'] } },
  { word: 'TURNTABLISM', category: 'djing', difficulty: 'medium', knowledge: { title: 'Turntablism', description: 'El turntablism es la disciplina que trata al tocadiscos como un instrumento musical: en lugar de solo poner discos, el DJ los manipula con las manos y el mixer (mezclador) para crear sonidos, ritmos y música nueva. El nombre junta "turntable" (tocadiscos) con el sufijo de "virtuoso": el turntablist no pincha música, la toca.', importance: 'El turntablism redefinió el lugar del DJ en la cultura: de animador de fiestas a instrumentista con lenguaje propio, capaz de improvisar y dialogar con músicos de verdad. Mantuvo viva la tradición del DJ dentro del Hip Hop cuando el mainstream la había descartado, y su vocabulario (scratch, transform, beat juggling) alimentó después al beatmaking y al sampling.', funFact: 'El término "turntablist" se popularizó en 1995 cuando DJ Babu rotuló cientos de copias de su mixtape "Comprehension" con la firma "Babu the Turntablist" — pero el origen del término es discutido: DJ Disk, DJ Supreme y hasta Herbie Hancock (según GrandMixer DXT, en 1984) tienen versiones que compiten con la de Babu.', related: ['BEATJUGGLING', 'BREAKBEAT', 'DJ', 'DJ_KOOL_HERC', 'DVS', 'FLASH', 'MIXER', 'SCRATCHING', 'THEODORE', 'TRANSFORM', 'TURNTABLE'] } },
  { word: 'VINILO', category: 'djing', difficulty: 'easy', knowledge: { title: 'Vinilo', description: 'El vinilo es el disco físico —hecho de cloruro de polivinilo— en el que se grabó la música durante décadas: un plato de 7, 10 o 12 pulgadas con surcos que la aguja lee mientras gira a 33⅓ o 45 revoluciones por minuto. Para el DJ no es solo el soporte de la música: es la superficie que se toca con la mano, se frena, se retrocede y se raspa, y la duración de sus caras determina qué secciones se pueden repetir (los breaks, ver `break`).', importance: 'El vinilo definió las reglas del DJing: la duración de los breaks, la posibilidad de manipular la aguja y la relación física y sonora con la música. La cultura de buscar discos (crate digging) y buena parte del sampling nacen de la relación del DJ con el vinilo.', funFact: 'El primer sencillo comercial de 12 pulgadas fue "Ten Percent" de Double Exposure, en el remix de Walter Gibbons para Salsoul Records (1976): el formato disco que luego adoptó el rap para sus lanzamientos.', related: ['BACKSPIN', 'BREAK', 'BREAKBEAT', 'DJ_KOOL_HERC', 'EXTENDBREAK', 'GRABACIONES', 'RAPDELIGHT', 'TURNTABLE'] } },
  { word: 'BLACKBOOK', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Blackbook', description: 'El blackbook (cuaderno de bocetos) es el cuaderno personal del writer, donde practica, desarrolla y archiva su estilo antes de llevarlo a la calle. Los glosarios de la escena lo definen como el cuaderno para planificar, desarrollar estilos y coleccionar tags. Es a la vez taller y museo personal: en sus páginas se ensayan handstyles (ver `handstyle`), se diseñan piezas completas (ver `piece`) con sus outlines y fills (ver `outline` y `fill`), y se guardan las firmas que otros writers le dejan como intercambio de respeto.', importance: 'El blackbook es la prueba de que el writing es una disciplina: el estilo no nace en el muro, se construye en el cuaderno. Como archivo, conserva la memoria de la escena —firmas, estilos, épocas— y como práctica, es la escuela donde cada writer se hace dueño de su letra.', funFact: 'El blackbook es el cuaderno de bocetos del writer: laboratorio del estilo propio y archivo de firmas ajenas, ya que el intercambio clásico entre writers es firmarse el cuaderno mutuamente.', related: ['FILL', 'HANDSTYLE', 'OUTLINE', 'PIECE', 'TAG', 'WRITER'] } },
  { word: 'BOMBING', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Bombing', description: 'El bombing (bombardeo) es la práctica de pintar la mayor cantidad de lugares posible en el menor tiempo: tags y throw-ups (ver `tag`, `throw-up`) repetidos por toda la ciudad, en superficies visibles y de riesgo. En el bombing, la cantidad y la velocidad importan más que la calidad: se trata de bombardear la ciudad con tu firma hasta que sea imposible no verla.', importance: 'El bombing definió la lógica de fama del writing: demostró que en el graffiti, estar en todos lados es una forma de poder. Es también el lado más arriesgado de la disciplina y el que más confronta al sistema.', funFact: 'En el bombing no se busca la pieza perfecta: un writer puede hacer decenas de tags y throw-ups en una sola noche; la fama se mide en kilómetros de ciudad cubiertos.', related: ['CREW', 'PIECE', 'TAG', 'THROW_UP', 'WRITERS70'] } },
  { word: 'BUBBLE', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Bubble Letters (Letras Burbuja)', description: 'Las bubble letters (letras burbuja) son letras redondeadas, infladas y de trazo grueso y uniforme, sin esquinas afiladas. Son el alfabeto del throw-up (ver `throw-up`) y un paso clásico del aprendizaje del writing (ver `writer`): fáciles de leer, rápidas de pintar y, aun así, difíciles de dominar bien. Se distinguen del handstyle (ver `handstyle`), que es la firma fluida y personal del tag (ver `tag`), y del wildstyle (ver `wildstyle`), que lleva la letra a la complejidad extrema.', importance: 'Las letras burbuja son el puente entre la firma y la pieza: enseñan a pensar la letra como forma rellenable y le dieron al writing su formato más democrático, el throw-up. Su influencia se ve desde los vagones del metro neoyorquino hasta la estética del grafiti comercial contemporáneo.', funFact: 'Las bubble letters se atribuyen a Phase 2 (fines de 1972, Bronx), que las llamaba "softies"; el estilo es la base del throw-up y, por lo general, el primer alfabeto del writer principiante.', related: ['HANDSTYLE', 'PIECE', 'TAG', 'THROW_UP', 'WILDSTYLE'] } },
  { word: 'BURNER', category: 'graffiti', difficulty: 'hard', knowledge: { title: 'Burner', description: 'El burner (quemador) es la pieza (ver `piece`) de máxima calidad: una obra a color donde el writer despliega su mejor letra, color, técnica y composición para superar a todos los demás. No es un formato distinto del piece, sino su nivel más alto: la pieza que "quema" (burn) a las demás, la que deja claro quién manda en la pared o en el vagón.', importance: 'El burner representa el estándar de excelencia del writing: la prueba de que el graffiti es una disciplina con niveles, donde el estilo, el color y la técnica se entrenan como en cualquier arte.', funFact: 'En la jerga, "he burned it" ("la quemó") significa que un writer hizo una pieza tan superior que opaca a todas las demás: de ahí viene el nombre del burner.', related: ['BOMBING', 'PIECE', 'WHOLECAR', 'WILDSTYLE', 'WRITERSHIST'] } },
  { word: 'CAN', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'Can (Lata)', description: 'El can (lata) es la lata de pintura en aerosol, la herramienta central del writing: pintura envasada a presión que se libera como spray fino al pulsar la válvula. Su portabilidad, permanencia y velocidad la convirtieron en el soporte ideal del graffiti callejero: cabe en una mochila, seca rápido, cubre grande y deja marca duradera. El trazo lo define el cap (ver `cap`), la boquilla intercambiable que se monta sobre la válvula.', importance: 'La lata es lo que hace posible el writing como se conoce: sin aerosol no habría throw-ups ni piezas en muros y trenes. Su baratura, portabilidad y permanencia definieron la estética del graffiti —trazo, color, escala— y la economía de la escena: la producción masiva del bombing.', funFact: 'La pintura en aerosol comercial nació en 1949 (Edward Seymour, EE. UU.); dentro de la lata, la "pea" mezcla la pintura al agitar, y la presión alta cubre rápido mientras la baja da control.', related: ['BOMBING', 'CAP', 'PIECE', 'TAG', 'THROW_UP'] } },
  { word: 'CAP', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Cap (Boquilla)', description: 'El cap (boquilla) es la pieza intercambiable que se coloca sobre la válvula de la lata de spray (ver `can`) y determina el ancho y la forma del trazo. Cambiando el cap se pasa de una línea fina de precisión a un chorro ancho de relleno sin cambiar de lata: es la pieza que convierte un aerosol común en una herramienta de dibujo. En la escena del writing se llama "cap"; técnicamente es el actuador (actuator) del aerosol.', importance: 'El cap es la herramienta que define el estilo de trazo: con el mismo aerosol, un cap distinto cambia por completo el resultado. Dominar los caps —elegir el ancho justo para cada línea y cada relleno— es parte del oficio del writer y del "can control" que distingue al principiante del maestro.', funFact: '"Cap" es el término de la escena para el actuador del aerosol: los caps finos (skinny) dan precisión para outlines, los anchos (fat) dan velocidad para rellenos, y los de caligrafía producen un trazo en abanico plano.', related: ['CAN', 'FILL', 'OUTLINE', 'PIECE', 'THROW_UP'] } },
  { word: 'CREW_WRITER', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'Crew de Graffiti', description: 'Una crew de graffiti es un grupo de writers que pinta junto bajo un nombre compartido: una identidad colectiva que se firma junto al tag individual (ver `tag`). La crew reúne a writers de distintos niveles —desde principiantes hasta maestros— que se protegen, se enseñan y compiten como equipo. Es la forma específica que toma en el writing el concepto transversal de crew del Hip Hop (ver `crew`).', importance: 'La crew es la unidad de trabajo y pertenencia del writer: define con quién se pinta, bajo qué nombre y con qué código. Entenderla es entender la dimensión colectiva del writing, donde el logro individual —el tag, la pieza— casi siempre se apoya en un grupo con nombre propio.', funFact: 'La crew de writers es la misma institución social que la crew de b-boys o la crew de MCs (ver `crew`): grupo con nombre, identidad y lealtad, aplicado a la escritura callejera.', related: ['BOMBING', 'CODIGO', 'CREW', 'PIECE', 'TAG', 'WRITERS70'] } },
  { word: 'FILL', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Fill (Relleno)', description: 'El fill (relleno, fill-in) es el color que llena el interior de las letras de un graffiti: la superficie que queda dentro del contorno (ver `outline`). Es la segunda capa básica de la pieza (ver `piece`), después del contorno y antes del fondo. En su forma mínima —un solo color— es la mitad del throw-up clásico (ver `throw-up`); en su forma máxima, es el espacio donde el writer despliega color, técnica y creatividad.', importance: 'El relleno es donde el color se vuelve estilo: decide la legibilidad de la letra, el impacto visual de la pieza y la impresión de dominio técnico. Un piece sin buen relleno es solo un contorno prometedor.', funFact: 'El fill-in es la superficie de color dentro del contorno: en el throw-up es un solo color plano; en la pieza puede llevar fades, patrones, brillos y los "bits and doodads" que popularizó SEEN en Style Wars (1983).', related: ['BLACKBOOK', 'BURNER', 'OUTLINE', 'PIECE', 'THROW_UP'] } },
  { word: 'HANDSTYLE', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Handstyle', description: 'El handstyle (estilo de mano) es la caligrafía personal del tag: la manera particular en que un writer dibuja las letras de su firma a mano alzada, con trazos rápidos, presión y personalidad. Es el equivalente a la firma manuscrita y la primera señal de identidad de un writer: antes de dominar colores y piezas, hay que dominar la letra. Un buen handstyle se reconoce a la distancia, incluso si no se alcanza a leer el nombre.', importance: 'El handstyle es la firma de la firma: el sello que hace único a cada writer y que sostiene todo el sistema de estilos del writing. Sin handstyle no hay tag memorable, y sin tag no hay piece.', funFact: 'El handstyle es el nivel más básico y a la vez el más difícil de perfeccionar: la mayoría de los writers pasan años practicando su firma en papel antes de llevarla a la pared, porque una letra floja delata al principiante.', related: ['PIECE', 'TAG', 'THROW_UP', 'WILDSTYLE', 'WRITERS70'] } },
  { word: 'HEAVEN', category: 'graffiti', difficulty: 'hard', knowledge: { title: 'Heaven', description: 'El heaven (o heaven spot, literalmente "lugar celestial") es el término del writing (graffiti de firma) para los lugares casi imposibles de alcanzar: azoteas, techos, marquesinas, carteles publicitarios, estructuras de puentes y zonas elevadas sobre las vías del tren. Hacer un tag o un piece en un heaven es la apuesta máxima del writer: subir, pintar rápido y bajar sin que nadie lo vea. La dificultad del acceso es parte de la obra: cuanto más imposible el lugar, más respeto gana el nombre.', importance: 'El heaven condensa el código del writing: riesgo, visibilidad y permanencia. Separa al writer comprometido del que pinta solo donde es cómodo, y convierte el tag —la forma más simple del graffiti— en una hazaña respetada por toda la escena. Es, junto con el bombing (ver `bombing`), la demostración de que en el writing el valor no se pinta: se conquista.', funFact: 'Un heaven spot no se elige por lo que se ve desde la calle, sino por lo que se ve desde donde nadie puede subir a borrarlo: cuanto más alto y más expuesto el lugar, más tiempo dura el nombre del writer.', related: ['BOMBING', 'HANDSTYLE', 'TAG', 'WRITERS70', 'WRITERSHIST'] } },
  { word: 'KING', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'King (Rey del Metro)', description: 'El king (rey) es el writer que domina un territorio del writing: una línea de tren, un barrio o un estilo. En el metro de Nueva York, el título más codiciado era el de "king of the line": el writer con más y mejores piezas en una línea completa de vagones. El rey no se autoproclama: la escena se lo reconoce por producción, estilo y constancia, y su nombre se convierte en referencia obligada del lugar (ver `writer`).', importance: 'El rey es la prueba viviente de que en el writing el estatus se construye: nadie nace rey, se llega con producción y estilo. La jerarquía king/toy estructura la competencia de la escena y explica su motor: la búsqueda de respeto entre pares.', funFact: '"King of the line" es el título documentado del writer que domina una línea de tren: el más presente y de mejor nivel en ese territorio; algunos reyes añadían una corona junto a su nombre.', related: ['BOMBING', 'TAG', 'TOY', 'WHOLECAR', 'WRITER', 'WRITERSHIST'] } },
  { word: 'MURAL', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'Mural', description: 'El mural es la obra de graffiti de gran escala pintada sobre una pared, generalmente con permiso o por encargo: el formato legal del writing (graffiti de firma). A diferencia del bombing —pintar rápido, sin permiso y con riesgo (ver `bombing`)—, el mural se hace a la vista, con tiempo y a veces con pago. El artista pinta durante horas o días, y la pared le pertenece mientras la obra dure. Es la puerta por la que el graffiti salió de la ilegalidad sin perder su carácter de arte público.', importance: 'El mural demostró que el graffiti podía ser arte público reconocido y dio a los writers una carrera posible: del riesgo de la noche al encargo del día. Para la cultura Hip Hop, es la prueba de que el writing no era solo vandalismo: era un lenguaje visual con algo que decir, y el mural le dio la pared para decirlo.', funFact: 'En el mural el tiempo de trabajo se mide en horas o días; en el bombing, en segundos. La diferencia no es solo legal: es también técnica, de relación con el lugar y de relación con el público que verá la obra terminada.', related: ['BOMBING', 'HEAVEN', 'HIP_HOP', 'PIECE', 'WRITERSHIST'] } },
  { word: 'OUTLINE', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Outline (Contorno)', description: 'El outline (contorno) es la línea que define el borde de las letras en un graffiti: el trazo que dibuja la forma y separa la letra del fondo. Es la columna vertebral del piece (ver `piece`): sin contorno no hay letra legible. En el throw-up (ver `throw-up`), el outline es el trazo que cierra la pieza sobre el relleno (ver `fill`); en la pieza a color, puede ser simple —una línea negra clásica— o doble, con colores y efectos.', importance: 'El outline es lo que hace legible y potente a la letra: define la forma, sostiene el color del relleno y conecta la pieza con su fondo. Un buen contorno —limpio, parejo, con el grosor justo— es la firma de un writer maduro.', funFact: 'El outline es la línea que define y cierra la letra: se dibuja primero como guía y se repasa al final sobre el relleno; sin relleno, un throw-up solo con contorno se llama "hollow" (hueco).', related: ['FILL', 'PIECE', 'TAG', 'THROW_UP', 'WILDSTYLE'] } },
  { word: 'PIECE', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Piece', description: 'El piece (abreviación de masterpiece, "obra maestra") es el graffiti grande y a color: letras estilizadas, a veces con personajes, sombras y fondos, que pueden tomar horas o días. Es el formato más ambicioso del writing, el que muestra el nivel real de un writer: manejo de la letra (ver `handstyle`), del color y de la composición. Mientras el tag (ver `tag`) es la firma y el throw-up (ver `throw-up`) la producción rápida, el piece es la obra.', importance: 'El piece elevó el writing de firma callejera a arte visual: demostró que la letra podía ser pintura, color y composición, y abrió el camino del graffiti a la galería y al mural.', funFact: '"Piece" viene de "masterpiece" (obra maestra): los writers del metro llamaron así a sus obras grandes a color para distinguirlas de los simples tags y throw-ups.', related: ['BURNER', 'MURAL', 'TAG', 'THROW_UP', 'WHOLECAR', 'WILDSTYLE'] } },
  { word: 'TAG', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'Tag', description: 'El tag (firma) es la escritura del propio nombre o apodo —a veces acompañado del número de la calle— con un estilo de letra propio, hecho con rotulador o pintura en aerosol. Es la forma más básica y original del writing (graffiti): la firma con la que un writer deja su marca en la ciudad. Todo writer tiene un tag; es su identidad visual.', importance: 'El tag es el origen de toda la disciplina visual del Hip Hop: demostró que la firma personal podía ser arte, fama y comunicación. Los valores centrales del writing —estilo propio, visibilidad, competencia— nacieron del tag.', funFact: 'TAKI 183 tiene el tag más famoso de la historia documentada: su firma en los muros y el metro de Nueva York provocó el artículo del New York Times del 21 de julio de 1971, la primera cobertura de prensa importante del graffiti.', related: ['BRONX', 'CREW', 'HANDSTYLE', 'HIP_HOP', 'WRITERS70'] } },
  { word: 'THROW_UP', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Throw-up', description: 'El throw-up (throwie) es un formato rápido de graffiti de una o dos palabras, con letras burbuja (bubble letters) redondeadas y rellenas, hecho con un solo contorno (outline) y un solo color de relleno (fill-in), en minutos o incluso segundos. Es el punto intermedio entre el tag (ver `tag`) y la pieza completa (ver `piece`): más grande y visible que la firma, pero mucho más rápido que una obra a color.', importance: 'El throw-up democratizó el writing: permitió producir mucho, rápido y con estilo. Es la prueba de que en el graffiti la cantidad también es una estrategia artística (ver `bombing`).', funFact: 'Un throw-up clásico se compone de apenas dos colores: el contorno (outline) y el relleno (fill-in). Sin sombras, sin fondos, sin efectos: pura velocidad y estilo.', related: ['BOMBING', 'HANDSTYLE', 'PIECE', 'TAG', 'WRITERS70'] } },
  { word: 'TOY', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Toy (Principiante)', description: 'El toy es el principiante o imitador del writing: el writer sin estilo propio, que copia a otros ("biting"), pinta mal o desconoce el código de la escena. El término se usa como descripción y como insulto: llamar a alguien "toy" es decirle que no tiene nivel ni respeto ganado. Es el opuesto del king (ver `king`): mientras el rey domina por producción y estilo, el toy se define por lo que le falta —mano propia, criterio y obra—.', importance: 'El término toy delata el sistema de valores del writing: el respeto no se regala, se gana con estilo propio. La tensión king/toy es el motor de la competencia que empuja a los writers a mejorar su letra, su mano y su obra.', funFact: '"Toy" designa al principiante o imitador, y su falta típica es el "biting": copiar el estilo de otro writer, considerado por los glosarios de la escena como altamente irrespetuoso.', related: ['CODIGO', 'HANDSTYLE', 'KING', 'TAG', 'WRITER'] } },
  { word: 'WHOLECAR', category: 'graffiti', difficulty: 'hard', knowledge: { title: 'Whole car', description: 'El whole car ("coche entero") es la pieza de graffiti que cubre el largo total de un vagón de metro como una sola obra continua: letras, colores y a veces personajes, pintados de punta a punta del coche en un único diseño. Fue el hito máximo de la era de los trenes de Nueva York: el nombre del writer viajando por toda la ciudad como una galería rodante. Antes de que existieran el internet o las redes sociales, el whole car era la forma más grande que existía de mostrar una firma al mundo.', importance: 'El whole car elevó el writing a la escala de obra pública: por primera vez, una firma callejera se movía por toda una ciudad, vista por millones. Definió el sueño de toda una generación de writers y marcó el pico del graffiti como arte antes de la represión sistemática. Ningún otro formato del writing (ver `bombing`) logró esa combinación de escala, movimiento y audiencia.', funFact: 'En la era de los trenes, un whole car no se exhibía en una pared: se movía. Un solo vagón pintado de punta a punta recorría toda la red de metro de Nueva York, convirtiendo la firma del writer en una obra en movimiento vista por toda la ciudad.', related: ['BOMBING', 'BURNER', 'PIECE', 'TAG', 'WILDSTYLE', 'WRITERS70', 'WRITERSHIST'] } },
  { word: 'WILDSTYLE', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Wildstyle', description: 'El wildstyle (estilo salvaje) es el estilo de letra más complejo del writing: letras entrelazadas, alargadas, con flechas, remolinos y conexiones que se funden entre sí hasta volverse casi ilegibles para quien no es de la cultura. Es la máxima expresión del estilo de letra: el handstyle (ver `handstyle`) llevado al límite, donde la forma domina sobre la lectura. Solo los iniciados pueden descifrar un wildstyle.', importance: 'El wildstyle demostró que el writing podía ser un lenguaje propio: una escritura que no busca ser leída por cualquiera, sino admirada y descifrada por los iniciados. Es el símbolo de la sofisticación del graffiti.', funFact: 'El wildstyle es tan difícil de leer que los writers hablan de "canon": el conjunto de reglas no escritas que permite a los iniciados descifrar letras que para el resto parecen un nudo de líneas y colores.', related: ['BURNER', 'HANDSTYLE', 'PIECE', 'TAG', 'WRITERS70', 'WRITERSHIST'] } },
  { word: 'WRITER', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'Writer (Escritor)', description: 'El writer (escritor) es la persona que practica el writing: la disciplina de pintar letras, nombre y estilo propio en muros, trenes y superficies urbanas. Los practicantes llaman a su actividad "writing" (escribir), no "graffiti", término que popularizó un ensayo de Norman Mailer en 1974 y que muchos writers rechazan por su carga judicial. El writer no se considera un "artista de graffiti" sino un escritor: alguien que compite por estilo, visibilidad y respeto dentro del código de la escena (ver `codigo`).', importance: 'El writer es el sujeto del writing: sin writers no hay tags, ni piezas, ni crews, ni la competencia de estilos que define a la disciplina. La palabra misma ("writer", no "artista") dice cómo la cultura se ve a sí misma: una escritura callejera que compite por estilo y respeto.', funFact: 'Los practicantes del graffiti se llaman a sí mismos "writers" y a su práctica "writing": el término "graffiti" fue popularizado por el ensayo de Norman Mailer (1974) y muchos lo rechazan.', related: ['BOMBING', 'HANDSTYLE', 'PIECE', 'TAG', 'WRITERS70', 'WRITERSHIST'] } },
  { word: 'WRITERSHIST', category: 'graffiti', difficulty: 'medium', knowledge: { title: 'Writers Históricos', description: 'Los writers históricos son los protagonistas que convirtieron el writing (graffiti) en una disciplina del Hip Hop: de los pioneros del tag (ver `primeros-writers`) a la generación que en los años 70 y 80 llevó el graffiti del muro al vagón entero (ver `wholecar`) y de la calle a la galería. Nombres como TAKI 183, Julio 204, Phase 2, Lee Quiñones, Lady Pink, Blade y Seen definieron los estilos, los formatos (ver `tag`, `piece`) y la fama de la escena neoyorquina.', importance: 'Esta generación fijó los cimientos del writing: los formatos, los estilos, los códigos de fama y el paso del vandalismo al arte. Sin ellos, el graffiti no sería la disciplina visual del Hip Hop ni habría llegado a museos y galerías.', funFact: 'La era dorada terminó cuando el metro de Nueva York selló las cocheras de vagones a fines de los 80; muchos de esos writers históricos pasaron al arte de galería y al mural, pero su fama sigue siendo la medida de todo writer actual.', related: ['BOMBING', 'CREW', 'PIECE', 'TAG', 'WHOLECAR', 'WRITERS70'] } },
  { word: 'B_BOY', category: 'breaking', difficulty: 'easy', knowledge: { title: 'B-Boy', description: 'El b-boy es el bailarín de breaking, la disciplina de baile del Hip Hop. El término nació en el Bronx de los años 70 para nombrar a los que bailaban en el break de los discos, y con el tiempo se convirtió también en una identidad: el b-boy como parte de la cultura, con su estilo, su crew y su código.', importance: 'El b-boy es una de las identidades fundacionales del Hip Hop: demuestra que la cultura nació del cuerpo y la calle, no solo de la música. La búsqueda de estilo y originalidad del b-boy —"no copiar, crear lo propio"— es un valor que la cultura repite en todas sus disciplinas.', funFact: 'El b-boy baila "en el break": su nombre conecta directamente con la técnica del DJ de alargar los breaks, el eslabón musical del nacimiento del Hip Hop.', related: ['BLOCK_PARTY', 'BREAK', 'DJ_KOOL_HERC', 'HIP_HOP'] } },
  { word: 'BATTLE', category: 'breaking', difficulty: 'easy', knowledge: { title: 'Battle', description: 'La battle (batalla) es el formato competitivo del breaking: dos b-boys o dos crews se enfrentan por turnos en el círculo (ver `cypher`), bailando para superar al rival ante el público, que reacciona como juez. Se compite con vocabulario, estilo, musicality y power moves; no hay contacto físico: la respuesta se baila. Es la forma original de competencia del baile y sigue siendo su corazón.', importance: 'La battle es el motor del breaking: impulsa la evolución técnica, premia la originalidad y el estilo (ver `style`) y mantiene viva la competencia cara a cara como valor central de la cultura. Sin batallas, el breaking sería exhibición; con ellas, es un diálogo físico donde el respeto se gana bailando, frente a los pares y sin escenario que proteja.', funFact: 'El breaking debutó como deporte olímpico en los Juegos de París 2024, con batallas de uno contra uno juzgadas por un panel: el mismo formato competitivo que la cultura venía practicando en el círculo desde los años 70.', related: ['BATTLE_RAP', 'BREAK', 'B_BOY', 'CYPHER', 'JAM', 'ROCKSTEADY'] } },
  { word: 'FOOTWORK', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Footwork', description: 'El footwork (también llamado downrock, "trabajo de pies") es la parte del breaking que se baila en el suelo: las manos y los pies se mueven en patrones circulares y rápidos alrededor del cuerpo, con las piernas abiertas y el peso repartido entre manos y pies. El patrón base es el six-step (paso de seis): seis movimientos de pies en círculo que ordenan todo el vocabulario del footwork (ver `six-step`). Es el corazón técnico del breaking: donde se mide la velocidad, el control y la limpieza del b-boy.', importance: 'El footwork es el vocabulario del b-boy: sin footwork no hay breaking, porque es la base sobre la que se construyen los freezes (ver `freeze`) y desde la que se entra y se sale de los power moves. Define el estilo individual, es el terreno donde se gana el respeto en el cypher y sigue siendo el primer entrenamiento de todo principiante.', funFact: 'El six-step se llama así porque ordena seis posiciones de los pies en un círculo: es el primer rito de todo b-boy, y sobre ese círculo se construyen decenas de variaciones y casi todo el resto del footwork.', related: ['BATTLE', 'B_BOY', 'FREEZE', 'ROCKSTEADY', 'SIX_STEP', 'TOPROCK'] } },
  { word: 'FOUNDATION', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Foundation', description: 'La foundation (fundamento, "la base") es el conjunto de movimientos básicos del breaking que todo b-boy debe dominar antes de desarrollar su estilo propio: los pasos de pie (toprock), el trabajo de suelo (footwork), los movimientos de potencia (power moves) y las poses congeladas (freezes). No es un movimiento puntual, sino el vocabulario mínimo de la disciplina: la gramática sobre la que se construye todo lo demás.', importance: 'La foundation es lo que hace del breaking una disciplina y no una colección de trucos: garantiza que el b-boy pueda bailar con control, musicalidad y durabilidad física, y que el estilo propio (ver `style`) se construya sobre terreno firme. En las competencias modernas, los criterios de juicio incluyen explícitamente el dominio de la base, lo que mantiene viva la idea de la vieja escuela: primero se aprende a caminar en el suelo, después se vuela.', funFact: 'El six-step —la caminata de seis pasos en círculo— es el movimiento de foundation más conocido y el primer paso de footwork que aprende casi todo b-boy (tradición oral de la pedagogía del breaking).', related: ['B_BOY', 'FOOTWORK', 'FREEZE', 'POWER', 'ROCKSTEADY', 'SIX_STEP', 'TOPROCK'] } },
  { word: 'FREEZE', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Freeze', description: 'El freeze (literalmente "congelar") es la pose estática con la que el b-boy o la b-girl remata una secuencia: en pleno movimiento, el cuerpo se detiene de golpe en una posición sostenida —sobre las manos, la cabeza, los codos o los hombros— y se queda inmóvil un instante. Es el "punto final de la frase" del breaking: sin freeze, la secuencia no termina, se apaga. Además de control físico, el freeze es actitud: la pose congelada mira al rival o al público y dice "ahí quedó".', importance: 'El freeze convierte el baile en frase: da forma y remate a la secuencia y es la firma de estilo del b-boy. En el battle, un buen freeze es un golpe de efecto que define el momento en que el bailarín "gana" el round ante el público; en el cypher, es la prueba de que el movimiento no se improvisa, se controla.', funFact: 'Cuanto más difícil la pose —menos puntos de apoyo, más equilibrio invertido— más contundente el remate: el freeze más celebrado no es el más largo, sino el más limpio, el que se sostiene perfectamente inmóvil en el momento exacto.', related: ['BATTLE', 'B_BOY', 'FOOTWORK', 'POWER', 'ROCKSTEADY', 'TOPROCK'] } },
  { word: 'HEADSPIN', category: 'breaking', difficulty: 'hard', knowledge: { title: 'Headspin', description: 'El headspin (giro de cabeza) es el movimiento más icónico del breaking: el b-boy invierte el cuerpo, apoya la cabeza en el suelo y gira sobre ella, con las piernas abiertas en el aire o recogidas, manteniendo el equilibrio solo con el cuello y la corona del cráneo. Es un power move de alto impacto visual y físico.', importance: 'El headspin es la postal del breaking: el movimiento que el mundo entero reconoce como símbolo de la disciplina y la prueba física de hasta dónde lleva el b-boy su cuerpo. Su exigencia técnica y su riesgo físico lo convirtieron también en un límite que cada bailarín negocia consigo mismo —qué tan lejos llevar el giro—, un dilema que forma parte de la cultura del power move.', funFact: 'El headspin es uno de los movimientos más reproducidos del breaking en cine, televisión y publicidad desde los años 80, más que ningún otro movimiento de la disciplina.', related: ['BATTLE', 'B_BOY', 'POWER', 'ROCKSTEADY'] } },
  { word: 'MUSICALITY', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Musicality', description: 'La musicality (musicalidad) es la capacidad del b-boy de bailar conectado con la música: entrar en el momento exacto del break, caer en el beat (a tiempo), frenar en seco cuando la base se corta y subrayar con el cuerpo los acentos de la batería. Es lo que separa al que ejecuta trucos del que realmente baila.', importance: 'La musicality es el puente entre el b-boy y el DJ: recuerda que el breaking no es gimnasia sino baile, y que la disciplina nació de una sección de batería repetida sin parar. Un b-boy con musicality puede bailar poco y emocionar; sin ella, los trucos más difíciles quedan vacíos.', funFact: 'El b-boy baila "en el break": su nombre mismo viene de bailar en la sección rítmica que el DJ alargaba (ver `b-boy`), y la musicality es la heredera directa de ese origen.', related: ['BREAK', 'BREAKBEAT', 'B_BOY', 'DJ', 'JAM'] } },
  { word: 'POWER', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Power moves', description: 'Los power moves ("movimientos de poder") son el grupo de movimientos acrobáticos del breaking basados en la fuerza, el impulso y la rotación: el cuerpo gira sobre la espalda, la cabeza, las manos o los codos sin detenerse. Los clásicos son el windmill (el "molino": giro continuo sobre la espalda y los hombros, ver `windmill`), el headspin (giro sobre la cabeza, ver `headspin`) y el flare (balanceo de piernas abiertas sin tocar el suelo), entre muchos otros. Es la parte más espectacular del breaking y la que el público recuerda: cuando suena el power, la gente deja de mirar el teléfono.', importance: 'El power cambió la percepción del breaking: de baile de barrio a disciplina atlética con reconocimiento mundial, y definió la imagen del b-boy de los 80 en la cultura popular. Es el puente entre el breaking y el deporte de alto rendimiento, y el elemento que convirtió el cypher en espectáculo: cuando el b-boy gira, la cultura entera se muestra en su versión más física.', funFact: 'El power move más conocido es el windmill: un giro continuo que pasa por la espalda y los hombros sin que los pies toquen el suelo, y que en manos de un b-boy avanzado se encadena con otros power moves en una misma vuelta, sin parar el giro.', related: ['BATTLE', 'B_BOY', 'FOOTWORK', 'FREEZE', 'HEADSPIN', 'ROCKSTEADY', 'WINDMILL'] } },
  { word: 'ROCKSTEADY', category: 'breaking', difficulty: 'easy', knowledge: { title: 'Rock Steady Crew', description: 'La Rock Steady Crew es la crew de breaking más famosa de la historia del Hip Hop: nació en el Bronx en los años 70 y se hizo mundial en los 80 gracias a sus batallas, sus apariciones en cine y televisión y su estilo acrobático. Sus integrantes de la primera generación —Crazy Legs, Ken Swift, Frosty Freeze, Mr. Freeze, entre otros— son los nombres que definieron el breaking como disciplina.', importance: 'La Rock Steady Crew convirtió el breaking de calle en una disciplina reconocida mundialmente: sus batallas, sus videos y sus apariciones en cine le dieron al baile una visibilidad que ninguna otra crew logró. Además, su historia condensa valores centrales de la cultura: lealtad a la crew, competencia en el círculo y la idea de que el estilo se gana bailando, no declarándose.', funFact: 'La batalla contra Dynamic Rockers en el Lincoln Center, el 15 de agosto de 1981, fue uno de los primeros enfrentamientos de breaking ante un público masivo y quedó en la memoria de la cultura como el momento en que el baile del Bronx saltó a la escena pública.', related: ['BREAK', 'B_BOY', 'CREWS_70S', 'CYPHER'] } },
  { word: 'SIX_STEP', category: 'breaking', difficulty: 'easy', knowledge: { title: 'Six-step', description: 'El six-step (6-step, "caminata de seis pasos") es el movimiento básico de footwork del breaking: con el cuerpo agachado y las manos apoyadas en el suelo, el b-boy camina en círculo con las piernas —seis apoyos de pies que lo hacen girar 360 grados— sin despegar las manos del piso. Es el primer paso de suelo que aprende casi todo b-boy y la puerta de entrada al footwork.', importance: 'El six-step es la puerta de entrada al breaking en el suelo: sin six-step no hay footwork, y sin footwork no hay breaking completo. Es el movimiento que demuestra que la disciplina se aprende de abajo hacia arriba, literalmente: primero el piso, después los trucos.', funFact: 'El six-step se llama así porque son seis apoyos de pies los que completan el giro de 360 grados en el suelo, con las manos siempre apoyadas.', related: ['BATTLE', 'B_BOY', 'FOOTWORK', 'FOUNDATION', 'TOPROCK'] } },
  { word: 'STYLE', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Style', description: 'El style (estilo) es la firma personal de cada b-boy: la forma única de moverse, de entrar al círculo, de ejecutar los pasos y de combinar los movimientos, que hace que cualquiera lo reconozca aunque no le vea la cara. En el breaking, el style es el valor central de la disciplina: más importante que la cantidad de trucos es cómo se baila.', importance: 'El style encarna la idea de que el Hip Hop premia la identidad propia: la originalidad como valor que el breaking comparte con las demás disciplinas de la cultura. Entender el style es entender por qué en el breaking no basta con ejecutar: hay que decir algo propio con el cuerpo.', funFact: 'En el breaking se dice que "el estilo no se copia": la regla no escrita de la escena, transmitida como tradición oral, es que imitar el estilo de otro b-boy es la falta más grave de la disciplina.', related: ['BATTLE', 'B_BOY', 'FOUNDATION', 'MUSICALITY', 'ROCKSTEADY'] } },
  { word: 'TOPROCK', category: 'breaking', difficulty: 'easy', knowledge: { title: 'Toprock', description: 'El toprock es la parte del breaking que se baila de pie: los pasos y movimientos con los que el b-boy o la b-girl entra al círculo (ver `cypher`) antes de bajar al suelo. Es la carta de presentación del bailarín: en el toprock se ven el estilo, la actitud y la musicalidad de quien baila. Entre los pasos clásicos están el indian step, el crossover y el salsa step, aunque los nombres varían según la región.', importance: 'El toprock es la puerta de entrada al breaking: muestra carácter antes de mostrar acrobacia. Es donde la musicalidad se hace visible y donde el b-boy establece su estilo frente al cypher; en un battle, un toprock con actitud ya es un mensaje antes de que empiece el duelo en el suelo.', funFact: 'El toprock se baila de pie y parece simple, pero es estratégico: es la primera impresión que el b-boy da al círculo, y en la escena se dice que el toprock ya revela si alguien baila con música o solo con pasos.', related: ['BREAK', 'BREAKERS70', 'B_BOY', 'CYPHER', 'FOOTWORK', 'MUSICALITY', 'ROCKSTEADY'] } },
  { word: 'WINDMILL', category: 'breaking', difficulty: 'hard', knowledge: { title: 'Windmill', description: 'El windmill (molino) es el power move más emblemático del breaking: un giro continuo sobre la parte alta de la espalda y los hombros, con las piernas abiertas en V rotando como aspas de molino y el cuerpo rodando por el piso sin parar. Se enlaza con otros giros y power moves del repertorio del b-boy (ver `power`) y es uno de los movimientos que el público identifica al instante como breaking.', importance: 'El windmill llevó el breaking del suelo a la acrobacia y definió la imagen del power move: junto con el headspin (ver `headspin`), es el movimiento que el mundo reconoce como símbolo del breaking. Además, inspiró a generaciones de "power heads" —b-boys especializados en movimientos de potencia— y empujó la evolución técnica de la disciplina.', funFact: 'En español, el windmill se llama molino: la imagen es la misma, las piernas girando como aspas mientras la espalda rueda por el piso.', related: ['BATTLE', 'B_BOY', 'FREEZE', 'POWER', 'ROCKSTEADY'] } },
  { word: 'BASS', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Bass', description: 'El bass —el bajo— es el sonido grave y continuo del beatbox: una vibración profunda de la garganta o de la voz que imita la línea de bajo (bass line) de la música. A diferencia del kick, que es un golpe seco y corto, el bass es un sonido sostenido que suena mientras dura el aire. Es la base sobre la que el beatbox moderno construye grooves completos, y su versión más avanzada, el throat bass (bajo de garganta), tiene su propia entrada (ver `throat-bass`).', importance: 'El bass es lo que hace que el beatbox suene a música y no a ruido: le da peso, continuidad y carácter armónico. Marcó el salto del beatbox de "acompañamiento del MC" a arte autónomo con escena competitiva, y es la base sobre la que se apoyan las técnicas avanzadas de la disciplina.', funFact: 'Rahzel, exmiembro de The Roots, es el beatboxer que demostró al mundo que se puede cantar y beatboxear a la vez: en "If Your Mother Only Knew" (álbum *Make the Music 2000*, 1999) sostiene un bajo continuo con la voz mientras hace el beatbox.', related: ['HUMANBEATBOX', 'KICK', 'THROAT_BASS'] } },
  { word: 'BEATBOX_LOOP', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Loop (beatbox)', description: 'En beatbox, el loop es el patrón rítmico que se repite en bucle: la secuencia de kick, snare y hi-hat (ver `kick`, `snare`, `hi-hat`) que el beatboxer repite una y otra vez para sostener el beat, sobre el que se rapea, se improvisa o se construyen capas. Es la unidad básica del lenguaje del beatbox: sin loop no hay beat continuo, y sin beat continuo no hay cypher (ver `cypher`).', importance: 'El loop es la columna vertebral del beatbox: convierte sonidos sueltos (kick, snare, hi-hat) en música continua. Entenderlo permite distinguir dos usos del mismo nombre: el patrón repetido del beatbox (esta entrada) y el loop de audio de la producción (ver `loop`), y ubica al beatbox dentro de la lógica musical del sampleo y la repetición que define al Hip Hop (ver `beat`).', funFact: 'El loop del beatbox es un patrón ejecutado en vivo con la boca, mientras que el loop de producción (ver `loop`) es un fragmento de audio que se repite: mismo nombre, distinto medio — uno es performance, el otro es material grabado.', related: ['BASS', 'BEAT', 'BEATBOX', 'CYPHER', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'LOOP', 'MOUTHDRUM', 'SNARE'] } },
  { word: 'BEATBOX', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Beatbox', description: 'El beatbox —beatboxing o human beatbox— es la práctica de hacer percusión con la boca: imitar con labios, lengua, garganta y voz los sonidos de una batería o de una caja de ritmos, sobre todo el bombo (kick), la caja (snare) y el charles (hi-hat), además de efectos como el scratch de un DJ. Nació dentro del Hip Hop como solución práctica cuando no había instrumentos ni presupuesto: el cuerpo como única máquina de ritmos (ver `human-beatbox`).', importance: 'El beatbox es la disciplina del Hip Hop que no necesita ningún aparato: demuestra que la cultura cabe en el cuerpo. Mantuvo la percusión en vivo cuando las máquinas eran caras, abrió el camino al scratching vocal y convirtió la percusión vocal en un arte con campeonatos mundiales. La escena lo llama, por tradición oral, el "quinto elemento" del Hip Hop (ver `fifth-element`), junto al MC, el DJ, el breaking y el writing.', funFact: 'En inglés, "beatbox" nombra a la vez la práctica y la máquina que imita: las cajas de ritmos se llamaban "beat boxes", y de ahí el nombre del arte vocal que las reproduce con la boca.', related: ['BASS', 'BLOCK_PARTY', 'CYPHER', 'DJ', 'HIP_HOP', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'MC', 'MOUTHDRUM', 'SNARE', 'VOCALPERC'] } },
  { word: 'CLICK', category: 'beatbox', difficulty: 'medium', knowledge: { title: 'Click', description: 'El click (clic de lengua) es un sonido percusivo seco y agudo que el beatboxer produce con la lengua o el carrillo: se sella la lengua contra el paladar o contra los molares, se aspira un poco de aire y se suelta de golpe, generando un chasquido corto. Suena como un hi-hat acústico o como el chasquido que se hace para llamar la atención. Su gran ventaja es que no necesita aire de los pulmones: se puede ejecutar una y otra vez sin exhalar.', importance: 'El click amplió la caja de ritmos del beatbox con un hi-hat sin aire: permite mantener ritmos continuos sin quedarse sin respiración y añade una textura seca y nítida imposible de lograr solo con la voz. Es la base de los redobles de la nueva escuela y una de las puertas de entrada a los sonidos "sin aire" que caracterizan al beatbox moderno (ver `inward`).', funFact: 'El click es uno de los "sonidos sin aire" del beatbox: se ejecuta sellando y soltando la lengua sin exhalar, lo que permite tocarlo en ráfagas rapidísimas (click roll) sin cortar el ritmo ni quedarse sin respiración.', related: ['HI_HAT', 'HUMANBEATBOX', 'INWARD', 'KICK', 'SNARE'] } },
  { word: 'HI_HAT', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Hi-hat', description: 'El hi-hat —el charles— es el sonido agudo y metálico del beatbox: un "ts" corto y brillante que imita el charles de la batería y mantiene el tiempo dentro del patrón. Es el tercer sonido de la trilogía básica (kick, snare, hi-hat) y el más rápido de producir. Se hace dejando pasar un golpe de aire por la lengua apoyada contra los dientes, como al pronunciar "ts": corto para el hi-hat cerrado, alargado ("tsss") para el abierto. En la notación estándar se escribe /ts/.', importance: 'El hi-hat le da "aire" y velocidad al beatbox: es el sonido que sostiene el tiempo y el que más veces se repite en cualquier patrón. Junto al kick y la caja completa la trilogía con la que se construye cualquier ritmo, y su práctica entrena la independencia rítmica que exigen las técnicas avanzadas.', funFact: 'En la notación estándar del beatbox el hi-hat se escribe /ts/, y el patrón básico de 4/4 que aprenden todos los principiantes —bombo, charles, caja— se escribe [b-ts-k-ts-b-ts-k-ts].', related: ['HUMANBEATBOX', 'KICK', 'SNARE'] } },
  { word: 'HUMANBEATBOX', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Human Beatbox', description: 'El human beatbox —beatbox a secas— es la práctica de hacer percusión con la boca: imitar con labios, lengua, garganta y voz los sonidos de una caja de ritmos, sobre todo el bombo (kick), la caja (snare) y el charles (hi-hat), además de efectos como el scratch de un DJ. Es una forma de percusión vocal nacida dentro del Hip Hop que convierte al cuerpo en el único instrumento. El nombre viene de las máquinas de ritmo —las "beatboxes", como el Roland TR-808— que los primeros beatboxers imitaban con la voz.', importance: 'El beatbox es la disciplina del Hip Hop que no necesita ningún aparato: demuestra que la cultura cabe en el cuerpo. Mantuvo la percusión en vivo cuando las máquinas eran caras, abrió el camino al scratching vocal y convirtió la percusión vocal en un arte autónomo con campeonatos mundiales. La escena lo llama el "quinto elemento" del Hip Hop (tradición oral), junto al MC, el DJ, el breaking y el graffiti.', funFact: '"La Di Da Di" (1985), de Doug E. Fresh y Slick Rick, está respaldada de principio a fin por el beatbox de Fresh y es una de las canciones más sampleadas de la historia de la música, según The Wall Street Journal (2019).', related: ['BLOCK_PARTY', 'BREAKBEAT', 'CYPHER', 'DJ', 'HIP_HOP', 'JAM', 'MC'] } },
  { word: 'INWARD', category: 'beatbox', difficulty: 'hard', knowledge: { title: 'Inward', description: 'El inward (sonidos de inhalación) es una familia de técnicas de beatbox en las que el sonido se produce aspirando, es decir, con el aire entrando hacia los pulmones en lugar de saliendo: el beatboxer inhala y articula el sonido al paso del aire, como en el inward k snare (la "K" aspirada hacia adentro, que produce un chasquido de caja). Al alternar sonidos outward (de exhalación) e inward (de inhalación), el beatboxer mantiene el ritmo de forma continua, porque la respiración deja de ser un corte obligatorio: lo que sale como sonido vuelve a entrar como sonido.', importance: 'El inward convirtió la respiración en parte del instrumento: el beatboxer dejó de exhalar y punto, y pasó a respirar haciendo música. Permitió rutinas largas y continuas, duplicó el vocabulario de sonidos y sentó las bases de los bajos graves y los drags que definen el beatbox moderno (ver `throat-bass` y `click`, los otros pilares "sin aire" de la nueva escuela).', funFact: 'Está documentado que Kenny Muhammad ("the Human Orchestra") fue el pionero del inward k snare en los años 90; en cambio, la atribución a Swifty como primer usuario de la inhalación es tradición oral que la Wikipedia registra con cita pendiente.', related: ['CLICK', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'SNARE', 'THROAT_BASS'] } },
  { word: 'KICK', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Kick', description: 'El kick es el sonido del bombo (bass drum) imitado con la boca: un golpe grave, corto y contundente que marca el pulso del ritmo. Es el primero de la trilogía básica del beatbox —kick, caja (snare) y charles (hi-hat)— y el sonido con el que todo principiante empieza. Se produce con los labios cerrados, soltando un golpe de aire corto, como al pronunciar una "b" o una "p" sin voz. En la notación estándar del beatbox se escribe con la letra [b].', importance: 'El kick es el cimiento rítmico del beatbox: es el golpe que el público "siente" en el pecho y el que mantiene el tiempo junto al charles. Dominarlo es el primer paso de cualquier beatboxer y la base sobre la que se construyen todos los patrones, desde el más simple hasta los grooves de la escena competitiva.', funFact: 'En la notación estándar del beatbox (SBN), el kick se representa con la letra [b] (de "bass drum") y abre el patrón básico de 4/4 que aprenden todos los principiantes: [b-ts-k-ts-b-ts-k-ts].', related: ['BASS', 'BREAKBEAT', 'HUMANBEATBOX', 'SNARE'] } },
  { word: 'MOUTHDRUM', category: 'beatbox', difficulty: 'medium', knowledge: { title: 'Mouth Drum (Batería Bucal)', description: 'Mouth drum —batería bucal— es el término descriptivo que la escena del beatbox usa para la práctica de imitar con la boca el sonido de una batería completa: el bombo (kick), la caja (snare), el charles y los platillos (hi-hat), y en general los golpes graves y agudos que componen un patrón de percusión. Es una forma de percusión vocal (ver `vocalpercussion`) orientada específicamente a reproducir el set de una batería, no solo ritmos abstractos.', importance: 'La batería bucal es la columna vertebral del beatbox: sin kick, snare y hi-hat no hay beat, y sin beat no hay cypher ni MC que rapee encima. Entender la disciplina como "tocar una batería con la boca" ayuda a comprender por qué el beatbox se enseña separando golpes graves y agudos, y por qué sus sonidos básicos (ver `kick`, `snare`, `hi-hat`, `bass`) se nombran como los de una batería real.', funFact: 'En la didáctica del beatbox, el mouth drumming se practica separando los golpes graves (kick y snare) de los agudos (hi-hats) para construir patrones que suenen como una batería completa, con el cuerpo como único instrumento.', related: ['BASS', 'BEATBOX', 'CYPHER', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'SNARE', 'VOCALPERC'] } },
  { word: 'SNARE', category: 'beatbox', difficulty: 'easy', knowledge: { title: 'Snare', description: 'El snare —la caja— es el golpe seco y rasgado del beatbox: el sonido que imita la caja de la batería (snare drum) y que en el patrón clásico cae en los tiempos 2 y 4 del compás. Junto al kick y el hi-hat forma la trilogía básica del beatbox, y en la notación estándar se escribe con la letra [k]. Se produce cortando un golpe de aire con la lengua o los labios, y existe en muchas variantes: hacia afuera (outward), hacia adentro (inward), "pfat" (bilabial más fricativa) o "CL" (que imita el palmoteo).', importance: 'La caja es el sonido que le da "cara" al ritmo: diferencia un patrón de otro y es el golpe con más variantes del beatbox básico. Aprender sus dos direcciones —hacia afuera y hacia adentro— es esencial para mantener el flujo sin cortarse y para acceder a las técnicas avanzadas de la disciplina.', funFact: 'El "inward k snare" —la caja aspirada, hacia adentro— se atribuye por tradición oral a Kenny Muhammad, y es la técnica que permite a los beatboxers tocar patrones rápidos sin quedarse sin aire.', related: ['HI_HAT', 'HUMANBEATBOX', 'KICK'] } },
  { word: 'TAG_TEAM', category: 'beatbox', difficulty: 'medium', knowledge: { title: 'Tag team', description: 'El tag team (equipo con relevos, del wrestling) es el formato de competencia de beatbox en parejas: dos beatboxers compiten juntos como un solo participante, alternándose en los solos —el "tag", el relevo—, complementándose (uno lleva el ritmo mientras el otro toca el bajo o la melodía) y coordinando pasajes a dúo. Es una de las categorías estándar de los campeonatos internacionales, junto al solo, el crew y el loopstation. Frente a un battle individual, la pareja compite como una unidad contra otra pareja, ante jueces y público (ver `battle`).', importance: 'El tag team llevó el beatbox de lo individual a lo colaborativo dentro de la competencia: demostró que dos beatboxers pueden funcionar como un solo instrumento con arreglos a dos voces, y popularizó el dúo como formato escénico y competitivo. Es, además, la puerta de entrada natural del beatbox a los formatos grupales (crew) y a la musicalidad conjunta.', funFact: 'La categoría tag team existe desde el primer campeonato mundial de beatbox: el WBC de 2005 coronó a Attention Deficit Disaudio (Joel Turner y Tom Thum, Australia). Y en 2018, Spider Horse ganó el título de tag team en los dos grandes circuitos, el WBC y el GBB, en el mismo año.', related: ['BATTLE', 'CLICK', 'HI_HAT', 'HUMANBEATBOX', 'INWARD', 'KICK', 'SNARE', 'THROAT_BASS'] } },
  { word: 'THROAT_BASS', category: 'beatbox', difficulty: 'hard', knowledge: { title: 'Throat bass', description: 'El throat bass (bajo de garganta) es un sonido grave, profundo y gutural que el beatboxer produce en la garganta: al hacer vibrar las cuerdas vocales falsas (los pliegues vestibulares, situados sobre las cuerdas vocales) se genera un subarmónico ronco, como un gruñido grave y sostenido. Suena parecido a un bajo eléctrico distorsionado o a un contrabajo profundo. Se puede mantener como nota continua o golpearlo para marcar el downbeat, el pulso fuerte del compás.', importance: 'El throat bass le dio al beatbox una dimensión musical nueva: notas graves sostenidas y subarmónicos que imitan bajos sintetizados y contrabajos, no solo percusión. Es la base del llamado "bass music beatbox" y un puente entre el beatbox y otras tradiciones vocales de grave profundo, además de un sonido exigente que marcó el nivel técnico de la nueva escuela.', funFact: 'Contra el mito extendido, el throat bass no se produce con las cuerdas vocales vibrando lento: se produce con las cuerdas vocales falsas (pliegues vestibulares), que generan un subarmónico grave — la corrección la documenta la propia comunidad en BeatboxAnatomy.', related: ['BASS', 'HI_HAT', 'HUMANBEATBOX', 'INWARD', 'KICK', 'SNARE'] } },
  { word: 'VOCALPERC', category: 'beatbox', difficulty: 'medium', knowledge: { title: 'Percusión Vocal', description: 'La percusión vocal es el arte de producir ritmos y sonidos de percusión con la voz y el cuerpo: labios, lengua, garganta, mejillas y respiración, sin ningún instrumento. Es una categoría amplia que existe en muchas culturas y músicas —el scat del jazz, el eefing de los Apalaches, el konnakol de la India— y que dentro del Hip Hop toma la forma concreta del beatbox (ver `beatbox`, `human-beatbox`).', importance: 'La percusión vocal demuestra que el ritmo no necesita instrumentos: cabe en el cuerpo humano. En el Hip Hop, sostuvo las fiestas y los cyphers antes y después de que las cajas de ritmos fueran accesibles, y se convirtió en una disciplina competitiva con campeonatos mundiales. Verla como categoría general permite ubicar al beatbox en un mapa más amplio de prácticas humanas sin reclamar para él una primacía que no está documentada.', funFact: 'El beatbox es la forma de percusión vocal del Hip Hop, pero la percusión vocal es más antigua y más amplia: incluye tradiciones como el scat del jazz, el eefing de los Apalaches y el konnakol de la India, sin que exista un linaje documentado entre ellas y el beatbox.', related: ['BEATBOX', 'CYPHER', 'HIP_HOP', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'MOUTHDRUM', 'SNARE'] } },
  { word: 'EIGHT', category: 'produccion', difficulty: 'medium', knowledge: { title: 'TR-808', description: 'La Roland TR-808 (o simplemente "la 808") es una caja de ritmos analógica de Roland, fabricada entre 1980 y 1983, que genera todos sus sonidos por síntesis analógica —sin samples— y permite programar la pista de percusión completa paso a paso (ver `drum-machine` y `drum-programming`). Su bombo profundo y grave, con caída prolongada, se volvió el sonido más famoso del Hip Hop: la base de miles de beats, del rap sureño al trap (ver `beat`).', importance: 'La 808 le dio al Hip Hop su batería característica: el bombo grave y largo que la prensa describió como el equivalente hip hop de la Fender Stratocaster. Su fracaso comercial inicial —una máquina "fallida" que terminó definiendo un género— es parte central de la historia del beatmaking (ver `producer`).', funFact: 'La Roland TR-808 (1980, US$ 1.195) fracasó en ventas —menos de 12.000 unidades hasta 1983— pero su bombo sintético profundo se volvió la firma sonora del Hip Hop, desde "Planet Rock" (1982) hasta el trap actual.', related: ['BAMBAATAA', 'BASSLINE', 'BEAT', 'DRUMPROG', 'DRUM_MACHINE', 'MPC', 'PLANETROCK', 'PRODUCER', 'SYNTH'] } },
  { word: 'ARRANGEMENT', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Arrangement', description: 'El arrangement (arreglo) es la estructura del beat: el orden y la duración de sus secciones —intro, versos, estribillo, breakdown y outro— que convierten un loop (ver `loop`) en una canción. Un beat en bruto es una idea que se repite; el arreglo decide cuándo entra cada elemento, cuándo se queda solo, cuándo sube la energía y cuándo baja, para que el tema no canse y el MC (ver `mc`) tenga espacio para rapear. Es la diferencia entre una base y una canción terminada.', importance: 'El arrangement es lo que hace que un beat funcione como canción: decide la respiración, la tensión y el momento del "golpe". Un loop puede ser genial, pero sin arreglo es solo una idea; con arreglo se convierte en un tema que el oyente recuerda, canta y baila, y en el andamiaje sobre el que el MC construye su historia.', funFact: 'La estructura típica del rap documentada en los manuales de composición alterna versos de unos 16 compases con hooks de unos 8 compases que se repiten de tres a cuatro veces por tema: el hook ocupa la mitad del espacio de un verso, pero al repetirse termina siendo la parte que más suena.', related: ['BEAT', 'DRUMPROG', 'HOOK', 'LOOP', 'MC', 'POSSE_CUT', 'RAPDELIGHT'] } },
  { word: 'BASSLINE', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Bassline', description: 'La bassline (línea de bajo) es la parte grave y repetida que sostiene el beat: una secuencia de notas bajas —o un solo golpe profundo— que marca la armonía y el groove de la base. En el Hip Hop puede venir de samplear o re-grabar líneas de bajo de discos de funk y soul (ver `sampling`, `interpolation`), o de sintetizadores y cajas de ritmos como el bajo profundo del Roland TR-808. Es lo que se siente en el pecho y lo que "pega" el beat con el cuerpo: sin bajo, un beat suena plano.', importance: 'La bassline es la conexión física entre el beat y el bailarín: define el peso, el groove y hasta el género de un tema. Cada escuela del Hip Hop se reconoce por su bajo —el bajo de funk sampleado del boom bap, el 808 profundo del G-funk y del trap, el bajo melódico del neo-soul—, y es la parte que más se "siente" antes de entenderse.', funFact: '"Impeach the President" (Roy C, 1973), un tema funk de protesta contra Nixon, está entre los discos más sampleados de la historia del Hip Hop: según el registro, se ha sampleado cientos de veces desde mediados de los 80, y Marley Marl lo usó como base de "The Bridge" (1986).', related: ['BASS', 'BREAK', 'BREAKBEAT', 'INTERPOLA', 'KICK', 'PRODUCTORES', 'RAPDELIGHT', 'SAMPLING'] } },
  { word: 'BEAT', category: 'produccion', difficulty: 'easy', knowledge: { title: 'Beat', description: 'El beat es el instrumental sobre el que rapea el MC: la pista musical compuesta por batería, bajo y, según el estilo, samples, sintetizadores o voces. Es la unidad musical del Hip Hop: la base que el rapero convierte en canción al sumarle sus rimas. En el Hip Hop, el beat no es un acompañamiento de fondo: es la mitad del tema.', importance: 'El beat es el suelo de toda la cultura: el MC rima sobre él, el b-boy baila al ritmo que marca, el DJ lo mezcla y el público lo reconoce en los primeros segundos. Es la pieza que convierte la poesía en canción y la canción en producto, y por eso el beatmaking se volvió un oficio central del Hip Hop (ver `beatmaker`).', funFact: 'En el Hip Hop, el beat es anterior a la canción: los productores crean y venden beats como piezas independientes —la "cama musical" (musical bed) sobre la que el artista canta o rapea, según documenta la entrada \'Beatmaker\' de Wikipedia— y solo después llegan las rimas.', related: ['BASS', 'BEATMAKER', 'BLOCK_PARTY', 'BREAKBEAT', 'DJ_KOOL_HERC', 'DRUM_BREAK', 'KICK', 'LOOP', 'MC', 'PRODUCER'] } },
  { word: 'BEATMAKER', category: 'produccion', difficulty: 'easy', knowledge: { title: 'Beatmaker', description: 'El beatmaker es la persona que crea el beat: la pista instrumental sobre la que después se rapea. Su trabajo consiste en armar la batería, el bajo y los demás elementos del tema usando samplers, cajas de ritmos, el MPC o programas de computadora (DAW). No es el DJ, que toca y mezcla discos en vivo (ver `dj`), ni necesariamente el productor, que dirige el sonido final de la grabación (ver `producer`): su foco es el beat mismo.', importance: 'El beatmaker es el músico del Hip Hop: el que decide cómo suena la base sobre la que toda la cultura se mueve. Según la sección \'Beatmaker\' de Wikipedia (s. v. \'Songwriter\'), su función es poner la "cama musical" (musical bed) de la canción, y no necesariamente supervisa la producción final del estudio. Su aporte dio al Hip Hop su diversidad sonora: cada región y cada época tienen los beats que sus beatmakers les construyeron.', funFact: 'El Akai MPC60 (1988), diseñado por Roger Linn, es la máquina que convirtió el beatmaking en un oficio de una sola persona: sampler, secuenciador y pads de disparo en un solo aparato, y sigue siendo el estándar de referencia del sonido clásico del Hip Hop (ver `mpc`).', related: ['BEAT', 'DJ', 'DRUM_MACHINE', 'MC', 'MPC', 'PRODUCER', 'SAMPLER', 'SAMPLING'] } },
  { word: 'CHOP', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Chop', description: 'El chop es la técnica de cortar un sample en fragmentos pequeños —las "rebanadas"— y dispararlos en un orden nuevo desde los pads de un sampler, creando un patrón que ya no suena como el original. En vez de repetir el sample entero, el beatmaker lo desarma y lo vuelve a armar a su manera: así un break de batería ajeno se convierte en un beat propio. Es una de las técnicas centrales del beatmaking y la que dio al sonido clásico del Hip Hop su carácter de collage rítmico.', importance: 'El chop es lo que convierte el sample en composición: sin él, el beatmaking sería copiar; con él, es reescribir. Le dio al Hip Hop la posibilidad de hacer sonar como propio el material ajeno y abrió la puerta a los estilos que construyen toda su base rítmica con rebanadas reordenadas, del boom bap al lo-fi.', funFact: 'Según la descripción de Roger Linn, diseñador del MPC60, chopear es "tomar un loop de 8 compases, cortarlo en 8 o 16 rebanadas y reordenarlas a ver si suena bien": la receta básica de la técnica que definió el sonido del beatmaking con MPC (ver `mpc`).', related: ['BREAKBEAT', 'DRUMPROG', 'DRUM_BREAK', 'LOOP', 'MPC', 'SAMPLE', 'SAMPLER', 'SAMPLING', 'SWING'] } },
  { word: 'DRUM_BREAK', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Drum break', description: 'El drum break (break de batería) es el fragmento de batería que el productor extrae de un disco, lo samplea y lo usa como material de un beat: unos segundos de tambores, aislados del resto de la canción, que se convierten en la base rítmica de un tema nuevo. Es la versión de estudio del break: el break es la sección del disco; el drum-break es ese mismo fragmento ya convertido en sample (ver `break` y `breakbeat`). Quien escucha Hip Hop clásico reconoce el efecto: la batería suena repetida, con sus ruidos de vinilo, como un lazo que nunca se cansa.', importance: 'El drum-break es el eslabón que conecta las tres vidas del break: el DJ lo extiende en la fiesta, el b-boy lo baila y el productor lo samplea en el estudio. Sin él no existiría el Hip Hop sampleado tal como lo conocemos: es el material sobre el que se construyen los beats de la edad de oro y el origen del boom bap.', funFact: 'El Amen break —unos seis segundos de batería de Gregory Coleman en "Amen, Brother" (The Winstons, 1969)— es uno de los drum-breaks más sampleados de la historia, con más de 1.800 usos documentados hasta 2015; sus autores no recibieron un centavo en regalías.', related: ['BOOM_BAP', 'BREAK', 'BREAKBEAT', 'DJ_KOOL_HERC', 'LOOP', 'SAMPLE', 'SAMPLING'] } },
  { word: 'DRUM_MACHINE', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Caja de ritmos', description: 'La caja de ritmos (drum machine) es un instrumento que genera sonidos de percusión —bombo, caja, charles, tom, clap— y los organiza en patrones programables: el usuario elige qué golpes suenan en cada paso del compás y la máquina los repite en bucle. Las primeras solo reproducían ritmos prefijados (bossa nova, rock); las modernas se programan paso a paso con botones y pueden guardar decenas de patrones. Es el aparato que le dio al Hip Hop su batería "de máquina": precisa, repetible y, con el paso del tiempo, inconfundible (ver `drum-programming`).', importance: 'La caja de ritmos le dio al Hip Hop su batería característica y su precisión mecánica: el bombo del 808, descrito por la prensa como el equivalente hip hop de la Fender Stratocaster, se escucha desde Run-DMC y Public Enemy hasta el trap actual. También introdujo la idea de programar el ritmo paso a paso, la base de toda la producción moderna (ver `drum-programming` y `beat`).', funFact: 'La Roland TR-808 (1980, US$ 1.195) fracasó comercialmente —menos de 12.000 unidades hasta 1983— pero terminó usándose en más éxitos de listas que ninguna otra caja de ritmos de la historia, con su bombo profundo como sello del Hip Hop.', related: ['BAMBAATAA', 'BEAT', 'BREAKBEAT', 'DRUMPROG', 'MPC', 'ONE_SHOT', 'SAMPLER'] } },
  { word: 'DRUMPROG', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Drum programming', description: 'El drum programming es el arte de crear la batería de un beat colocando golpes —bombo (kick), caja (snare) y charles (hi-hat)— sobre una rejilla rítmica, ya sea en una caja de ritmos, un sampler o un programa de música. En lugar de que un baterista toque en vivo, el productor decide en qué momento exacto suena cada golpe, con qué fuerza y con qué velocidad. Es la base de casi todo beat de Hip Hop desde los años 80: primero se programa (o se samplea) la batería y sobre ella se construye el resto.', importance: 'El drum programming es la columna vertebral del beat: determina el estilo, el groove y la energía de la canción. Gracias a él, un solo productor con una máquina puede sonar como una banda de funk completa, y cada escuela del Hip Hop se reconoce por su programación de batería —los golpes secos del boom bap, el bombo largo del G-funk, el charles rápido del trap.', funFact: 'El patrón clásico del boom bap es un loop donde el kick cae en los tiempos 1 y 3 y la caja (snare) en el 2 y el 4; el nombre es onomatopeya: "boom" por el bombo y "bap" por la caja.', related: ['BOOM_BAP', 'BREAKBEAT', 'DRUM_MACHINE', 'HI_HAT', 'KICK', 'MPC', 'QUANTIZATION', 'SNARE', 'SWING'] } },
  { word: 'INTERPOLA', category: 'produccion', difficulty: 'hard', knowledge: { title: 'Interpolación', description: 'La interpolación es la técnica de re-grabar una melodía, una línea de bajo o una letra conocida en lugar de usar la grabación original: en vez de samplear el disco (ver `sampling`, `sample`), músicos de estudio o el propio productor tocan la parte de nuevo, a veces cambiándola. El resultado suena parecido pero es un audio completamente nuevo. En el Hip Hop se usa para conseguir el guiño a un clásico sin pagar (o sin poder conseguir) la autorización de la grabación original.', importance: 'La interpolación amplió las herramientas del productor: permite homenajear un clásico, evitar problemas legales y reconstruir la parte a gusto del beat, sin depender de la cinta original. También cambió la economía del sampleo —más barata y más fácil de limpiar— y obligó a la industria a definir los límites entre homenaje, imitación y plagio, un terreno que sigue en disputa.', funFact: 'Según la U.S. Copyright Office (2021), la interpolación solo requiere licencia del titular de la composición; el sampling requiere licencia tanto del titular de la composición como del dueño de la grabación. Y el caso pionero fue "Rapper\'s Delight" (1979), que re-grabó la línea de bajo de "Good Times" de Chic y terminó dando créditos de composición a Nile Rodgers y Bernard Edwards.', related: ['BEAT', 'LOOP', 'PRODUCTORES', 'RAPDELIGHT', 'SAMPLE', 'SAMPLING'] } },
  { word: 'LOOP', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Loop', description: 'Un loop es una sección corta de audio —típicamente de uno a cuatro compases— editada para repetirse en ciclo sin cortes perceptibles, de modo que suena de forma continua mientras dura el tema. Es el ladrillo básico del beatmaking: la base rítmica que se repite una y otra vez mientras el MC rima encima. Según Daniel Duffell (2005), un loop es "una sección corta de una pista (probablemente de entre uno y cuatro compases) que se cree que puede funcionar repetida", a diferencia del one-shot, que suena una sola vez (ver `sample`).', importance: 'El loop es la razón por la que unos segundos de música pueden sostener una canción entera: convirtió el break de un disco —un momento efímero— en la estructura permanente del tema. Es el puente entre el DJing manual de los 70 y el beatmaking digital, y la técnica que permite que un fragmento de seis segundos se convierta en el corazón de un beat.', funFact: 'Según la definición estándar de Daniel Duffell (2005), un loop dura entre uno y cuatro compases y está pensado para repetirse en ciclo: es lo que permite que el break de seis segundos de un disco se convierta en la base de una canción completa.', related: ['BEAT', 'BLOCK_PARTY', 'BREAKBEAT', 'DJ_KOOL_HERC', 'DRUM_BREAK', 'FLASH', 'MERRYGOROUND', 'SAMPLE', 'SAMPLER', 'SAMPLING', 'TURNTABLE'] } },
  { word: 'MASTERING', category: 'produccion', difficulty: 'hard', knowledge: { title: 'Mastering (Masterización)', description: 'El mastering (masterización) es la etapa final de la producción musical: el proceso que prepara la mezcla final y la transfiere a la copia maestra —el archivo del que se hacen todas las copias (ver `album`). El ingeniero de mastering escucha la mezcla en detalle y aplica ecualización, compresión, limitación, ajustes de volumen y secuenciación de canciones para que el resultado suene bien en cualquier sistema: parlantes, audífonos, radio, streaming y club. No es una etapa creativa como la producción del beat (ver `producer` y `beat`): es la etapa de precisión final.', importance: 'El mastering es la puerta de salida de una producción: decide cómo sonará el trabajo en el mundo real, en todos los sistemas y formatos. Un buen master hace que un beat (ver `beat`) suene profesional; un mal master arruina una buena mezcla. Es la diferencia entre una maqueta y un lanzamiento terminado.', funFact: 'El mastering es la etapa final: ecualización, compresión, limitación y secuenciación de la mezcla para crear la copia maestra; la "loudness war" (guerra de volumen) es su controversia más documentada.', related: ['ALBUM', 'BEAT', 'PRODUCER', 'REMIX'] } },
  { word: 'MIDI', category: 'produccion', difficulty: 'medium', knowledge: { title: 'MIDI', description: 'El MIDI (Musical Instrument Digital Interface) es el protocolo estándar que permite comunicar instrumentos electrónicos, cajas de ritmos, computadores y controladores entre sí. No transmite sonido ni audio: transmite eventos —qué nota, con qué fuerza (velocidad), cuánto dura— por hasta 16 canales. Es el "esperanto" de la música electrónica: con MIDI, un teclado puede tocar un sintetizador (ver `synth`), una caja de ritmos puede sincronizarse con otra (ver `drum-machine`) y un secuenciador puede programar una canción completa (ver `drum-programming`).', importance: 'El MIDI es la base de la producción musical moderna: sin él, los equipos de cada fabricante no conversarían entre sí y el estudio de beats sería una torre de Babel. Permite programar, editar y sincronizar la música como datos —pequeños, editables y transportables—, lo que hizo posible el beatmaking tal como se conoce (ver `drum-machine`, `mpc` y `synth`).', funFact: 'El MIDI se estandarizó en 1983, propuesto por Ikutaro Kakehashi (Roland) y Dave Smith (Sequential Circuits): transmite eventos musicales —no audio— por hasta 16 canales, y la primera caja de ritmos con MIDI fue la Roland TR-909.', related: ['BEAT', 'DRUMPROG', 'DRUM_MACHINE', 'MPC', 'PRODUCER', 'SYNTH'] } },
  { word: 'MPC', category: 'produccion', difficulty: 'medium', knowledge: { title: 'MPC', description: 'El MPC (Akai MPC, de "MIDI Production Center", hoy "Music Production Center") es un instrumento que combina sampler y secuenciador en una sola caja: graba sonidos, los asigna a una rejilla de almohadillas (pads) y programa ritmos con ellas. Su cara más reconocible es la parrilla de 16 pads sensibles a la presión, que se tocan con los dedos como si fueran un instrumento de percusión. Es, para millones de productores, el corazón del beatmaking: la máquina con la que se construye un beat de principio a fin.', importance: 'El MPC convirtió el sampleo en una forma de tocar: con los pads, el productor "toca" los sonidos en vez de programarlos con botones, y eso cambió la manera de construir beats. DJ Shadow, J Dilla y Kanye West, entre otros, lo usaron como instrumento central, y su parrilla de pads fue adoptada por innumerables fabricantes hasta volverse estándar de la tecnología musical. Es, según la prensa especializada, el sampler más influyente del Hip Hop (ver `sampler` y `beatmaker`).', funFact: 'El primer MPC, el MPC60, se lanzó el 8 de diciembre de 1988 a US$ 5.000 y solo permitía samplear 13 segundos de audio: esa limitación de memoria empujó a los productores a recortar (chop) los discos en fragmentos pequeños, y de ahí nació gran parte de la estética del sampleo del Hip Hop.', related: ['BEAT', 'BEATMAKER', 'BOOM_BAP', 'DRUM_MACHINE', 'SAMPLE', 'SAMPLER', 'SAMPLING'] } },
  { word: 'ONE_SHOT', category: 'produccion', difficulty: 'medium', knowledge: { title: 'One-shot', description: 'El one-shot (literalmente "de un solo disparo") es un sonido individual grabado como sample propio y disparado de una en una vez: un bombo (kick), una caja (snare), un charles (hi-hat), un aplauso o incluso un grito vocal. A diferencia del loop —un fragmento que se repite solo—, el one-shot es un golpe suelto que el productor coloca donde quiere, en el momento exacto del compás que le conviene. Es la unidad mínima de la programación de batería: con one-shots se construye un patrón golpe a golpe (ver `drum-programming`).', importance: 'El one-shot le dio al productor el control de un baterista con la precisión de una máquina: la posibilidad de construir un patrón golpe a golpe, con cada sonido elegido, afinado y colocado a mano. Es la pieza que separa el sampleo "de pasajes" (loops) del beatmaking quirúrgico, y la base sobre la que se programan desde los beats del boom bap hasta el trap (ver `boom-bap`).', funFact: 'Un mismo golpe de batería grabado como one-shot puede dispararse en cualquier punto del compás, afinarse y procesarse por separado; los samplers de frases, como los 16 pads del MPC, existen precisamente para eso: cada pad es un one-shot.', related: ['DRUM_MACHINE', 'HI_HAT', 'KICK', 'LOOP', 'MPC', 'SAMPLE', 'SAMPLER', 'SAMPLING', 'SNARE'] } },
  { word: 'PRODUCER', category: 'produccion', difficulty: 'easy', knowledge: { title: 'Productor musical', description: 'El productor es quien dirige la grabación: decide el sonido, el arreglo, el tempo y cómo suena el disco final, y coordina a los artistas, los músicos y los técnicos en el estudio. En el Hip Hop el productor puede ser quien hace el beat, quien elige y ordena los beats de otros, o ambas cosas: su sello es que el resultado final lleva su firma sonora. Se distingue del beatmaker en que su mirada cubre la canción completa, no solo la pista instrumental (ver `beatmaker`).', importance: 'El productor es el puente entre la creatividad del beatmaker y el producto final que llega al público: define cómo suena un disco, lanza carreras y da continuidad de estilo a una escena. Además, desde la sentencia Grand Upright de 1991 (ver `sampling`), es el responsable legal de que los samples estén licenciados: el oficio incluye no solo crear, sino asegurar los derechos.', funFact: 'The Chronic (1992), producido por Dr. Dre, fue certificado triple platino en Estados Unidos y la crítica lo considera uno de los discos mejor producidos e influyentes de los años 90: marcó el momento en que el productor dejó de ser un técnico para convertirse en el autor reconocido del sonido.', related: ['ALBUM', 'ARRANGEMENT', 'BEAT', 'BEATMAKER', 'CONSOLIDA80', 'MC', 'RAPDELIGHT', 'REMIX', 'SAMPLING'] } },
  { word: 'PRODUCTORES', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Productores Históricos', description: 'Los productores históricos son los beatmakers que definieron el sonido del Hip Hop desde los 80 hasta hoy: Marley Marl, Dr. Dre, DJ Premier, RZA, J Dilla y Kanye West, entre otros, documentados aquí como referencias de sus escuelas —sin ranking de "mejor". Son los que convirtieron el beat en el centro de la canción: tomaron el oficio de los DJs pioneros (ver `dj`, `dj-kool-herc`), lo llevaron a los samplers y las cajas de ritmos (ver `sampler`, `mpc`, `drum-machine`), y crearon los sonidos que identifican a cada región y cada época.', importance: 'Estos productores convirtieron el beat en el centro de la canción de Hip Hop y definieron subgéneros enteros: sin Marley Marl no hay batería sampleada, sin DJ Premier no hay boom bap de Nueva York, sin Dr. Dre no hay G-funk, sin J Dilla no hay el groove del neo-soul, sin Kanye no hay el chipmunk soul. Su red de influencias —Marley Marl inspiró a RZA, Premier, Pete Rock y Madlib; Dre formó a Snoop, Eminem y 50 Cent— explica cómo se transmite el oficio de generación en generación.', funFact: 'Según el registro académico de Mark Katz, Marley Marl se convirtió con "The Bridge" (1986) en el primer productor en samplear y reconfigurar un break de batería grabado (el de "Impeach the President", 1973); su influencia es reconocida por RZA, DJ Premier, Pete Rock y Madlib.', related: ['BAMBAATAA', 'BEAT', 'BEATMAKER', 'BOOM_BAP', 'DJ', 'DJ_KOOL_HERC', 'DRUM_BREAK', 'DRUM_MACHINE', 'FLASH', 'G_FUNK', 'JDILLA', 'MARLEYMARL', 'MPC', 'PRODUCER', 'RAPDELIGHT', 'SAMPLER', 'SAMPLING'] } },
  { word: 'QUANTIZATION', category: 'produccion', difficulty: 'hard', knowledge: { title: 'Quantization', description: 'La quantization (cuantización) es la función que alinea los golpes de un beat a una rejilla rítmica: si tocas un patrón ligeramente fuera de tiempo, la máquina lo "pega" a la división más cercana (corchea, semicorchea, etc.), dejando todo perfectamente recto. Es el proceso contrario al swing (ver `swing`): mientras el swing desplaza notas para que suenen humanas, la cuantización las fija al punto exacto. Toda caja de ritmos y programa de música la incluye, y decidir cuánto cuantizar es una de las decisiones centrales del beatmaker.', importance: 'La cuantización permitió que cualquiera pudiera programar una batería impecable, y definió el sonido del beat moderno: estable, bailable y repetible. A la vez, su existencia obligó a los productores a decidir qué tan "perfecto" quieren que suene su música, y esa decisión separa escuelas enteras: el beat pulido de la radio frente al groove suelto del underground.', funFact: 'Según el testimonio de Roger Linn, la cuantización de grabación (junto con el swing) fue introducida por él en la Linn LM-1 de 1979: antes de esa caja, los secuenciadores no corregían el tiempo de las notas.', related: ['BEAT', 'BOOM_BAP', 'DRUMPROG', 'DRUM_MACHINE', 'MPC', 'SWING'] } },
  { word: 'SAMPLE', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Sample', description: 'Un sample es un fragmento de una grabación existente que se reutiliza como material para una composición nueva: pueden ser unos segundos de batería, una frase cantada, un acorde corto o un golpe suelto. Es la materia prima del sampling (ver `sampling`): el beatmaker lo elige, lo recorta, lo repite o lo transforma hasta integrarlo en su beat. Un sample puede sonar reconocible o quedar irreconocible después del tratamiento.', importance: 'El sample es la unidad mínima de la memoria musical del Hip Hop: por él, discos olvidados vuelven a sonar y géneros enteros se construyen sobre fragmentos ajenos. Además, define el sonido: un beat de boom bap suena distinto según qué break, qué nota y qué textura se hayan sampleado.', funFact: 'Según la definición de Daniel Duffell (2005), un loop es "una sección corta de una pista (probablemente de entre uno y cuatro compases) que se cree que puede funcionar repetida", y no cualquier sample: la distinción entre el fragmento que se repite en ciclo (loop) y el golpe único (one-shot) es la primera decisión técnica del beatmaker.', related: ['BREAKBEAT', 'CHOP', 'DRUM_BREAK', 'LOOP', 'MPC', 'ONE_SHOT', 'SAMPLER', 'SAMPLING'] } },
  { word: 'SAMPLER', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Sampler', description: 'El sampler (muestreador) es un instrumento electrónico que graba fragmentos de sonido —un golpe de batería, una frase, un acorde, un pasaje de un disco—, los guarda en memoria digital y los reproduce cuando se los dispara con teclas, almohadillas (pads) o un secuenciador. El mismo sample puede reproducirse a distintas alturas de tono (pitch) para construir escalas y acordes, y la mayoría de los samplers permite filtrarlo y procesarlo. En el Hip Hop, el sampler es el aparato con el que el productor convierte pedazos de discos ajenos en un beat nuevo (ver `sampling` y `sample`).', importance: 'El sampler cerró el círculo del Hip Hop: convirtió en técnica de estudio lo que el DJ hacía en la fiesta, y permitió a productores sin formación musical construir canciones enteras a partir de fragmentos de otros discos. Con él nació la estética del recorte (chop), el sampleo de breaks y la idea de que cualquier sonido grabado puede ser material de un beat (ver `drum-break` y `one-shot`).', funFact: 'El Fairlight CMI (1979), un sampler de 8 bits que costaba decenas de miles de dólares, es el aparato que acuñó el término "sampling"; una década después, el SP-1200 (1987) y el MPC60 (1988) pusieron esa misma idea al alcance de los productores de Hip Hop.', related: ['DRUM_BREAK', 'DRUM_MACHINE', 'MPC', 'ONE_SHOT', 'SAMPLE', 'SAMPLING', 'SP_1200'] } },
  { word: 'SAMPLING', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Sampling', description: 'El sampling es la técnica de tomar fragmentos de grabaciones ya existentes —unos segundos de batería, una nota de bajo, una voz— y usarlos como material para construir una composición nueva. Es la práctica fundacional del beatmaking: el sample se recorta, se repite, se reordena o se transforma hasta dejar de ser el disco original y convertirse en un beat nuevo. Sin él, la mayor parte del sonido clásico del Hip Hop no existiría.', importance: 'El sampling es el puente entre la tradición musical y el Hip Hop: por él, el funk, el soul, el jazz y la música de todo el mundo entraron en el ADN del rap. También es un archivo viviente: cada sample documenta un disco anterior y lo vuelve a poner en circulación. Y es la práctica que más debates generó en la cultura, entre quienes la ven como robo y quienes, como Schloss, la documentan como una forma de tradición y conversación musical.', funFact: 'La sentencia Grand Upright (1991) contra Biz Markie —por samplear sin permiso "Alone Again (Naturally)"— declaró por primera vez en un tribunal que samplear sin licencia es infracción de copyright, puso fin a la era del sampling sin consecuencias y obligó a la industria a licenciar cada fragmento usado.', related: ['BEATMAKER', 'BREAKBEAT', 'CHOP', 'CONSOLIDA80', 'DRUM_BREAK', 'LOOP', 'MARLEYMARL', 'MPC', 'PRODUCER', 'SAMPLE', 'SAMPLER'] } },
  { word: 'SP_1200', category: 'produccion', difficulty: 'hard', knowledge: { title: 'SP-1200', description: 'El SP-1200 (E-mu SP-1200) es un sampler de batería lanzado por E-mu Systems en agosto de 1987: graba sonidos, los asigna a 8 almohadillas táctiles y programa patrones con su secuenciador, todo en una sola caja portátil. Su sonido es crudo, cálido y granuloso —una combinación de resolución de 12 bits, baja frecuencia de muestreo y filtros analógicos— y ese "suciedad" se volvió la firma sonora del Hip Hop de la edad de oro. Quien lo escucha reconoce los tambores crujientes y los samples recortados de forma entrecortada que definieron el sonido neoyorquino de finales de los 80 y principios de los 90.', importance: 'El SP-1200 definió el sonido de una era: Pete Rock produjo "They Reminisce over You (T.R.O.Y.)" (1992) con uno, RZA lo usó para las bases de Wu-Tang Clan, y DJ Premier, Large Professor, Lord Finesse y J Dilla lo convirtieron en el pilar del boom bap de la Costa Este. Su limitación —10 segundos de sampleo— obligaba a recortar los discos en fragmentos diminutos y a programarlos, una estética que hoy se imita digitalmente. La prensa lo describe como la máquina cuyas virtudes y defectos esculpieron una era entera de música.', funFact: 'El SP-1200 tiene solo 10 segundos de memoria de sample (2,5 segundos por sonido), resolución de 12 bits a 26,04 kHz y filtros analógicos SSM2044: esa combinación de limitaciones es exactamente lo que produce su sonido "sucio" y crujiente, imitado durante décadas por emulaciones digitales.', related: ['BOOM_BAP', 'DRUM_MACHINE', 'GOLDEN_ERA', 'MPC', 'SAMPLER', 'SAMPLING'] } },
  { word: 'STEMS', category: 'produccion', difficulty: 'hard', knowledge: { title: 'Stems (Pistas)', description: 'Los stems (pistas) son grupos de audio mezclados por separado dentro de una canción: por ejemplo, un stem de batería, uno de bajo, uno de cuerdas y uno de voz, cada uno entregado como archivo propio. La definición clásica (Norman Hollyn) dice que un stem es una colección discreta o agrupada de fuentes de audio mezcladas para tratarse aguas abajo como una unidad. No son las pistas individuales del proyecto: son "sub-mezclas" que permiten re-trabajar una canción sin reconstruirla desde cero (ver `arrangement`).', importance: 'Los stems son el formato de la colaboración moderna: hacen posible el remix, la licencia comercial del beat, la re-mezcla de sonido en vivo y el trabajo en equipo de ingenieros. Son la prueba de que, en la producción actual, la canción ya no es un archivo único sino un conjunto de partes intercambiables.', funFact: 'Un stem es un grupo de audio mezclado por separado (p. ej., batería completa, bajo, voz), distinto de las pistas individuales; la convención D-M-E del cine (diálogo, música, efectos) es su origen documentado.', related: ['ARRANGEMENT', 'BEAT', 'PRODUCER', 'REMIX', 'SAMPLING'] } },
  { word: 'SWING', category: 'produccion', difficulty: 'hard', knowledge: { title: 'Swing', description: 'El swing es el desplazamiento rítmico que hace que un beat "respire" como si lo tocara un humano: las notas que caen en la segunda semicorchea de cada pulso se retrasan un poco, creando un vaivén entre nota larga y nota corta. En las cajas de ritmos y programas de música se mide en porcentaje: 50 % es sin swing (todo recto) y 66 % es el swing perfecto de tresillo, donde la primera nota de cada par dura el doble que la segunda. Es la diferencia entre un beat mecánico y un beat que hace mover la cabeza.', importance: 'El swing es el puente entre la máquina y el cuerpo: sin él, el beat programado suena a metrónomo; con él, suena a batería humana y a funk. Es una de las razones por las que los beats de la era dorada siguen sonando vivos, y la herramienta con la que cada generación de productores define su firma rítmica, del boom bap (ver `boom-bap`) al lo-fi.', funFact: 'El swing se mide en porcentaje: 50 % es sin swing y 66 % es el "tresillo perfecto"; Roger Linn, diseñador de la LM-1 y del MPC60, introdujo el swing en su caja LM-1 de 1979, según su propio testimonio.', related: ['BOOM_BAP', 'BREAKBEAT', 'DRUMPROG', 'DRUM_MACHINE', 'MPC', 'QUANTIZATION'] } },
  { word: 'SYNTH', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Sintetizador', description: 'El sintetizador (synth) es un instrumento que genera sonido electrónicamente —con osciladores, filtros y envolventes— en vez de reproducir grabaciones: no necesita grabar nada, produce el sonido desde cero. Puede imitar instrumentos reales (aproximadamente) o crear texturas que no existen en la naturaleza, desde el bajo grave y redondo del Minimoog hasta los pads brillantes del Juno. En el Hip Hop cumple dos papeles: es el sonido que los productores samplean de otros discos y, a la vez, el instrumento con el que tocan líneas de bajo y melodías originales cuando no quieren (o no pueden) samplear (ver `sampling`, `sample` y `bassline`).', importance: 'El sintetizador amplió la paleta del Hip Hop más allá de los discos sampleados: le dio al género sus bajos profundos, sus acordes brillantes y su estética futurista, y permitió a los productores crear música original sobre las bases sampleadas. Es, junto a la caja de ritmos y el sampler, uno de los tres pilares instrumentales del beatmaking (ver `drum-machine` y `sampler`).', funFact: 'Según el testimonio de Afrika Bambaataa, "Planet Rock" (1982) no sampleó a Kraftwerk: el teclista John Robie tocó las líneas en un sintetizador para que sonaran como el grupo alemán; es una de las controversias más citadas de la historia del Hip Hop.', related: ['BAMBAATAA', 'BASSLINE', 'BEAT', 'BEATMAKER', 'DRUM_MACHINE', 'HIP_HOP', 'SAMPLE', 'SAMPLING'] } },
  { word: 'ALBUM', category: 'historia', difficulty: 'easy', knowledge: { title: 'Álbum', description: 'Un álbum es la obra musical de larga duración: en vinilo, el LP (long play) de 12 pulgadas a 33⅓ rpm que permite unos 20 minutos por cara, y en la práctica actual un lanzamiento de unas 8 a 15 canciones y entre 30 y 60 minutos. En el rap, el álbum es el formato donde un artista presenta un proyecto completo, con identidad propia, en lugar de un tema suelto. Se distingue del single (una sola canción, ver `single`) y del EP (formato intermedio de pocos temas, ver `ep`).', importance: 'El álbum convirtió el rap en arte de larga duración: dio espacio a la producción cuidada, al storytelling (ver `storytelling`) y a la coherencia sonora que un single no permite. También fue la base del negocio: el LP (y luego el CD) era el producto que sostenía a sellos y artistas, frente al mixtape callejero no comercial (ver `mixtape`).', funFact: '"The Message" (1982) de Grandmaster Flash and the Furious Five dura 36 minutos con 58 segundos, incluye el tema homónimo de 7:12 y "The Adventures of Grandmaster Flash on the Wheels of Steel", y fue el primer álbum de rap al que la prensa seria trató como obra artística.', related: ['EP', 'EXPANSION80S', 'GRABACIONES', 'HIP_HOP', 'MIXTAPE', 'RAPDELIGHT', 'SINGLE'] } },
  { word: 'ALTHIPHOP', category: 'historia', difficulty: 'hard', knowledge: { title: 'Alternative hip hop', description: 'El alternative hip hop es el rap que se salió del molde del mainstream: en vez de seguir los estereotipos del gangsta rap y del rap de club, sus artistas mezclaron sampleos de jazz, soul y rock, letras introspectivas o conscientes y una estética propia que a veces sonaba más a rock alternativo que a radio de Hip Hop. Nació en Estados Unidos a mediados y fines de los años 80 y creció en circuitos de sellos independientes, aunque varios de sus discos llegaron a vender millones.', importance: 'El alternative hip hop abrió la puerta a que el rap no tuviera que sonar de una sola manera: demostró que se podía samplear jazz, vestirse distinto, hablar de introspección y aun así ser importante, y es la línea que conecta al rap consciente con el experimental y el lo-fi actuales.', funFact: 'En 1996, The Fugees llegaron al #1 del Billboard 200 con *The Score*, que por un tiempo fue el álbum de Hip Hop más vendido de la historia.', related: ['BOOM_BAP', 'CONSCIOUSRAP', 'EXPERIMENTAL', 'JAZZ_RAP', 'SAMPLING', 'UNDERGROUND'] } },
  { word: 'BOOM_BAP', category: 'historia', difficulty: 'medium', knowledge: { title: 'Boom Bap', description: 'El boom bap es el sonido de batería más característico del Hip Hop de Nueva York: un bombo (kick) que suena "boom" y una caja (snare) que responde "bap", construidos a partir de samples de discos de jazz, funk y soul. Nació en los 80 con los primeros samplers, dominó el rap de la costa este en los 90 y hoy sigue siendo la firma sonora del rap clásico: seco, contundente y hecho para que la voz del MC brille por encima del beat (ver `sampling`, `drum-break`).', importance: 'El boom bap es el sonido que definió el rap de Nueva York y la golden era: demostró que un beat podía construirse por capas a partir de discos viejos y que la batería podía ser tan protagonista como la voz. Es también el puente entre el DJ de los 70 y el productor de los 90 (ver `productores-historicos`): el mismo golpe que Kool Herc alargaba con dos copias del disco, el sampler lo convirtió en el latido de una generación. Hoy sigue siendo el sonido de referencia del rap "clásico" y de sus revivals.', funFact: '"Boom bap" es una onomatopeya: "boom" imita el golpe del bombo (kick) y "bap" el de la caja (snare). Según el testimonio de T La Rock, la frase quedó grabada por primera vez en "It\'s Yours" (1984), el single que además fue el primer lanzamiento de Def Jam según el archivo de la Universidad de Cornell.', related: ['BREAKBEAT', 'CONSOLIDA80', 'DJ', 'DRUM_BREAK', 'DRUM_MACHINE', 'FLASH', 'GOLDEN_ERA', 'KICK', 'MPC', 'PRODUCTORES', 'SAMPLE', 'SAMPLING', 'SNARE', 'SP_1200'] } },
  { word: 'CONCEPTALBUM', category: 'historia', difficulty: 'medium', knowledge: { title: 'Álbum conceptual', description: 'Un álbum conceptual es un disco cuyos temas comparten un tema central o una narrativa que los une: el conjunto vale más que la suma de las canciones. En el rap, toma la forma de discos que cuentan una historia de principio a fin, describen un mundo cerrado o siguen a un personaje a lo largo de los cortes. Es la apuesta máxima del formato álbum (ver `album`): no una colección de temas, sino una obra pensada como unidad.', importance: 'El álbum conceptual demostró que el rap podía contar historias a escala de obra completa y con ambición de arte serio: elevó el prestigio crítico del género, amplió sus herramientas narrativas (personajes, interludios, arcos) y dio forma a algunos de los discos más celebrados de su historia.', funFact: '"Only Built 4 Cuban Linx..." (1995) fue pensado como una película: Raekwon "protagonista", Ghostface Killah "estrella invitada" y RZA "director", con la narrativa de dos hombres que planean un último golpe antes de retirarse.', related: ['ALBUM', 'CONSCIOUSRAP', 'GANGSTA_RAP', 'G_FUNK', 'STORYTELLING'] } },
  { word: 'CONSCIOUSRAP', category: 'historia', difficulty: 'medium', knowledge: { title: 'Conscious Rap', description: 'El conscious rap es el rap que pone el foco en la conciencia social: racismo, violencia policial, pobreza, desigualdad, historia y "knowledge of self" (conocimiento de uno mismo), en lugar del dinero, el estatus o la fiesta. No es un sonido único —puede ir sobre boom bap (ver `boom-bap`) o sobre samples de jazz (ver `jazz-rap`)— sino una elección de contenido: el rapero consciente le habla al oyente de los problemas del mundo en que vive y le pide mirarlos de frente.', importance: 'El conscious rap aportó al Hip Hop su dimensión de conciencia crítica: la idea de que el rap no solo entretiene, sino que documenta, denuncia y educa. Es la corriente que conecta al género con sus raíces en la tradición oral afroamericana y con el activismo, y la que le dio al rap su legitimidad como voz de las comunidades. Frente al gangsta rap —que retrata la calle—, el conscious rap propone analizarla y cambiarla; juntos forman la tensión central del contenido del Hip Hop.', funFact: 'Según la Carnegie Hall (Timeline of African American Music), los sonidos y letras de Public Enemy, Boogie Down Productions y KRS-One pasaron a conocerse como "conscious rap", y Chuck D describió a Public Enemy como "la CNN de la América negra": el rap como noticiero de su comunidad.', related: ['BOOM_BAP', 'GANGSTA_RAP', 'GOLDEN_ERA', 'GRABACIONES', 'HIP_HOP', 'JAZZ_RAP', 'MC'] } },
  { word: 'DRILL', category: 'historia', difficulty: 'medium', knowledge: { title: 'Drill', description: 'El drill es un subgénero nacido en Chicago a inicios de los 2010s: suena como un trap más rápido, más frío y más sincopado, con hi-hats nerviosas que la BBC describió como el tableteo de una ametralladora, bajos 808 y letras ominosas sobre rivalidades de pandillas y retaliaciones. Nació en el South Side de Chicago, se expandió a Londres (UK drill) y a Brooklyn (Brooklyn drill), y hoy la BBC lo llama "el sonido de la juventud global". Es, junto al trap, el subgénero más influyente del rap joven.', importance: 'El drill renovó el rap de calle a escala global: definió el sonido del rap joven de los 2010s y 2020s (del UK drill al Brooklyn drill y al Detroit drill), y puso sobre la mesa, con crudeza sin precedentes, la discusión sobre la relación entre la música y la violencia real.', funFact: 'Según Wikipedia, el rapero Pac Man es acreditado como el originador estilístico del drill: su tema "It\'s a Drill" (2010) es el primer uso del término ligado al género.', related: ['BEAT', 'BEEF', 'DRUM_MACHINE', 'GANGSTA_RAP', 'HIP_HOP', 'TRAP'] } },
  { word: 'EP', category: 'historia', difficulty: 'easy', knowledge: { title: 'EP', description: 'Un EP (extended play, "reproducción extendida") es una grabación con más temas que un single pero menos que un álbum: por convención, de 4 a 8 canciones y entre 15 y 30 minutos de duración. En el rap es el formato intermedio: permite presentar un proyecto corto, un puñado de temas con identidad propia, sin comprometerse a la escala de un LP (ver `album`). En vinilo, el EP clásico era el disco de 7 pulgadas con dos temas por cara, y en el rap también funcionó como EP el 12 pulgadas con varios cortes.', importance: 'El EP le dio al rap un formato de ambición media: lanzar obra sin el costo ni la escala del álbum. Fue la plataforma de despegue de artistas (el caso Slim Shady EP es el ejemplo documentado más citado) y hoy sigue siendo la pieza intermedia del mercado entre el single y el álbum.', funFact: '"The Slim Shady EP" de Eminem (1997) se imprimió en solo 500 copias y vendió poco más de 250; aun así, ese EP de 8 pistas fue lo que llevó al rapero hasta Dr. Dre, que al escucharlo dijo, según su testimonio: "Encontrarlo. Ahora".', related: ['ALBUM', 'DJ', 'MIXTAPE', 'REMIX', 'SINGLE'] } },
  { word: 'DISCO', category: 'historia', difficulty: 'medium', knowledge: { title: 'Era Disco', description: 'La era disco es el periodo en que la música disco dominó la música popular —sobre todo en Estados Unidos, a mediados y fines de los años 70— y que funcionó como contexto musical inmediato del nacimiento del Hip Hop. La disco aportó al Hip Hop su materia prima: los discos con breaks bailables que los DJs del Bronx alargaban en las block parties, y el primer gran éxito del rap se construyó sobre un tema disco, "Good Times" de Chic (ver `block-party`, `breakbeat`).', importance: 'La era disco es el contexto musical sin el cual no se entiende el nacimiento del Hip Hop: aportó los discos, los breaks y el modelo de DJ que la nueva cultura transformó. "Good Times" de Chic, la base de "Rapper\'s Delight", es el puente literal entre la disco y el rap: el momento en que el sonido de la pista de baile se convirtió en la base del Hip Hop grabado (ver `primeras-grabaciones`).', funFact: '"Rapper\'s Delight" (1979), el primer gran éxito del rap, se construyó sobre la base de "Good Times" de Chic, un tema disco de ese mismo año: la era disco no solo precedió al Hip Hop, sino que le entregó la base de su primera grabación exitosa.', related: ['BLOCK_PARTY', 'BREAK', 'BREAKBEAT', 'DJ', 'DJ_KOOL_HERC', 'GRABACIONES', 'HIP_HOP', 'OLD_SCHOOL', 'RAPDELIGHT'] } },
  { word: 'ESTILOSREG', category: 'historia', difficulty: 'hard', knowledge: { title: 'Estilos regionales', description: 'Los estilos regionales son las formas que el rap adoptó fuera de su cuna neoyorquina: cada ciudad y cada país desarrolló su propio sonido, su propia cadencia y sus propios temas, a partir de la base común del Hip Hop (ver `hip-hop`). Nueva York, Los Ángeles, el Sur de Estados Unidos, Londres o París no son variantes menores de un mismo género, sino escenas con historia propia que se influyeron entre sí. Este mapa se presenta como descripción documentada, sin ranking de importancia.', importance: 'Los estilos regionales demostraron que el rap podía ser a la vez global y local: cada escena aportó un sonido, un slang y una identidad que enriquecieron el género. El mapa regional explica la historia comercial del rap —del dominio neoyorquino al auge del Sur— y muestra cómo el Hip Hop se convirtió en el lenguaje musical más adaptado del mundo, del Bronx a París, de Memphis a Londres.', funFact: 'Memphis, una ciudad sin industria discográfica propia, desarrolló desde mediados de los 80 un rap de baja fidelidad con la TR-808 que está documentado como semilla del crunk, el trap y el phonk; y sus representantes Three 6 Mafia ganaron el Oscar a la Mejor Canción Original en 2006.', related: ['BOOM_BAP', 'CONSCIOUSRAP', 'DRILL', 'GANGSTA_RAP', 'G_FUNK', 'HIP_HOP', 'TRAP', 'UNDERGROUND'] } },
  { word: 'EXPERIMENTAL', category: 'historia', difficulty: 'hard', knowledge: { title: 'Experimental hip hop', description: 'El experimental hip hop es el rap que rompe las reglas: estructuras raras, tempos que cambian, ruido, industrial, sampleos imposibles y personajes fuera de serie. No tiene un sonido único —cada artista experimental inventa el suyo—, pero comparte la actitud de tratar el Hip Hop como laboratorio en vez de como fórmula. Va de la máscara de MF DOOM a la agresión de Death Grips, del pop roto de Kanye West al shock de Tyler, the Creator.', importance: 'El experimental es el laboratorio del Hip Hop: de él salen las técnicas y estéticas que después se popularizan (del sampleo abstracto al industrial), y demuestra que el género puede absorber cualquier sonido sin perder identidad. Es también el puente entre el rap y las vanguardias artísticas.', funFact: 'Death Grips lanzó *No Love Deep Web* (2012) por BitTorrent para saltarse a su propio sello, que planeaba publicarlo en 2013; la discográfica los despidió, y el disco se volvió un caso célebre de autonomía radical en el rap.', related: ['ALTHIPHOP', 'BEAT', 'HIP_HOP', 'SAMPLING', 'UNDERGROUND'] } },
  { word: 'G_FUNK', category: 'historia', difficulty: 'hard', knowledge: { title: 'G-Funk', description: 'El G-funk es el sonido del gangsta rap de Los Ángeles en los 90: bajos sintetizados profundos, sintetizadores melódicos inspirados en el P-Funk, batería lenta y relajada, y voces que cantan más que rapean. Lo popularizó Dr. Dre con *The Chronic* (1992) y dominó la costa oeste durante la primera mitad de la década, convirtiéndose en la firma sonora que distinguió al rap de Los Ángeles del boom bap de Nueva York (ver `boom-bap`). Es un subgénero de producción: no define un contenido, sino un sonido, aunque nació ligado al gangsta rap (ver `gangsta-rap`).', importance: 'El G-funk definió el sonido de la costa oeste y demostró que el rap podía construir un mundo sonoro completo: bajo, sintetizador, funk sampleado y melodía cantada, con un tempo que invitaba al paseo en auto. Le dio al gangsta rap su banda sonora más exitosa, consolidó a Death Row como la gran potencia del rap de los 90 y estableció el modelo del productor-compositor que re-toca y rearma la música de los discos (ver `productores-historicos`). Su influencia llega hasta hoy: cada revival del sonido de la costa oeste vuelve al G-funk.', funFact: '*The Chronic* de Dr. Dre se lanzó el 15 de diciembre de 1992 por Death Row Records e Interscope y se convirtió en triple platino; según Wikipedia, una de sus marcas de producción era usar músicos en vivo que re-tocaban la música de los discos sampleados, en lugar de reproducir los samples directamente.', related: ['BASSLINE', 'DRUM_MACHINE', 'ESTILOSREG', 'GANGSTA_RAP', 'GOLDEN_ERA', 'HARDCORE_RAP', 'PRODUCTORES', 'SAMPLING', 'SYNTH'] } },
  { word: 'GANGSTA_RAP', category: 'historia', difficulty: 'medium', knowledge: { title: 'Gangsta Rap', description: 'El gangsta rap es el rap que narra la vida de la calle desde dentro: la violencia, el narcotráfico, la pobreza, la policía y la supervivencia en los barrios marginados de Estados Unidos. Nació en los 80 entre Filadelfia y Los Ángeles, explotó a nivel nacional con N.W.A en 1988 y se convirtió en el subgénero más exitoso y más controvertido del Hip Hop: su crudeza le ganó millones de discos, la atención del FBI y un debate cultural que dura hasta hoy.', importance: 'El gangsta rap aportó al Hip Hop su cara más cruda y su mayor éxito comercial: demostró que el rap podía contar la realidad de los barrios sin filtros y aun así vender millones. Dio voz —y visibilidad nacional— a las comunidades negras marginadas de Los Ángeles y otras ciudades, convirtió a la costa oeste en un polo de la cultura frente a Nueva York y abrió el debate sobre la libertad de expresión, la representación y la responsabilidad del arte que acompaña al género hasta hoy. Es, junto al conscious rap (ver `conscious-rap`), la otra mitad de la gran tensión de contenido del Hip Hop.', funFact: '"Fuck tha Police", de N.W.A (1988/1989), provocó una carta de advertencia del FBI a los responsables del grupo y de Ruthless Records: fue el momento en que el Estado respondió oficialmente al gangsta rap, y *Straight Outta Compton* se convirtió en julio de 1989 en el primer álbum del género con certificación de platino.', related: ['CONSCIOUSRAP', 'CONSOLIDA80', 'ESTILOSREG', 'GOLDEN_ERA', 'G_FUNK', 'HARDCORE_RAP', 'HIP_HOP', 'PRODUCTORES'] } },
  { word: 'GOLDEN_ERA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Golden Era', description: 'La golden era —la "era dorada"— es el periodo del Hip Hop, aproximadamente entre mediados de los 80 y mediados de los 90, en que el rap dejó de ser un sonido de fiesta y se volvió un arte de reinvención constante: más rápido, más denso, más complejo. Es la etapa de Rakim y la lírica consciente, de Public Enemy y el rap político, de De La Soul y el sampling juguetón, del boom bap de Nueva York y de los primeros gangsta raps de la costa oeste (ver `boom-bap`, `conscious-rap`, `gangsta-rap`). Muchas fuentes la consideran el pico creativo del género.', importance: 'La golden era aportó la idea de que el rap es un arte con densidad: lírica compleja, producción por capas y diversidad de voces. Dejó los subgéneros que el catálogo documenta en esta misma área —boom bap, jazz rap, conscious rap, gangsta rap— y estableció a Nueva York como el centro creativo del género antes de que la costa oeste equilibrara la balanza. Es la era que la mayoría de las referencias cita cuando habla de "el mejor momento del Hip Hop", y casi todo el rap posterior se mide contra ella.', funFact: 'El crítico Michael Eric Dyson documentó el periodo central de la era dorada —1987 a 1993— como el momento en que el rap afrocéntrico y nacionalista negro fue prominente, y Wikipedia registra que el álbum *Paul\'s Boutique* de los Beastie Boys (1989) usó más de 200 samples: la muestra más citada de la cultura del sampling de la época.', related: ['BOOM_BAP', 'CONSCIOUSRAP', 'CONSOLIDA80', 'ESTILOSREG', 'GANGSTA_RAP', 'HARDCORE_RAP', 'JAZZ_RAP', 'MPC', 'OLD_SCHOOL', 'PRODUCTORES', 'RUN_DMC', 'SAMPLE', 'SAMPLING', 'SP_1200'] } },
  { word: 'HARDCORE_RAP', category: 'historia', difficulty: 'hard', knowledge: { title: 'Hardcore rap', description: 'El hardcore rap es el sonido más crudo y agresivo del Hip Hop: baterías duras, sampleos con actitud y un MC que rapea con energía de confrontación, muchas veces sobre la vida dura de la calle. Se desarrolló en la escena de la Costa Este de Estados Unidos en los años 80 y es la raíz de la que salió el gangsta rap, aunque no todo el hardcore habla de pandillas. No es un estilo de producción único: es una intensidad y una actitud que se reconocen al primer golpe de caja.', importance: 'El hardcore es la vena agresiva del Hip Hop: fijó la intensidad del rap de batalla, alimentó al gangsta rap y a casi todos los subgéneros duros posteriores, y demostró que el rap podía ser un arma de confrontación sin necesidad de pulir el mensaje.', funFact: 'El gangsta rap suele considerarse un subgénero o derivado del hardcore, pero no todo el hardcore es gangsta: según el académico Russell Potter (1995), los raperos hardcore "reclamaron un terreno muy variado".', related: ['BATTLE_RAP', 'BEAT', 'BOOM_BAP', 'DISS', 'GANGSTA_RAP'] } },
  { word: 'JAZZ_RAP', category: 'historia', difficulty: 'medium', knowledge: { title: 'Jazz Rap', description: 'El jazz rap es la fusión del rap con el jazz: beats de Hip Hop construidos sobre samples de jazz —saxos, contrabajos, pianos— o tocados con músicos de jazz en vivo. Es un sonido suave, profundo y espacioso, casi lo opuesto al rap duro y denso: nació en Nueva York a fines de los 80, brilló en la golden era (ver `golden-era`) y sus referentes son Gang Starr, A Tribe Called Quest, Digable Planets y la serie *Jazzmatazz* de Guru.', importance: 'El jazz rap aportó al Hip Hop la conexión con su herencia musical afroamericana: demostró que el rap podía dialogar con el jazz sin perder el beat, y le dio al género una veta de sofisticación, calma y profundidad que contrasta con el rap duro. También amplió la paleta del sampling —el jazz como materia prima— y dejó álbumes que siguen siendo referencias de la golden era. Es, junto al boom bap y el conscious rap, una de las tres grandes aportaciones sonoras del rap de Nueva York de fines de los 80 y los 90.', funFact: '"Words I Manifest" de Gang Starr (1988), el single debut del dúo, sampleaba a Charlie Parker: el jazz estaba en el ADN del rap neoyorquino desde los primeros pasos del subgénero, un año antes de que la golden era lo convirtiera en corriente principal.', related: ['BOOM_BAP', 'CONSCIOUSRAP', 'ESTILOSREG', 'GOLDEN_ERA', 'MPC', 'PRODUCTORES', 'SAMPLE', 'SAMPLING', 'SP_1200'] } },
  { word: 'LOFIHIPHOP', category: 'historia', difficulty: 'hard', knowledge: { title: 'Lo-fi hip hop', description: 'El lo-fi hip hop es un subgénero relajado que combina beats de Hip Hop con estética de baja fidelidad: tempos lentos, pianos y guitarras suaves, sampleos nostálgicos y un acabado "imperfecto" a propósito —hiss de vinilo, grano de cinta, chasquidos— que suena como una memoria musical. Se popularizó en YouTube en los 2010s con streams de 24 horas, como "lofi hip hop radio - beats to relax/study to" de Lofi Girl, y se convirtió en la banda sonora del estudio y la relajación de toda una generación.', importance: 'El lo-fi hip hop demostró que el Hip Hop instrumental podía ser un espacio de calma y no solo de energía, y convirtió la estética de la imperfección (hiss, grano, swing suelto) en un lenguaje global. También es uno de los grandes fenómenos de escucha de la era del streaming: millones de personas estudian y trabajan con sus beats.', funFact: 'El canal Lofi Girl (antes ChilledCow) transmite "lofi hip hop radio - beats to relax/study to" desde febrero de 2017; su stream llegó a acumular más de 13.000 horas seguidas, uno de los videos más largos de YouTube.', related: ['ALTHIPHOP', 'BEAT', 'JAZZ_RAP', 'JDILLA', 'SAMPLE', 'SAMPLING', 'SOUNDTRACK'] } },
  { word: 'NEW_SCHOOL', category: 'historia', difficulty: 'easy', knowledge: { title: 'New School', description: 'La new school —la nueva escuela— es el movimiento del Hip Hop de mediados de los años 80 que renovó el rap tras la era old school: liderado por Run-DMC, LL Cool J y Beastie Boys, impuso un sonido más duro y minimalista —cajas de ritmos, pocos elementos, scratch—, rimas más agresivas y de autofirmación, y una imagen callejera (buzos, zapatillas, sombreros) que rompía con la estética disco-funk de la generación anterior (ver `old-school`). Con el new school, el rap dejó de ser música de fiesta para convertirse en el sonido dominante del Hip Hop mainstream (ver `consolidacion-80s`).', importance: 'El new school separó el rap de su primera era y definió el Hip Hop moderno: el sonido de la caja de ritmos y el scratch como base, el MC como voz dura de la calle y la imagen del rapero como figura mainstream. Es el puente entre el old school y la era dorada (ver `old-school`, `golden-era`): sin Run-DMC y su generación, el rap no habría pasado de ser un sonido de fiesta a convertirse en la cultura global que es hoy.', funFact: 'Run-DMC marcó el inicio documentado del new school con "It\'s Like That"/"Sucker M.C.\'s" (1983) —según Peter Shapiro, ese sencillo "cambió completamente el Hip Hop"— y consolidó la era con su álbum debut (1984) y *Raising Hell* (1986, platino, con el crossover "Walk This Way" junto a Aerosmith).', related: ['BEAT', 'BREAKBEAT', 'CONSOLIDA80', 'DJ', 'EXPANSION80S', 'GOLDEN_ERA', 'HIP_HOP', 'MC', 'OLD_SCHOOL', 'RAPDELIGHT', 'RUN_DMC'] } },
  { word: 'OLD_SCHOOL', category: 'historia', difficulty: 'medium', knowledge: { title: 'Old School', description: 'El old school es la primera era del rap: el sonido de las fiestas del Bronx que llegó a los discos entre fines de los 70 y mediados de los 80. Es el rap de las block parties —ritmos bailables, rimas simples, shoutouts al barrio—, el que se grabó por primera vez en 1979 y el que sentó todas las bases: el break del DJ (ver `break`, `breakbeat`), el MC que anima (ver `mc`) y el rap como música de fiesta antes que como música de mensaje o de industria.', importance: 'El old school aportó la materia prima de toda la cultura: el break como base musical, el MC como voz, el rap como música de celebración de barrio y las primeras grabaciones que convirtieron la fiesta en industria. También dejó el molde del rapero de la vieja escuela: rimas simples, presencia, flow de fiesta y lealtad al barrio. La era siguiente construyó sobre estos cimientos —y a veces contra ellos—, pero los sonidos, las técnicas y las historias de esta etapa siguen siendo el punto de partida obligado de cualquier historia del Hip Hop.', funFact: '"The Message" (1982), de Grandmaster Flash and the Furious Five, escrita por Duke Bootee y Melle Mel, está documentada como el momento en que el rap pasó del tema de fiesta al comentario social: es el antecedente directo de todo el rap de mensaje que vino después, desde Public Enemy hasta el conscious rap (ver `conscious-rap`).', related: ['BAMBAATAA', 'BREAK', 'BREAKBEAT', 'CONSOLIDA80', 'DJ', 'DJ_KOOL_HERC', 'EXPANSION70S', 'FLASH', 'GRABACIONES', 'HIP_HOP', 'JAM', 'MC', 'RAPDELIGHT'] } },
  { word: 'REMIX', category: 'historia', difficulty: 'medium', knowledge: { title: 'Remix', description: 'Un remix es una versión alternativa de una canción: se cambia la base musical, se alarga, se reordena, se le añaden voces o se transforma el sonido original para crear algo nuevo a partir de la grabación existente. No es una versión en vivo ni una nueva grabación del tema (eso sería un cover): es el mismo material, tratado como materia maleable. En el rap, el remix oficial suele ser un acontecimiento: el tema original más estrofas nuevas de otros MCs invitados.', importance: 'El remix es la prueba sonora de la tesis del Hip Hop: ninguna grabación es sagrada, todo puede rehacerse. Extendió la vida comercial de los temas, conectó artistas de distintos niveles y fue el laboratorio donde muchos productores aprendieron a construir beats.', funFact: '"Seven Minutes of Madness", el remix que Coldcut hizo de "Paid in Full" de Eric B. & Rakim (octubre de 1987), dura 7 minutos y fue uno de los primeros remixes en entrar a las listas de varios países, allanando la entrada del rap al Reino Unido.', related: ['BEAT', 'DJ', 'MIXTAPE', 'PRODUCER', 'SAMPLING', 'SINGLE', 'TURNTABLE'] } },
  { word: 'SINGLE', category: 'historia', difficulty: 'easy', knowledge: { title: 'Single', description: 'Un single es una canción publicada como unidad comercial independiente, con el objetivo de promocionarse en la radio y en las listas de ventas. Originalmente era un disco pequeño de 7 pulgadas a 45 rpm con unos tres o cuatro minutos por cara; en el rap, el formato característico fue el de 12 pulgadas, con la versión larga en una cara y la instrumental en la otra. Es la pieza más corta del trío de formatos: menos que el EP (ver `ep`) y mucho menos que el álbum (ver `album`).', importance: 'El single fue la puerta del rap a la radio, a las listas y al público masivo: sin él, el rap habría quedado en las fiestas. Además, consolidó la relación del rap con los DJs y la pista de baile, porque el 12 pulgadas fue pensado para ser pinchado y mezclado.', funFact: '"Rapper\'s Delight" (1979) llegó al puesto 36 del Billboard Hot 100 siendo la primera canción del Top 40 que solo se vendía en versión extendida de 12 pulgadas: la versión larga dura 14 minutos con 37 segundos.', related: ['ALBUM', 'DJ', 'EP', 'EXPANSION80S', 'GRABACIONES', 'MIXTAPE', 'RAPDELIGHT', 'REMIX'] } },
  { word: 'SOUNDTRACK', category: 'historia', difficulty: 'medium', knowledge: { title: 'Soundtrack', description: 'Un soundtrack (banda sonora) es la música asociada a una película, publicada como disco: temas de los artistas que aparecen en la cinta o canciones inspiradas en ella. En el rap, los soundtracks acompañaron a las películas del género desde sus comienzos, y varios se volvieron discos importantes por derecho propio, a veces más exitosos que la propia película. Funcionan como un álbum (ver `album`) con la particularidad de estar anclados a una historia visual.', importance: 'El soundtrack acercó el rap al cine y al público masivo, documentó la cultura en su propia época (Wild Style sigue siendo la referencia visual de los primeros años) y demostró que el rap podía conquistar las instituciones más tradicionales del entretenimiento, con el Oscar de "Lose Yourself" como hito.', funFact: '"Wild Style" es considerada la primera película de hip hop (1982/1983), y su banda sonora, publicada en 1983, fue definida por AllMusic como "uno de los discos clave del rap de comienzos de los 80".', related: ['ALBUM', 'BREAKBEAT', 'DJ', 'HIP_HOP', 'MIXTAPE'] } },
  { word: 'TRAP', category: 'historia', difficulty: 'medium', knowledge: { title: 'Trap', description: 'El trap es el subgénero del Hip Hop que domina el siglo XXI: nació en Atlanta y se reconoce al instante por los graves profundos de 808, las hi-hats rapidísimas (a menudo en tresillos), los tempos lentos que se programan al doble y una atmósfera oscura y sintetizada. El nombre viene del "trap house", la casa donde se vende droga, y sus letras hablaron al principio de esa vida y del camino hacia el éxito. Hoy el trap es una familia enorme que incluye desde el Latin trap hasta el EDM trap, el emo rap y el rage.', importance: 'El trap es el motor del Hip Hop del siglo XXI: definió la producción moderna (el 808 y las hi-hats de tresillos), convirtió a Atlanta en capital mundial del género y generó una familia de subgéneros que va del drill al Latin trap. Ningún otro subgénero del rap moderno ha tenido su alcance.', funFact: 'Un beat de trap típico va a unos 70 BPM (programados a 140 en tiempo doble), con hi-hats divididas en tresillos y un subgrave de 808: la combinación de lentitud y velocidad que lo hace inconfundible.', related: ['BASS', 'BEAT', 'DRILL', 'DRUM_MACHINE', 'GANGSTA_RAP', 'HI_HAT'] } },
  { word: 'UNDERGROUND', category: 'historia', difficulty: 'medium', knowledge: { title: 'Underground', description: 'El underground es la escena del Hip Hop que vive por fuera del circuito mainstream: artistas sin contrato grande, beats hechos en casa o en estudios chicos, mixtapes, freestyles en radios universitarias y una relación directa con el público por internet. No es un sonido único —hubo underground de rap consciente, experimental y también de trap— sino una forma de existir al margen de la industria, que muchas veces termina siendo la cantera de donde la industria saca sus próximas estrellas.', importance: 'El underground es la cantera del Hip Hop: mantiene viva la lógica del mixtape, del cypher y del freestyle, y ha alimentado al mainstream con casi todos sus sonidos nuevos, del conscious rap de los 90 al trap y al drill de hoy.', funFact: '*The Stretch Armstrong and Bobbito Show* (1990–1999) se hizo famoso por abrir su micrófono a MCs sin contrato: muchos artistas consiguieron difusión y contratos tras aparecer en el programa.', related: ['ALTHIPHOP', 'CONSCIOUSRAP', 'CYPHER', 'DJ', 'EXPERIMENTAL', 'MC', 'MIXTAPE'] } },
  { word: 'CODIGO', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Código del Hip Hop', description: 'El código es el conjunto de normas no escritas que ordenan la vida del Hip Hop: el respeto entre pares, la autenticidad, la prohibición de copiar el estilo de otro y las reglas del cypher. No está en ningún libro: se aprende en la calle, se transmite de boca en boca y se pone a prueba en cada jam, batalla o círculo.', importance: 'El código explica cómo el Hip Hop se gobierna a sí mismo: sin leyes escritas, la reputación, el respeto y la autenticidad funcionan como justicia de la escena. Quien bitea (copia), miente sobre su historia o falta el respeto, se queda sin lugar en el círculo: entender esa lógica es entender la cultura desde adentro.', funFact: 'La Hip Hop Declaration of Peace, presentada el 16 de mayo de 2001 ante la ONU por el Temple of Hip Hop, intentó poner por escrito en 18 principios el código que el Hip Hop transmite oralmente desde los años 70.', related: ['BATTLE', 'CREW', 'CYPHER', 'HIP_HOP', 'ORIGINALITY', 'RESPECT'] } },
  { word: 'COMMUNITY', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Comunidad', description: 'La comunidad es la base del Hip Hop: la cultura nació y se vive en grupo, del block party al cypher. No hay Hip Hop de un solo individuo: hay crews que entrenan juntas (ver `crew`), fiestas donde el barrio se reúne y círculos donde todos participan. Entender el Hip Hop es entender que primero fue una comunidad —un barrio, una generación— y después un arte.', importance: 'La comunidad es el marco donde tienen sentido los demás valores de la cultura: la competencia es entre pares que se conocen (ver `cypher`), el respeto se gana frente a la comunidad, la identidad se construye en grupo (ver `crew`). Sin comunidad no hay block party, ni jam, ni cypher, ni la memoria que la cultura transmite de generación en generación. Entender que el Hip Hop es primero comunidad permite entender por qué ninguna disciplina se practica en soledad y por qué la cultura sobrevivió a la industria: la comunidad es su base.', funFact: 'La frase más citada para resumir el valor de la comunidad es de KRS-One: "Rap is something you do, Hip Hop is something you live" (el rap es algo que haces; el Hip Hop es algo que vives), del tema "Hip Hop vs. Rap" (1993): el Hip Hop se vive en comunidad, no se consume en soledad.', related: ['BLOCK_PARTY', 'CREW', 'CYPHER', 'HIP_HOP', 'JAM', 'UNITY', 'ZULU_NATION'] } },
  { word: 'COMPETITION', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Competencia', description: 'La competencia es el motor del Hip Hop: las batallas de breaking, las batallas de MCs, las competencias de DJs y de writers. En el cypher (ver `cypher`), la competencia es sana: se compite por demostrar más estilo, no por destruir al rival. Es la forma en que la cultura se supera a sí misma: cada uno sube el nivel del otro, y el público decide quién ganó.', importance: 'La competencia es el motor de la evolución del Hip Hop: cada batalla sube el nivel técnico y creativo de todos, porque el rival obliga a mejorar (ver `creativity`). También es la escuela del respeto: se compite cara a cara, delante de la comunidad (ver `community`), y la cultura premia al que gana con estilo propio, no al que destruye al otro. Sin competencia no habría evolución del breaking, del freestyle ni del battle-rap.', funFact: 'El DMC World DJ Championships, fundado en 1985 en Londres por el Disco Mix Club, es el certamen mundial de DJs más antiguo: un torneo que nació de las batallas de tocadiscos de los años 80 y que sigue coronando campeones mundiales del turntablism.', related: ['BATTLE', 'BATTLE_RAP', 'BLOCK_PARTY', 'B_BOY', 'CREW', 'CYPHER', 'FREESTYLE', 'JAM', 'RESPECT', 'ROCKSTEADY'] } },
  { word: 'CREATIVITY', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Creatividad', description: 'La creatividad es el motor del Hip Hop: la capacidad de hacer algo de nada —"make something from nothing"—, de transformar recursos mínimos, dos tocadiscos, una pared, una caja de cartón, en arte. Su expresión más clara es la cultura del sampleo (ver `sampling`): tomar fragmentos de otros discos y construir algo nuevo. El Hip Hop no esperó a tener instrumentos ni dinero: creó sus propios instrumentos.', importance: 'La creatividad es lo que distingue al Hip Hop de una moda: reciclar como creación. Sin creatividad no habría sampleo, ni scratching, ni freestyle, ni la cultura del "hacer algo de la nada" que todavía define a la escena en todo el mundo. Es también el valor que conecta con la originalidad (ver `originality`): crear algo propio a partir de lo que existe, sin copiar a nadie.', funFact: '"The Adventures of Grandmaster Flash on the Wheels of Steel" (1981) es considerado el primer disco hecho únicamente con otros discos y tocadiscos, sin músicos de sesión: un collage sonoro que demostró que el DJ es un instrumentista y que un disco puede nacer de otros discos.', related: ['BLOCK_PARTY', 'BREAK', 'DJ', 'DJ_KOOL_HERC', 'FLASH', 'HIP_HOP', 'ORIGINALITY', 'SAMPLING'] } },
  { word: 'CREW', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Crew', description: 'Una crew es un grupo con nombre, identidad y lealtad dentro del Hip Hop: un equipo que entrena, compite y crea junto. La palabra viene del inglés *crew* (grupo, tripulación) y designa la unidad social básica de la cultura: hay crews de writers que pintan juntos, crews de b-boys que bailan y batallan, y crews de MCs y DJs que hacen música. Pertenecer a una crew da nombre, respaldo y territorio simbólico.', importance: 'La crew es el marco de la competencia y la creación en el Hip Hop: sin crews no hay batallas de breaking, ni bombardeos de writers, ni posse cuts, ni la lealtad que sostiene a los artistas en la escena. Entender la crew es entender por qué el Hip Hop es una cultura colectiva: el logro individual siempre se apoya en un grupo con nombre propio.', funFact: 'La crew es transversal: la misma palabra designa a la crew de writers que pinta un tren completo, a la crew de b-boys que entra a batallar al cypher y al grupo de MCs que graba un posse cut: todas comparten nombre, identidad y lealtad.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'BREAKERS70', 'B_BOY', 'CREWS_70S', 'CYPHER', 'DJ_KOOL_HERC', 'HERCULOIDS', 'HIP_HOP', 'JAM', 'POSSE_CUT', 'PRIMEROSMCS', 'ROCKSTEADY', 'TAG', 'WRITERS70', 'ZULU_NATION'] } },
  { word: 'CULTBARR', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Cultura de barrio', description: 'La cultura de barrio es el Hip Hop vivido en su territorio: la versión local, de esquina, de población o de vecindario, donde la cultura global se adapta al barrio concreto — su idioma, sus problemas, sus referencias y su propia historia. Es el Hip Hop como identidad de pertenencia: no una copia de Nueva York, sino el mismo lenguaje puesto a hablar en otro lugar.', importance: 'La cultura de barrio explica por qué el Hip Hop es una cultura global y local a la vez: las escenas de cada barrio reclaman su versión como propia y legitiman su identidad dentro de la cultura (ver `community` e `identity`). Sin ella, el Hip Hop sería un producto importado; con ella, es una voz del territorio.', funFact: 'El libro *Global Noise* (2001) reunió trece ensayos académicos sobre escenas de hip hop fuera de Estados Unidos: la adaptación territorial del género ya estaba documentada como fenómeno global a dos décadas de su nacimiento.', related: ['COMMUNITY', 'ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'CYPHER', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Cypher', description: 'El cypher es el círculo que se forma alrededor de quien demuestra su arte en el Hip Hop: bailarines que entran al centro a batallar, MCs que rapean improvisando, beatboxers marcando el ritmo. Es a la vez un formato de participación —todos miran, cualquiera puede entrar— y un código de la cultura: en el círculo se gana o se pierde reputación frente a los ojos de todos.', importance: 'El cypher condensa un valor central del Hip Hop: la participación directa y la competencia cara a cara, sin escenario que proteja. Entender el cypher es entender por qué el Hip Hop es una cultura de demostración y respeto ganado en público, y por qué el círculo sigue siendo el formato de batallas, showcases y entrenamiento en todo el mundo.', funFact: 'En un cypher, el círculo es a la vez escenario, juez y público: quien entra demuestra su estilo frente a todos, sin esconderse detrás de un escenario ni de un aplauso grabado.', related: ['BLOCK_PARTY', 'BREAK', 'B_BOY', 'HIP_HOP', 'JAM'] } },
  { word: 'ELEMENTS', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Elementos del Hip Hop', description: 'Los elementos del Hip Hop son las disciplinas que, según la narrativa de la cultura, componen el movimiento: la versión más citada lista cuatro —el MCing (el rap, ver `mc`), el DJing (los discos y el break, ver `dj`, `breakbeat`), el Breaking (el baile, ver `b-boy`, `break`) y el Writing (el grafiti)—. A esa lista se le han sumado, según la fuente, el knowledge (quinto elemento según la Zulu Nation), el beatbox (reclamado por tradición oral por la escena del beatbox) y hasta nueve elementos (Hip Hop Declaration of Peace, 2001). La lista exacta es una controversia abierta de la cultura (ver `fifth-element`, `knowledge`).', importance: 'Los elementos son la forma en que la cultura se define a sí misma y se organiza: permiten hablar de un movimiento con disciplinas propias —cada una con su historia, sus técnicas y sus figuras (ver `mc`, `dj`, `b-boy`, `break`)— y no de un simple género musical. El debate sobre cuántos son muestra además que el Hip Hop es una cultura viva que negocia su propia definición.', funFact: 'La lista clásica del Hip Hop tiene cuatro elementos: MCing, DJing, Breaking y Writing. La narrativa de la Zulu Nation agrega knowledge como quinto; la tradición oral del beatbox reclama ese lugar; y la Hip Hop Declaration of Peace (2001) llega a nueve. No hay lista canónica única.', related: ['BAMBAATAA', 'BREAK', 'BREAKBEAT', 'B_BOY', 'DJ', 'FIFTHELEMENT', 'HIP_HOP', 'HUMANBEATBOX', 'KNOWLEDGE', 'MC', 'ZULU_NATION'] } },
  { word: 'EVOLUCION', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Evolución cultural del Hip Hop', description: 'La evolución cultural es el proceso por el cual el Hip Hop cambió con el tiempo y el territorio: de las fiestas de un barrio del Bronx en los años 70 a una cultura global con cientos de escenas locales. No es una historia lineal: cada década sumó estilos, disciplinas y significados, y cada territorio lo rehízo a su manera.', importance: 'La evolución cultural explica la diversidad actual del Hip Hop: cada generación y cada territorio le añadió capas sin romper la continuidad de la cultura. Saber que el Hip Hop siempre cambió ayuda a leer sus formas nuevas (trap, drill, lo-fi) no como traición, sino como un capítulo más de su historia.', funFact: 'En 2001, el libro académico *Global Noise* ya documentaba escenas locales de hip hop en Europa, Canadá, Japón y Australia: en menos de tres décadas el Hip Hop pasó de fiesta de barrio a cultura global con producción académica propia.', related: ['ESTILOSREG', 'EXPANSION70S', 'EXPANSION80S', 'HIP_HOP', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'EXPRESSION', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Expresión', description: 'La expresión es la manifestación cultural del Hip Hop: las disciplinas —el MCing, el DJing, el Breaking y el Writing, entre otras— como lenguajes con los que una comunidad habla de sí misma. No es solo música ni solo baile: es la voz de un barrio y de una generación que no tenía canales para expresarse. Cada disciplina es una vía de expresión con su propio vocabulario, y todas dicen algo de la misma cultura.', importance: 'La expresión es lo que convierte al Hip Hop en cultura: sin las vías de expresión quedaría solo música de fiesta. Entender la expresión es entender por qué un MC, un DJ, un breaker y un writer comparten un mismo impulso, y por qué el Hip Hop pudo hablar por comunidades enteras del mundo (ver `street-culture` y `cultura-de-barrio`): cada disciplina es una puerta de entrada a la misma cultura.', funFact: 'El Hip Hop se describe con "elementos" —vías de expresión— que según la fuente son 4 (MCing, DJing, Breaking, Writing) o más (la narrativa de la Zulu Nation agrega Knowledge y Beatbox): la lista varía, pero la idea es la misma: varias disciplinas, una sola cultura.', related: ['BLOCK_PARTY', 'B_BOY', 'DJ', 'HIP_HOP', 'JAM', 'MC', 'RESISTANCE', 'SELFEXPRES', 'STREETCULT', 'TAG'] } },
  { word: 'FIFTHELEMENT', category: 'cultura', difficulty: 'hard', knowledge: { title: 'Quinto Elemento', description: 'El "quinto elemento" es el nombre que la narrativa de la cultura Hip Hop da al componente que se suma a los cuatro elementos clásicos —MCing, DJing, Breaking y Writing (ver `elements`)—. La versión más difundida, asociada a la Universal Zulu Nation y a Afrika Bambaataa, identifica ese quinto elemento con el knowledge: el conocimiento de la historia, los códigos y la memoria de la cultura (ver `knowledge`). Otras versiones de la escena reclaman ese lugar para el beatbox (ver `beatbox`, `human-beatbox`). No existe una lista canónica única: el quinto elemento es una controversia abierta de la cultura.', importance: 'El debate del quinto elemento importa porque define qué es el Hip Hop para quienes lo practican: una lista de disciplinas o una cultura con un componente de conocimiento que las trasciende. También muestra cómo la cultura se piensa a sí misma: las primacías y las listas se construyen por narrativas de la escena (Zulu Nation, beatboxers, Temple of Hip Hop), no por un registro unívoco.', funFact: 'Según Travis Gosa (2015), el propio Afrika Bambaataa identificó el conocimiento como el quinto elemento del Hip Hop, enmarcado en las "Infinity Lessons" de la Universal Zulu Nation; en paralelo, la tradición oral de la escena del beatbox reclama ese lugar para la percusión vocal (ver `beatbox`).', related: ['BAMBAATAA', 'BEATBOX', 'CONSCIOUSRAP', 'ELEMENTS', 'HIP_HOP', 'HUMANBEATBOX', 'KNOWLEDGE', 'KNOWSELF', 'ZULU_NATION'] } },
  { word: 'HAVING_FUN', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Having Fun', description: 'Having fun (diversión, pasarlo bien) es el cuarto valor del lema que la narrativa de la Universal Zulu Nation difundió como base del Hip Hop: "peace, love, unity and having fun" (paz, amor, unidad y diversión). Es el recordatorio de que el Hip Hop nació de fiestas: antes de ser industria, música grabada o movimiento político, fue gente bailando y celebrando en la calle. Para los pioneros, la diversión no era un extra: era el punto de partida.', importance: 'Having fun es el antídoto contra la solemnidad y el comercio: recuerda que la cultura pertenece a la fiesta, no a la oficina. Para la narrativa Zulu, la diversión fue la puerta de entrada: los jóvenes llegaban por la fiesta y se quedaban por la comunidad y el conocimiento.', funFact: 'El MC Kid Lucky, de la primera generación, recuerda que en los orígenes la gente "break-danceaba contra el otro en vez de pelear": la diversión como alternativa directa a la violencia.', related: ['BAMBAATAA', 'BLOCK_PARTY', 'HIP_HOP', 'JAM', 'LOVE', 'PEACE', 'UNITY', 'ZULU_NATION'] } },
  { word: 'HIP_HOP', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Hip Hop', description: 'El Hip Hop es una cultura nacida en el Bronx de Nueva York en los años 70, construida alrededor de disciplinas propias: el MCing (rap), el DJing, el breaking y el writing (graffiti), junto a otras expresiones como el beatbox y la producción musical. No es un género musical ni una moda: es una cultura de barrio con sus códigos, sus valores y su historia, que se expandió por el mundo y se adaptó a cada territorio.', importance: 'El Hip Hop es el marco que conecta todas las entradas de esta enciclopedia. Entenderlo como cultura —no solo como música— permite entender por qué un DJ, un breaker, un writer y un MC comparten código, valores y memoria, y por qué los juegos de JuegaHipHop pueden construir conocimiento desde cualquier disciplina.', funFact: 'El Hip Hop suele describirse con "elementos" (MCing, DJing, Breaking, Writing, y según la narrativa de la Zulu Nation también Knowledge y Beatbox), pero el número y la lista varían según la fuente: la cultura es más grande que cualquier lista de elementos.', related: ['BLOCK_PARTY', 'BREAK', 'B_BOY', 'DJ_KOOL_HERC', 'ZULU_NATION'] } },
  { word: 'IDENTITY', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Identidad', description: 'La identidad es el Hip Hop como forma de ser: de barrio, de generación, de cultura. No es solo lo que se hace —rapear, bailar, pintar— sino lo que se es: el Hip Hop da nombre, pertenencia y código a quienes lo viven. Por eso se dice que el Hip Hop es una identidad que se lleva puesta, en la forma de hablar, de vestir y de moverse.', importance: 'La identidad es lo que hace que el Hip Hop perdure: la gente no solo consume la cultura, se identifica con ella. Es el puente entre la experiencia individual (ver `self-expression`) y la comunidad (ver `community`): el Hip Hop da identidad a quien lo vive, y cada identidad nueva —de barrio, de país, de generación— enriquece a la cultura.', funFact: 'La identidad del Hip Hop se rehace en cada territorio: el mismo formato global —MCing, DJing, Breaking, Writing— se vuelve identidad local en cada barrio (ver `cultura-de-barrio`), lo que explica por qué el Hip Hop del Bronx se vive distinto al de cualquier otro lugar del mundo sin dejar de ser el mismo Hip Hop.', related: ['CREW', 'CULTBARR', 'HIP_HOP', 'STREETCULT', 'TRADICION', 'UNDERGROUND', 'ZULU_NATION'] } },
  { word: 'JAM', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Jam', description: 'El jam es el evento donde se reúne la escena del Hip Hop: un DJ poniendo música, MCs tomando el micrófono y bailarines ocupando el círculo para batallar o mostrar su estilo. Es el formato de encuentro de la cultura —desde las fiestas del Bronx de los 70 hasta los jams de breaking actuales—, y en él se ven en acción todas las disciplinas a la vez.', importance: 'El jam es el formato que mantiene viva la cultura como comunidad: sin jams no hay escena, porque es en el evento donde se conocen las crews, se aprenden los estilos, se resuelven las batallas y se transmite la historia de boca en boca. Entender el jam es entender cómo el Hip Hop se organiza desde abajo, sin depender de la industria.', funFact: 'El flyer de la fiesta del 11 de agosto de 1973 en Sedgwick Avenue —la más temprana con registro documentado— la anuncia como "Back to School Jam": el jam es el formato de evento más antiguo del Hip Hop con registro conservado.', related: ['BLOCK_PARTY', 'CYPHER', 'DJ_KOOL_HERC', 'HIP_HOP', 'SEDGWICK73'] } },
  { word: 'KNOWSELF', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Knowledge of Self', description: 'Knowledge of self (conocimiento de sí mismo, autoconocimiento) es la idea de que el Hip Hop no solo entrega técnicas, sino también un saber sobre quién eres, de dónde vienes y cuál es tu valor. En la narrativa de la Zulu Nation y en el rap consciente, es la forma más profunda del knowledge: no basta conocer la cultura, hay que conocerse a uno mismo dentro de ella.', importance: 'El knowledge of self le dio al Hip Hop una dimensión espiritual y educativa: la cultura como camino de autoconocimiento y dignidad, especialmente para la juventud negra y latina. Es la base del rap consciente y del "conócete a ti mismo" que la escena repite en escuelas, talleres y comunidades hasta hoy.', funFact: 'Rakim, uno de los MCs más influyentes de la historia, rapeó en "Move the Crowd" (1988): "With knowledge of self, there\'s nothing I can\'t solve" ("con el conocimiento de sí mismo, no hay nada que no pueda resolver").', related: ['BAMBAATAA', 'CONSCIOUSRAP', 'HIP_HOP', 'KNOWLEDGE', 'RESPECT', 'ZULU_NATION'] } },
  { word: 'KNOWLEDGE', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Knowledge', description: 'Knowledge (conocimiento) es el nombre que la narrativa de la Universal Zulu Nation y de Afrika Bambaataa da al llamado "quinto elemento" del Hip Hop. No es una disciplina como el rap, el DJing, el breaking o el writing, sino el saber sobre la propia cultura: su historia, sus códigos, su gente y su memoria. La idea es que quien practica una disciplina del Hip Hop debe conocer también de dónde viene lo que hace.', importance: 'El knowledge convirtió al Hip Hop en una cultura que se piensa a sí misma: memoria, historia y transmisión. Es el puente entre las disciplinas y los valores (peace, unity, love, respect), y la base de la idea de que el Hip Hop puede educar y transformar, no solo entretener. Sin este elemento, la cultura quedaría reducida a estilos sin historia.', funFact: 'Según el investigador Travis Gosa (2015), el propio Afrika Bambaataa identificó el conocimiento como el quinto elemento del Hip Hop, inicialmente enmarcado en las "Infinity Lessons" de la Universal Zulu Nation.', related: ['BAMBAATAA', 'BREAK', 'CONSCIOUSRAP', 'HIP_HOP', 'KNOWSELF', 'ZULU_NATION'] } },
  { word: 'LOVE', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Love', description: 'Love (amor) es el tercer valor del lema que la narrativa de la Universal Zulu Nation difundió como base del Hip Hop: "peace, love, unity and having fun" (paz, amor, unidad y diversión). En el Hip Hop, el amor no es solo el amor romántico de las canciones: es el cariño por la cultura, por la gente del barrio y por los pares de la escena. Es el valor que hace del cypher, la crew y la comunidad espacios de cuidado y no solo de competencia.', importance: 'El amor es el valor que humaniza la competencia del Hip Hop: se puede batallar duro en el cypher y aún así respetar y querer al rival, porque se comparte la misma cultura. Es la base afectiva de la comunidad y de la lealtad entre crews.', funFact: 'El principio 10 de la Hip Hop Declaration of Peace (2001) establece que las relaciones en el Hip Hop deben construirse sobre "amor, confianza, igualdad y respeto" ("Love, trust, equality, and respect").', related: ['BAMBAATAA', 'HAVING_FUN', 'HIP_HOP', 'PEACE', 'RESPECT', 'UNITY', 'ZULU_NATION'] } },
  { word: 'ORIGINALITY', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Originalidad', description: 'La originalidad es el valor de crear lo propio: en el Hip Hop, el estilo es personal, y copiar el de otro —"bitear" (to bite, copiar)— se considera una falta grave. La regla de la escena se resume en "no copies, crea": cada MC, cada b-boy, cada writer debe aportar algo propio. Es el complemento de la creatividad (ver `creativity`): se puede reciclar de todo, pero el resultado debe ser tuyo.', importance: 'La originalidad protege a la cultura de convertirse en copia de sí misma: obliga a cada participante, a cada generación y a cada territorio a aportar algo propio. Es el valor que mantiene viva la competencia creativa del cypher y que explica por qué el Hip Hop sigue evolucionando sin repetirse (ver `evolucion-cultural` y `creativity`).', funFact: 'En la tradición oral del Hip Hop, "biting" —copiar el estilo, las rimas o los movimientos de otro— se considera una de las faltas más graves del código: se documenta en letras como "don\'t bite no style", y en la escena se dice que el que bitea no tiene estilo propio.', related: ['CODIGO', 'CREATIVITY', 'CYPHER', 'FREESTYLE', 'JAM', 'STYLE', 'TRADICION'] } },
  { word: 'PEACE', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Peace', description: 'Peace (paz) es el primer valor del lema que la narrativa de la Universal Zulu Nation difundió como base del Hip Hop: "peace, love, unity and having fun" (paz, amor, unidad y diversión). La paz aparece en el Hip Hop como proyecto: transformar la violencia de las pandillas en competencia artística. También es un saludo: decir "peace" al entrar, saludar o despedirse es parte del código de la cultura.', importance: 'La paz es el valor fundacional de la narrativa Zulu: la idea de que la cultura puede reemplazar la violencia por creatividad. Ese relato marcó la identidad del Hip Hop en todo el mundo y sigue siendo la base de programas sociales y educativos de la cultura.', funFact: 'La "Hip Hop Declaration of Peace" fue presentada ante las Naciones Unidas el 16 de mayo de 2001 por KRS-One y el Temple of Hip Hop, firmada por más de 300 activistas, pioneros y delegados, entre ellos Afrika Bambaataa.', related: ['BAMBAATAA', 'BATTLE', 'BLOCK_PARTY', 'HAVING_FUN', 'HIP_HOP', 'LOVE', 'UNITY', 'ZULU_NATION'] } },
  { word: 'REALNESS', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Realness (Autenticidad)', description: 'La realness —ser real, autenticidad— es uno de los valores centrales del Hip Hop: la exigencia de que lo que se dice, se canta y se muestra sea coherente con lo que se es y con el lugar del que se viene. Es la idea detrás de la frase "keep it real": no traicionar el barrio, la historia ni el propio estilo. En la práctica, la realness se mide por la credibilidad: un MC que rapea la calle debe venir de la calle, y quien no la vive no puede pretender representarla (ver `street`, `cultura-de-barrio`, `street-culture`).', importance: 'La realness es el pegamento de la credibilidad en el Hip Hop: regula quién puede hablar y de qué, sostiene el respeto entre pares (ver `respect`) y diferencia a la cultura de un simple producto de entretenimiento. Al mismo tiempo, es un valor problemático: la exigencia de "ser real" puede convertirse en presión para performar el barrio o en herramienta de exclusión, y por eso mismo es objeto de debate interno permanente.', funFact: '"Keep it real" (mantenerse real) es la frase que condensa el valor de la realness en el Hip Hop, popularizada en los años 90: la exigencia de coherencia entre lo que se dice, lo que se vive y el lugar del que se viene.', related: ['CODIGO', 'CULTBARR', 'HIP_HOP', 'IDENTITY', 'ORIGINALITY', 'RESPECT', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'RESISTANCE', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Resistencia', description: 'La resistencia es la lectura del Hip Hop como voz de los marginados: una cultura nacida en los barrios empobrecidos de Nueva York que convirtió el relato de la vida en la calle en denuncia, orgullo y exigencia. No es solo música de protesta: es la idea de que quienes no tenían canales para hablar tomaron la palabra con el micrófono, el spray y el baile.', importance: 'La resistencia dio al Hip Hop su dimensión política y explica por qué el género se convirtió en plataforma de denuncia global: del relato del gueto de "The Message" a las protestas contemporáneas, el rap sigue siendo uno de los canales más visibles de las comunidades marginadas para contar su propia historia.', funFact: '"The Message" (1982) es la primera grabación de hip hop incorporada al Registro Nacional de Grabaciones de la Biblioteca del Congreso de EE. UU. (2002), un reconocimiento documentado de su valor histórico.', related: ['CONSCIOUSRAP', 'GANGSTA_RAP', 'HIP_HOP', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'RESPECT', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Respect', description: 'Respect (respeto) es uno de los valores centrales del código del Hip Hop: el respeto por la cultura, por los pares, por los predecesores y por quien está en el círculo. En el Hip Hop, el respeto no se hereda ni se compra: se gana demostrando habilidad, consistencia y autenticidad, especialmente en el cypher y en la batalla. Es el valor que hace que la competencia más dura termine con un apretón de manos.', importance: 'El respeto es lo que mantiene viva la competencia sana del Hip Hop: se puede batallar sin odio, porque el rival que demuestra estilo también merece respeto. Es la base de la ética de la cultura —junto al valor codificado en la entrada codigo de esta enciclopedia— y el motivo por el que el cypher sigue siendo la prueba real de cada artista.', funFact: 'RESPECT es uno de los valores que la Universal Zulu Nation publica en su sitio junto a KNOWLEDGE, WISDOM, UNDERSTANDING, FREEDOM, JUSTICE, EQUALITY, PEACE, UNITY y LOVE, entre otros.', related: ['BATTLE', 'CODIGO', 'CREW', 'CYPHER', 'FREESTYLE', 'HIP_HOP', 'ZULU_NATION'] } },
  { word: 'SELFEXPRES', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Autoexpresión', description: 'La autoexpresión es la voz individual dentro del Hip Hop: el vehículo personal con el que cada participante habla de sí mismo —sus historias, su barrio, su verdad—. Mientras la expresión (ver `expression`) es el fenómeno cultural colectivo, la autoexpresión es lo que cada uno aporta: el freestyle del MC, el estilo del b-boy, la firma del writer. En el Hip Hop, la cultura da el marco y el individuo da la voz.', importance: 'La autoexpresión es lo que mantiene viva a la cultura: si la expresión es el idioma, la autoexpresión es lo que cada uno dice con él. Es el valor que conecta al individuo con la comunidad (ver `community`) y con su propia identidad (ver `identity`): en el Hip Hop, decir "yo" es también decir "nosotros".', funFact: '"The Message" de Grandmaster Flash and the Furious Five (1982) es uno de los primeros temas de rap en llevar la vida del barrio a primera persona: las crónicas lo citan como el momento en que el rap dejó de ser solo fiesta y se volvió voz personal y social.', related: ['CYPHER', 'EXPRESSION', 'FLASH', 'FREESTYLE', 'IDENTITY', 'JAM', 'MC', 'STORYTELLING'] } },
  { word: 'STREETCULT', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Cultura de calle', description: 'La cultura de calle (street culture) es el conjunto de expresiones urbanas que nacen y viven en la calle: el arte callejero, la danza callejera, el skate, el streetball, la moda urbana y el propio Hip Hop. El Hip Hop es la cultura de calle más influyente del último medio siglo, pero no es toda la cultura de calle: convive con otras escenas con las que comparte espacios, códigos y estilo.', importance: 'Entender la cultura de calle permite ver que el Hip Hop no es un fenómeno aislado: es parte de un ecosistema urbano más amplio con el que comparte lenguaje, estética y espacios. También explica por qué la moda urbana (sneakers, streetwear) es hoy una industria global que nació en la calle, junto al rap, el graffiti y el breaking.', funFact: 'Está documentado que el sencillo "My Adidas" de Run-DMC (1986) impulsó el papel de Adidas en la cultura sneaker: la relación entre la música y la moda de calle quedó sellada como parte de la identidad del Hip Hop.', related: ['B_BOY', 'CULTBARR', 'HIP_HOP', 'TAG', 'UNDERGROUND'] } },
  { word: 'STREET', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Street (La calle)', description: 'La street —la calle— es el territorio simbólico y real del Hip Hop: el lugar donde nació la cultura y del que se alimenta su contenido. No es solo un espacio físico —las esquinas, los parques, las block parties del Bronx—, sino una noción de origen y pertenencia: el Hip Hop es cultura de la calle porque nació en los barrios populares, fue hecha por gente de esos barrios y cuenta la vida de esos barrios (ver `street-culture`, `cultura-de-barrio`).', importance: 'La calle es la identidad de origen del Hip Hop: explica su contenido (historias de barrio), su estética (ropa, lenguaje, gestos) y su sistema de valores (autenticidad, respeto, código; ver `codigo`, `respect`). Entender la calle como territorio simbólico permite entender por qué la cultura defiende tanto su origen popular y desconfía de quienes lo fingen.', funFact: 'El Hip Hop nació en la calle: en las block parties del Bronx de los años 70 (ver `block-party`). La calle funciona en la cultura como territorio real y como sello de autenticidad: de ahí vienen sus historias, su estética y su exigencia de "ser real" (ver `realness`).', related: ['BLOCK_PARTY', 'CODIGO', 'COMMUNITY', 'CULTBARR', 'CYPHER', 'HIP_HOP', 'JAM', 'REALNESS', 'STREETCULT'] } },
  { word: 'TRADICION', category: 'cultura', difficulty: 'medium', knowledge: { title: 'Tradición', description: 'La tradición es la memoria del Hip Hop: el conjunto de relatos, técnicas, valores y nombres que la cultura se transmite a sí misma de generación en generación, sobre todo de forma oral. Antes de los libros y los documentales, el Hip Hop se contó en cyphers, jams y crews: quién inventó qué, cómo se bailaba, qué significaba ser original.', importance: 'La tradición explica por qué el Hip Hop cuida su memoria: los pioneros se nombran, las historias se repiten y el conocimiento ("knowledge") se valora como parte de la cultura. Sin la tradición oral, el Hip Hop habría perdido su propio relato de origen; con ella, cada generación recibe la historia con sus versiones y la hace suya.', funFact: '*Yes Yes Y\'all* (2002) es una historia oral del primer decenio del Hip Hop construida con entrevistas directas a los protagonistas: un registro documental de la memoria oral de la cultura.', related: ['BAMBAATAA', 'CREW', 'CYPHER', 'HIP_HOP', 'JAM', 'ZULU_NATION'] } },
  { word: 'UNITY', category: 'cultura', difficulty: 'easy', knowledge: { title: 'Unity', description: 'Unity (unidad) es el segundo valor del lema que la narrativa de la Universal Zulu Nation difundió como base del Hip Hop: "peace, love, unity and having fun" (paz, amor, unidad y diversión). En el Hip Hop, la unidad significa la comunidad que se forma alrededor de la cultura: crews, barrios y disciplinas que comparten códigos y se reconocen entre sí. Es la idea de que la cultura une lo que la ciudad separa.', importance: 'La unidad es lo que hace del Hip Hop una cultura y no solo un conjunto de disciplinas: une a MCs, DJs, breakers y writers bajo códigos comunes, y conecta barrios, ciudades y países. La narrativa Zulu la presenta como la respuesta cultural a la fragmentación y la violencia.', funFact: '"Unity" (1984) es el título de la canción que Afrika Bambaataa grabó con James Brown, llevando el valor de la unidad de la narrativa Zulu directamente al nombre de un disco.', related: ['BAMBAATAA', 'COMMUNITY', 'CREW', 'HAVING_FUN', 'HIP_HOP', 'LOVE', 'PEACE', 'ZULU_NATION'] } },
  { word: 'AFRICA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop africano', description: 'El Hip Hop africano es el conjunto de escenas que se desarrollaron en el continente desde los años 80, cuando el rap llegó a África a través de cassettes, cintas de vídeo y la diáspora, con Nueva York y París como puertas de entrada. Su rasgo distintivo es la adaptación radical a las lenguas y tradiciones locales: se rapea en wolof, suajili, afrikáans, igbo, xhosa y decenas de otras lenguas, y muchos estudiosos señalan que el rap encontró en África una tradición oral milenaria —los griots— que funcionaba como precedente. Sudáfrica tiene entrada propia (ver `sudafrica`).', importance: 'El Hip Hop africano demostró la capacidad del género para hablarse en cualquier lengua y arraigarse en tradiciones orales milenarias: la figura del griot como precedente del MC y el rap en lenguas maternas son sus aportes distintivos. Además, el continente produjo derivados originales —el kwaito sudafricano, el bongo flava tanzano, el hiplife ghanés— que son escenas hermanas del rap más que copias locales (ver `estilos-regionales` e `identity`).', funFact: 'Según la cronología de Eric Charry, el despegue comercial del rap africano se produjo entre 1994 y 1995, cuando las escenas dejaron de imitar el acento estadounidense y empezaron a rapear en sus lenguas maternas con mensajes propios.', related: ['CONSCIOUSRAP', 'ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'RESISTANCE', 'SUDAFRICA', 'UNDERGROUND'] } },
  { word: 'ARGENTINA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Argentina', description: 'La escena argentina es una de las más influyentes del hip hop en español: del rap underground en español rioplatense de los años 80-90 pasó al freestyle masivo de las plazas y, desde 2017, al trap que domina las listas de América Latina y España. Su particularidad es el papel central de las batallas de freestyle, que funcionaron como escuela y trampolín de toda una generación de artistas.', importance: 'Argentina aportó al hip hop en español el formato de las batallas de freestyle como fenómeno de masas y, con el trap, una de las industrias más potentes de América Latina. El rap argentino demostró que el español rioplatense podía sostener una escena propia, del underground a las listas globales, y la diferencia entre su rap de los 90 y su trap actual muestra cómo cada generación rehace el género a su manera.', funFact: 'Entre 2012 y 2017, El Quinto Escalón —competencia de freestyle gratuita en la escalinata del Parque Rivadavia de Buenos Aires— se convirtió en la competencia de plaza más grande del mundo hispanohablante y en la cuna de artistas como Duki, Wos, Trueno y Paulo Londra.', related: ['BATTLE_RAP', 'ESTILOSREG', 'FREESTYLE', 'HIP_HOP', 'LATAM', 'TRAP', 'UNDERGROUND'] } },
  { word: 'ASIA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Asia', description: 'El hip hop asiático es el conjunto de escenas de hip hop del continente: K-rap (Corea del Sur), J-rap (Japón), C-rap (China) y las escenas de Filipinas, Taiwán, Malasia, India y otros países. Es un territorio donde el Hip Hop llegó muy temprano —la primera escena documentada es de los primeros años 80— y se adaptó a idiomas y contextos muy distintos entre sí. Hoy Asia combina escenas underground sólidas con las industrias pop más grandes del mundo.', importance: 'Asia es el continente más poblado del planeta y su adopción del Hip Hop demostró la capacidad global de la cultura: desde la adopción temprana del breaking hasta adaptaciones idiomáticas completas. Las escenas asiáticas aportaron formas propias —el respeto por la vieja escuela del hip hop japonés, el rap consciente filipino, el salto del C-rap underground al mainstream televisivo— y hoy son parte central de la industria mundial del género.', funFact: 'Filipinas tuvo la primera escena de hip hop de Asia: en 1980 se publicaron los primeros discos de rap del continente (*Na Onseng Delight* de Dyords Javier e *Ispraken Delight* de Vincent Dafalong), años antes de que aparecieran el rap japonés o el coreano.', related: ['B_BOY', 'ESTILOSREG', 'EXPANSION80S', 'HIP_HOP', 'JAPON', 'OCEANIA', 'UNDERGROUND'] } },
  { word: 'BRASIL', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Brasil', description: 'La escena brasileña es la más grande de América del Sur y una de las más influyentes del rap en portugués: nació en los bailes black de São Paulo de los años 70, se consolidó con el rap consciente de los 90 encabezado por Racionais MC\'s y hoy convive con un trap brasileño que domina las listas comerciales. Su sello es la fusión con la música brasileña —samba, forró, baião— y su función como voz de las periferias negras.', importance: 'Brasil aportó al Hip Hop global el rap en portugués más influyente de América Latina: un rap consciente de conciencia racial y de clase (Racionais MC\'s es referencia en todo el continente) y una capacidad de fusión con la música brasileña que no tiene equivalente. Su estructura de posse (colectivos organizados tipo MH2O) y su paso del underground al trap comercial muestran la adaptación local de la cultura.', funFact: 'Racionais MC\'s publicó *Sobrevivendo no Inferno* (1997) por su propio sello, Cosa Nostra, y el álbum fue certificado oro en enero de 1998: un disco de rap independiente de São Paulo convertido en referencia del rap consciente en toda América Latina.', related: ['CONSCIOUSRAP', 'ESTILOSREG', 'HIP_HOP', 'LATAM', 'RESISTANCE', 'STREETCULT'] } },
  { word: 'CANADA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Escena canadiense', description: 'La escena canadiense es una de las más antiguas del Hip Hop fuera de EE. UU. y, desde los 2010, una de las más influyentes del mundo: Toronto, Montreal y Vancouver construyeron escenas propias — con fuerte presencia de la diáspora caribeña y de comunidades francófonas, indígenas y punjabíes — que pasaron del underground a la cima de las listas globales con Drake a la cabeza.', importance: 'Canadá demostró que una escena sin industria propia podía construir identidad local — el rap francés de Quebec, el sonido caribeño de Toronto, las escenas indígena y punjabí — y, en los 2010, se convirtió en la primera escena fuera de EE. UU. en dominar las listas globales del rap, con Toronto como nuevo centro creativo de referencia mundial.', funFact: 'El single canadiense más vendido de los 90, "Informer" de Snow (1993, número 1 en EE. UU.), suele etiquetarse como rap pero es dancehall: un ejemplo perfecto del peso de la influencia caribeña en la escena canadiense (ver `caribe`).', related: ['CARIBE', 'CREW', 'DJ', 'EE_UU', 'ESTILOSREG', 'EXPANSION80S', 'HIP_HOP', 'MC', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'CARIBE', category: 'historia', difficulty: 'medium', knowledge: { title: 'Escena caribeña', description: 'La escena caribeña es el conjunto de expresiones de rap y de las músicas que lo precedieron y acompañaron en las islas: el dancehall y el toasting de Jamaica, el soca y el rapso de Trinidad y Tobago, el hip hop cubano y el rap en español de Puerto Rico. El Caribe importa doblemente: es la región de donde salió la tradición de los sound systems que Kool Herc llevó al Bronx (ver `dj-kool-herc`), y es el laboratorio de ritmos — dancehall, riddims — que el rap mundial adoptó y sigue sampleando.', importance: 'El Caribe aportó al Hip Hop su prehistoria — el toasting y los sound systems que Kool Herc llevó al Bronx (ver `dj-kool-herc`) —, el dancehall y su cultura de riddims, que el rap mundial sampleó sin cesar y de la que derivó el reggaetón, y escenas propias (rapso, hip hop cubano, rap en español) que muestran cómo la cultura se adapta a cada isla. Es la región donde el rap no llegó "de fuera": su tradición oral de palabras sobre ritmo es anterior al propio hip hop.', funFact: '"Sleng Teng" de Wayne Smith (1985), el primer riddim digital del reggae — grabado con un teclado casero y usado después en más de 200 canciones — marcó el giro digital del dancehall; ese linaje rítmico, con el "Dem Bow" (1990), es la semilla del reggaetón.', related: ['CYPHER', 'DJ', 'DJ_KOOL_HERC', 'ESTILOSREG', 'HIP_HOP', 'JAM', 'LATAM', 'MC', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'EE_UU', category: 'historia', difficulty: 'medium', knowledge: { title: 'Escena de EE. UU.', description: 'La escena estadounidense es el conjunto de escenas locales que convirtieron el rap, nacido en el Bronx, en un fenómeno nacional e industrial: la radio, la televisión, los sellos discográficos y las listas de ventas expandieron el Hip Hop por todo el país y definieron el modelo que el resto del mundo copiaría. Esta entrada documenta esa expansión interna y el rol de la industria; el nacimiento del movimiento se documenta en `expansion-70s` y `expansion-80s`, y los sonidos de cada región en `estilos-regionales`.', importance: 'EE. UU. aportó al Hip Hop global la infraestructura que lo convirtió en industria: el modelo de sello, la radio especializada, el video musical y las listas de ventas que el resto del mundo adoptó. Como país de origen, su mercado siguió siendo la referencia (y el más grande) del rap mundial, y sus escenas regionales definieron los sonidos que las escenas nacionales de todo el planeta adaptaron a su lengua y su contexto.', funFact: 'En 1986 el rap alcanzó por primera vez la cima del Billboard 200 con "Licensed to Ill" de Beastie Boys — el segundo álbum de rap en lograr el platino, justo después de "Raising Hell" de Run-DMC, el primero: en menos de una década el rap pasó de las fiestas del Bronx al tope de las listas de EE. UU.', related: ['CANADA', 'CREW', 'CULTBARR', 'DJ', 'ESTILOSREG', 'EXPANSION80S', 'GOLDEN_ERA', 'HIP_HOP', 'JAM', 'MC', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'EUROPA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Europa', description: 'El Hip Hop europeo es el conjunto de escenas que surgieron en el continente a partir de comienzos de los 80, cuando el rap, el breaking, el graffiti y el DJing cruzaron el Atlántico a través de los discos, el cine y las giras de los pioneros neoyorquinos. Cada país lo adaptó a su lengua y a su música hasta formar un mapa propio: Francia es el segundo mercado mundial de rap, el Reino Unido desarrolló el grime como sonido propio, y Alemania, España, Italia y los Países Bajos construyeron escenas con identidad nacional. Esta entrada es el panorama continental; las escenas de Francia y el Reino Unido tienen entradas propias (ver `francia` y `reino-unido`).', importance: 'Europa demostró que el Hip Hop podía hablarse en cualquier lengua: el rap en francés, inglés, alemán, italiano y español enriqueció el género global con nuevos sonidos y nuevas voces. El continente alberga la segunda escena más grande del mundo (Francia), creó un género propio (el grime) y generó un circuito de festivales, sellos y batallas que hoy es parte central de la cultura global (ver `hip-hop` y `estilos-regionales`).', funFact: 'El 14 de enero de 1984, la cadena francesa TF1 estrenó *H.I.P. H.O.P.*, presentada por Sidney: según la Wikipedia en francés fue la primera emisión de televisión íntegramente dedicada al Hip Hop del mundo, cuatro años antes de *Yo! MTV Raps* en EE. UU. (1988).', related: ['ESTILOSREG', 'EXPANSION80S', 'FRANCIA', 'HIP_HOP', 'RAPDELIGHT', 'REINO_UNIDO', 'ROCKSTEADY', 'STREETCULT'] } },
  { word: 'FRANCIA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop francés', description: 'El Hip Hop francés (rap français) es la escena de rap más grande de Europa y la segunda del mundo después de la estadounidense, según fuentes de prensa y de Wikipedia. Nació a comienzos de los 80 a partir de la gira del New York City Rap Tour, la radio y la televisión, y en los 90 produjo un rap consciente de alcance masivo con grupos como IAM, Suprême NTM y MC Solaar. Es el ejemplo más citado de rap en una lengua distinta del inglés que alcanzó escala global.', importance: 'El rap francés demostró que el Hip Hop podía ser el género central de un mercado nacional no anglófono: su rap consciente de los 90 (IAM, NTM, MC Solaar) marcó a generaciones y su industria es hoy la segunda del mundo. También funcionó como puente con África —MC Solaar nació en Dakar y los grupos franceses de origen africano mantuvieron el vínculo con el continente— y como espacio de expresión de la identidad de los hijos de la inmigración (ver `underground`, `estilos-regionales` e `identity`).', funFact: 'Francia es el segundo mercado mundial de rap después de EE. UU. (afirmación citada por Wikipedia, France 24 y otras fuentes), y MC Solaar fue el primer artista de rap francés en alcanzar el platino con *Qui sème le vent récolte le tempo* (1991).', related: ['CONSCIOUSRAP', 'ESTILOSREG', 'EUROPA', 'HIP_HOP', 'IDENTITY', 'ROCKSTEADY', 'UNDERGROUND'] } },
  { word: 'JAPON', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Japón', description: 'La escena japonesa es la primera de Asia en adoptar el Hip Hop como cultura completa: rap, DJing, breaking y graffiti. Nació a mediados de los 80 de la mano de los b-boys, se consolidó con el rap de los 90 y hoy es reconocida mundialmente por su breaking de élite y por el respeto que mantiene hacia el hip hop de la vieja escuela. Es una de las escenas no estadounidenses más documentadas del género.', importance: 'Japón demostró que el Hip Hop podía arraigarse fuera de Estados Unidos manteniendo el respeto por sus orígenes: la escena japonesa fue la puerta de entrada de la cultura al resto de Asia y una referencia mundial tanto en rap como en breaking. Su tensión interna entre underground y pop —documentada desde 1996— anticipó un debate que después se repitió en todo el mundo.', funFact: 'En 1995, *Da.Yo.Ne* de East End X Yuri (doble platino, más de 800.000 copias vendidas) se convirtió en la primera canción de hip hop en el NHK Kōhaku Uta Gassen, la gala anual más vista de la televisión japonesa.', related: ['ASIA', 'B_BOY', 'ESTILOSREG', 'EXPANSION80S', 'HIP_HOP', 'UNDERGROUND'] } },
  { word: 'LATAM', category: 'historia', difficulty: 'medium', knowledge: { title: 'Escena latinoamericana', description: 'La escena latinoamericana es el conjunto de escenas nacionales de rap en español y portugués del continente: de México al Cono Sur, del Caribe hispano a Brasil, el Hip Hop llegó en los 80 por el cine y los cassettes — muchas veces bajo dictaduras y censura — y se adaptó a cada lengua, acento y música local. Esta entrada es el panorama continental: las escenas nacionales se documentan en sus propias entradas (ver `mexico`, `argentina`, `brasil` y `caribe`).', importance: 'América Latina aportó al Hip Hop global la demostración de que el rap es un lenguaje adaptable: lo recibió bajo dictaduras, lo difundió en cassettes piratas, lo mezcló con la cumbia, el dancehall y el funk, y terminó dominando las listas mundiales con el rap y el trap en español. Junto con EE. UU., es la región donde el rap en español y sus derivados construyeron la industria más grande del género fuera del mundo angloparlante (ver `evolucion-cultural`).', funFact: 'En plena dictadura de Pinochet (1973-1990), el hip hop ya circulaba en Chile: un estudio académico documenta la recepción del hip hop en el país entre 1984 y 1987, cuando el breakdance se convirtió en una vía de expresión de la juventud santiaguina — el rap llegó al Cono Sur antes que la democracia.', related: ['ARGENTINA', 'BRASIL', 'CARIBE', 'CULTBARR', 'ESTILOSREG', 'EVOLUCION', 'HIP_HOP', 'IDENTITY', 'MEXICO', 'RESISTANCE', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'MEDIOORIENTE', category: 'historia', difficulty: 'hard', knowledge: { title: 'Hip Hop de Medio Oriente', description: 'El Hip Hop de Medio Oriente reúne las escenas de rap en árabe, persa, turco y hebreo que surgieron desde los años 90 en la región y en su diáspora. Su rasgo distintivo es la censura: en varios países el rap se desarrolló casi por completo en el underground, y numerosos artistas grabaron desde el exilio. La escena es políticamente diversa y está atravesada por los conflictos de la región, que esta entrada documenta solo en su efecto sobre el rap, sin tomar partido.', importance: 'El Hip Hop de Medio Oriente demostró que el rap puede funcionar como voz underground en los contextos más restrictivos: la censura no eliminó la escena, sino que la empujó al subterráneo y al exilio, y el rap en árabe, persa, turco y hebreo amplió el mapa multilingüe del género. También mostró el papel de la diáspora como motor creativo —del rap turco-alemán de los 90 al exilio iraní— y la capacidad del MC para narrar conflictos complejos desde todas las posiciones (ver `estilos-regionales` e `identity`).', funFact: 'Según el USIP, el rap iraní se desarrolló casi por completo en el underground por la censura estatal, y artistas como Shahin Najafi siguieron grabando desde el exilio en Alemania después de recibir amenazas de muerte en 2012, documentadas por la BBC.', related: ['ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'RESISTANCE', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'MEXICO', category: 'historia', difficulty: 'medium', knowledge: { title: 'Escena mexicana', description: 'La escena mexicana es una de las más antiguas y grandes del rap en español: de los b-boys de los 80 al mainstream de Control Machete (1996), del rap "malandro" de los 2000 al freestyle mundial con Aczino y a la escena actual de Gera MX y Santa Fe Klan. México además documenta la primera grabación de rap en español conocida, de 1979. Esta entrada describe la escena nacional; el panorama continental está en `latinoamerica`.', importance: 'México aportó al rap en español la primera grabación conocida (1979, aunque paródica), una de las escenas más grandes del continente (ver `latinoamerica`), la fusión cumbia rap y la cima mundial del freestyle con Aczino. Su historia muestra el patrón latinoamericano: primero el breaking, luego los cassettes y la MTV, y la adaptación local de un género que cruzó la frontera en ambos sentidos con el rap chicano (ver `ee-uu`).', funFact: 'La primera grabación de rap en México es una parodia: "El Cotorreo" (1979), del comediante Memo Ríos ("MC Aplausos"), rapeada sobre el instrumental de "Rapper\'s Delight" — 17 años antes de que Control Machete llevara el rap mexicano al mainstream.', related: ['B_BOY', 'CONSCIOUSRAP', 'CREW', 'CULTBARR', 'DJ', 'EE_UU', 'ESTILOSREG', 'HIP_HOP', 'LATAM', 'MC', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'OCEANIA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop en Oceanía', description: 'El hip hop de Oceanía reúne las escenas de Australia y Nueva Zelanda. Su rasgo distintivo es la presencia indígena y del Pacífico: el rap neozelandés tiene una fuerte presencia maorí y pasifika, y el australiano cuenta con un protagonismo aborigen documentado desde los inicios de la escena. Es un territorio donde el Hip Hop se convirtió en voz de identidad y resistencia, y donde la industria independiente fue la regla.', importance: 'Oceanía demostró que el Hip Hop podía ser a la vez adopción global y voz local: en Nueva Zelanda, el rap se convirtió en un canal de la identidad maorí y pasifika (con la fusión propia llamada Urban Pasifika), y en Australia, en expresión de las comunidades indígenas y migrantes. Su modelo de sellos independientes y su proyección global (*How Bizarre*, Savage, The Kid Laroi) la convierten en referencia para escenas periféricas del género.', funFact: '*How Bizarre* de OMC (1995) es la canción más vendida grabada en Nueva Zelanda: la fusión del sonido urbano del Pacífico con el pop llevó el hip hop de Oceanía a las listas de todo el mundo.', related: ['ASIA', 'ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'RESISTANCE', 'UNDERGROUND'] } },
  { word: 'REINO_UNIDO', category: 'historia', difficulty: 'medium', knowledge: { title: 'Rap británico y grime', description: 'El rap británico es el Hip Hop hecho en el Reino Unido desde comienzos de los 80, con una influencia caribeña fundacional (dub, toasting y cultura de soundsystem) y un largo periodo underground. Su gran aporte al Hip Hop global es el grime: un género nacido en Londres a comienzos de los 2000 desde el UK garage, el jungle y el dancehall, con MCs sobre beats electrónicos rápidos, que se considera generalmente un género hermano del hip hop más que una variante del rap. Del grime derivó el drill británico (ver `drill`).', importance: 'El Reino Unido aportó al Hip Hop global algo que ninguna otra escena había logrado: un género propio con raíces electrónicas y caribeñas, el grime, que demostró la capacidad de la cultura del MC para cruzar géneros (garage, jungle, dancehall). Su escena de rap, influida por el toasting y los soundsystems, fue pionera en rapear con acento y slang locales, y del grime derivó el drill británico que hoy se replica en todo el mundo (ver `estilos-regionales` y `hip-hop`).', funFact: 'El grime nació en Londres a comienzos de los 2000 desde el UK garage, el jungle y el dancehall, se difundió por la radio pirata, y Dizzee Rascal ganó el Mercury Prize 2003 con *Boy in da Corner*; la primera grabación del género es discutida entre varias candidatas de 2000–2002.', related: ['DRILL', 'ESTILOSREG', 'EUROPA', 'HIP_HOP', 'MC', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'SUDAFRICA', category: 'historia', difficulty: 'medium', knowledge: { title: 'Hip Hop sudafricano', description: 'El Hip Hop sudafricano nació bajo el apartheid en Ciudad del Cabo: el rap, el breaking y el graffiti llegaron al país en los años 80 y se convirtieron en voz de la juventud de los Cape Flats y los townships segregados. Pioneros como Black Noise y Prophets of da City construyeron una de las escenas más antiguas del continente, y tras la caída del apartheid surgió el kwaito, un género masivo derivado del house cuya relación con el hip hop es discutida. Es la escena de referencia del rap africano de habla inglesa y afrikáans (ver `africa`).', importance: 'Sudáfrica aportó al Hip Hop global el ejemplo más claro de rap como resistencia bajo un régimen de segregación: sus pioneros rapearon en inglés, afrikáans y afrikaaps bajo el apartheid y grabaron algunos de los primeros álbumes de rap del continente. El kwaito, además, demostró cómo la cultura post-apartheid pudo crear un género propio de base house con influencia hip hop —con una relación que los estudiosos discuten—, y el país mantiene hoy una de las industrias de rap más grandes de África (ver `africa` y `estilos-regionales`).', funFact: 'Según la cronología de Eric Charry, *Our World* de Prophets of da City (1990) fue el primer álbum de rap sudafricano y uno de los primeros LPs de rap de África, y el mismo grupo grabó "Dala Flet", considerado el primer tema de rap en afrikáans.', related: ['AFRICA', 'CONSCIOUSRAP', 'ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'RESISTANCE', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'ANTECEDENTES', category: 'chile', difficulty: 'medium', knowledge: { title: 'Antecedentes del Hip Hop en Chile', description: 'Antes del rap existió en Chile una cadena de música de denuncia, resistencia y circulación clandestina que preparó el terreno: la nueva canción chilena (años 60-70), el canto nuevo bajo la dictadura, los cassettes como tecnología de copia y el exilio como puente cultural. Esta entrada documenta ese contexto previo: sin él no se entiende por qué el hip hop chileno nació en las poblaciones con vocación de testimonio político (ver `resistance`, `cultura-de-barrio`).', importance: 'El hip hop chileno no partió de cero: heredó una cultura de resistencia con códigos ya probados —la denuncia en verso, los circuitos de copia, los espacios comunitarios— y un público entrenado en escuchar música política bajo censura. Esa herencia explica el carácter testimonial y poblacional del rap chileno desde sus primeras grabaciones (ver `latinoamerica`).', funFact: 'El sello Alerce, fundado en 1975 por Ricardo García para rescatar la nueva canción chilena censurada, publicó en los años 90 los primeros discos de rap chileno: «Pozzeídos por la ilusión» de La Pozze Latina y «Reyes de la jungla» de Panteras Negras (ambos de 1993). Un solo sello conecta el canto censurado de la dictadura con la primera ola del rap.', related: ['CHILE80S', 'CULTBARR', 'ESTILOSREG', 'HIP_HOP', 'IDENTITY', 'LATAM', 'LLEGADAHH', 'RESISTANCE', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'BATALLA', category: 'chile', difficulty: 'easy', knowledge: { title: 'Batallas chilenas', description: 'Las batallas chilenas son la escena de freestyle competitivo de Chile: las competencias donde dos MCs improvisan rimas y se enfrentan con punchlines ante un jurado, desde las batallas de plaza hasta las ligas profesionales. Su referente histórico es la Red Bull Batalla Chile (desde 2006) y, desde 2019, la FMS Chile (ver `fms-chile`), pero la escena incluye decenas de competencias locales, plazas y eventos que formaron a varias generaciones de freestylers (ver `freestyle`, `battle-rap`).', importance: 'Las batallas chilenas son la puerta de entrada del freestyle en Chile y la base sobre la que se construyó la FMS Chile: formaron a los MCs que hoy compiten a nivel mundial, generaron una audiencia masiva por YouTube y posicionaron a Chile como uno de los países protagonistas del freestyle hispanoamericano, junto a México, Argentina, España y Perú.', funFact: 'La Red Bull Batalla Chile se disputa desde 2006 y clasifica a su campeón a la Red Bull Batalla Internacional; en 2026, El Menor ganó la Final Internacional disputada en el Movistar Arena de Santiago, el mayor logro internacional de la escena chilena.', related: ['BATTLE_RAP', 'DISS', 'ESCENACHILE', 'FMS_CHILE', 'FREESTYLE', 'MCINGCHILE', 'PUNCHLINE', 'SANTIAGO'] } },
  { word: 'BBOYCHILE', category: 'chile', difficulty: 'medium', knowledge: { title: 'Breaking en Chile', description: 'El breaking fue el primer elemento del hip hop en popularizarse en Chile: a comienzos de los años 80, antes que el rap, los bailarines llenaron plazas y pasajes del centro de Santiago inspirados por el cine estadounidense. Nacido en plena dictadura como una práctica juvenil de la calle, el breaking chileno sobrevivió a la represión, declinó frente al auge del rap y resurgió desde los 2000 en competencias que hoy tienen proyección internacional.', importance: 'El breaking fue la puerta de entrada de toda la cultura hip hop a Chile: del baile pasaron al rap, al graffiti y al DJing los primeros practicantes, y sus espacios de reunión (Bombero Ossa, San Agustín) funcionaron como escuela de la cultura. Hoy el breaking chileno mantiene una comunidad activa de batallas y representantes con logros internacionales verificados.', funFact: 'El breakdance fue el primer elemento del hip hop en popularizarse en Chile (1983-84), antes que el rap, y su primer punto de reunión documentado fue el Paseo Bombero Ossa, en el centro de Santiago, hacia 1986.', related: ['BATTLE', 'BOMBEROOSSA', 'B_BOY', 'CHILE80S', 'CULTBARR', 'CYPHER', 'ECOSISTEMAHH', 'HIP_HOP', 'JAM', 'LLEGADAHH', 'SANTIAGO', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'CHILENO', category: 'chile', difficulty: 'easy', knowledge: { title: 'Hip Hop chileno', description: 'El Hip Hop chileno es la escena de rap, breaking, DJing y writing desarrollada en Chile desde los años 80 hasta hoy. Nació en las poblaciones de Santiago bajo dictadura, se consolidó en los 90 con los primeros discos y el primer éxito comercial, y hoy es una escena madura con expresiones en todo el país, incluidas las ligas de freestyle más importantes del mundo hispano (ver `fms-chile`, `batalla-chilena`).', importance: 'El Hip Hop chileno es una de las escenas más reconocidas de América Latina: por su historia de resistencia ligada a la dictadura y la transición, por su música (de Panteras Negras a Ana Tijoux, pasando por Tiro de Gracia y Makiza), y por su presente en el freestyle competitivo, donde campeones chilenos compiten al más alto nivel (ver `fms-chile`, `batalla-chilena`).', funFact: 'El primer concierto de rap de Chile se realizó el 16 de junio de 1990 en el Gimnasio Manuel Plaza (Ñuñoa), apenas tres meses después del retorno a la democracia, con CMC Rappers, Latin Posse y Panteras Negras (ver `hip-hop-chileno-90s`).', related: ['ANTECEDENTES', 'BBOYCHILE', 'CHILE2000S', 'CHILE2010S', 'CHILE80S', 'CHILE90S', 'ECOSISTEMAHH', 'ESCENACHILE', 'LLEGADAHH', 'MCINGCHILE', 'SANTIAGO', 'WRITINGCHILE'] } },
  { word: 'CONCE', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop en Concepción y Talcahuano', description: 'La escena penquista — Concepción y su puerto vecino Talcahuano, en la Región del Biobío — es una de las más activas del hip hop chileno fuera de Santiago: tiene grupos históricos documentados, estudios académicos propios y una vida de batallas de freestyle que continúa hasta hoy. Esta entrada documenta el hip hop de la zona, su historia verificable y su rol de nodo regional (ver `otras-ciudades-hip-hop-chile`).', importance: 'La escena penquista demuestra la vitalidad del hip hop fuera de la capital: un polo regional con grupos históricos (Tono Abstracto), documentación académica propia (Cire, 2015) y una continuidad de batallas, producción y autogestión que la ubica entre las escenas más activas del país fuera de Santiago (ver `estilos-regionales`).', funFact: 'Concepción es, según el estudio de Cire (2015), "el mayor nodo logístico de relaciones entre distintas comunas" del hip hop de la zona: no su cuna, pero sí el centro que articula la escena regional del Biobío.', related: ['BATTLE_RAP', 'CIUDADESHH', 'CONSCIOUSRAP', 'CULTBARR', 'ECOSISTEMAHH', 'ESCENACHILE', 'FREESTYLE', 'HIP_HOP', 'LATAM', 'SANTIAGO', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'ECOSISTEMAHH', category: 'chile', difficulty: 'medium', knowledge: { title: 'Ecosistema del hip hop chileno', description: 'El ecosistema del hip hop chileno es la red de medios, eventos, sellos, organizaciones y espacios que sostuvo la cultura durante décadas sin industria y que hoy la proyecta a nivel global. Nació con encuentros autogestionados en plazas y pasajes del centro de Santiago, se articuló en festivales, revistas, radios y torneos, y en 2026 convirtió a Santiago en sede de la final internacional de Red Bull Batalla de los Gallos.', importance: 'El ecosistema chileno demuestra cómo una cultura puede sostenerse sin industria: encuentros, revistas, radios, sellos independientes y espacios públicos crearon las condiciones para que el rap, el breaking y el graffiti chilenos sobrevivieran a la dictadura y al centralismo, y para que hoy el país sea anfitrión de eventos globales de la cultura.', funFact: 'Chile tiene competencia nacional de freestyle propia desde 2006 (Red Bull Batalla de los Gallos) y en 2026 fue sede de la final internacional del torneo, disputada en el Movistar Arena de Santiago, donde el local El Menor se coronó campeón mundial.', related: ['BBOYCHILE', 'CIUDADESHH', 'COMMUNITY', 'CULTBARR', 'CYPHER', 'ESCENACHILE', 'EVOLUCION', 'HIP_HOP', 'JAM', 'MCINGCHILE', 'SANTIAGO', 'STREETCULT', 'UNDERGROUND', 'WRITINGCHILE'] } },
  { word: 'ESCENACHILE', category: 'chile', difficulty: 'medium', knowledge: { title: 'Escena contemporánea del hip hop chileno', description: 'La escena actual del hip hop chileno convive en dos velocidades: una industria dominada por el trap y la música urbana que llena listas y festivales, y una contracorriente de rap conciente y underground que sostiene la tradición territorial de las poblaciones. En el medio, el freestyle vive su momento más alto: Chile albergó la final internacional de Red Bull Batalla de los Gallos 2026 y un chileno, El Menor, se coronó campeón mundial. Esta entrada documenta el estado actual de la escena, continuando la historia de `hip-hop-chileno-2010s`.', importance: 'La escena contemporánea muestra la madurez del hip hop chileno: ya no es solo underground ni solo industria, sino ambas cosas a la vez — un país donde la calle produce campeones mundiales de freestyle, el trap domina las listas latinas y el rap conciente sostiene la memoria territorial, todo en el mismo ecosistema (ver `estilos-regionales`, `evolucion-cultural`).', funFact: 'El 11 de abril de 2026, la final internacional de Red Bull Batalla de los Gallos se disputó en Chile y el chileno El Menor se coronó campeón mundial: el primer título mundial de freestyle para el país, 20 años después de que Chile estrenara su final nacional (2006).', related: ['BATTLE_RAP', 'CHILE2000S', 'CHILE2010S', 'CIUDADESHH', 'CONCE', 'CONSCIOUSRAP', 'ECOSISTEMAHH', 'ESTILOSREG', 'EVOLUCION', 'FREESTYLE', 'HIP_HOP', 'LATAM', 'SANTIAGO', 'TRAP', 'UNDERGROUND', 'VALPARAISO'] } },
  { word: 'FMS_CHILE', category: 'chile', difficulty: 'hard', knowledge: { title: 'FMS Chile', description: 'La FMS Chile (Freestyle Master Series Chile) es la liga chilena de freestyle rap, parte de la Freestyle Master Series organizada por The Urban Roosters: una liga profesional donde los mejores freestylers de Chile se enfrentan todos contra todos a lo largo de una temporada, con puntuación acumulada, campeón anual y descensos. Comenzó en 2019 y es una de las ligas FMS más competitivas de habla hispana (ver `freestyle`, `battle-rap`).', importance: 'La FMS Chile profesionalizó el freestyle chileno: convirtió las batallas de plaza en una liga con temporadas, puntuación, descensos, transmisión y audiencia masiva. Es la plataforma que consolidó a los freestylers chilenos de elite (Teorema, Nitro, El Menor, Acertijo, Basek, entre otros) y que, junto a la Red Bull Batalla, posicionó a Chile entre los países protagonistas del freestyle mundial (ver `escena-contemporanea-chile`, `hip-hop-chileno-2010s`).', funFact: 'La FMS Chile comenzó en 2019 con Teorema como primer campeón; hasta la temporada 2025/26 solo ha tenido tres campeones: Teorema (2019), Nitro (2020/21 y 2022/23) y El Menor (2023/24, 2024/25 y 2025/26), este último tricampeón consecutivo.', related: ['BATALLA', 'BATTLE_RAP', 'CHILE2010S', 'ESCENACHILE', 'FLOW', 'FREESTYLE', 'MCINGCHILE', 'PUNCHLINE', 'SANTIAGO'] } },
  { word: 'CHILE2000S', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop chileno de los años 2000', description: 'Tras el boom comercial de fines de los 90, el hip hop chileno de los 2000 volvió a sus raíces: underground, rap conciente y encuentros callejeros. En esta década maduraron la «nueva escuela» nacida hacia 2000-2005, el rap político de Portavoz y Salvaje Decibel, la carrera solista de Ana Tijoux, los primeros pasos de Movimiento Original y las batallas de freestyle que empezaron a organizarse de forma regular (ver `underground`, `conscious-rap`, `freestyle`).', importance: 'Los 2000 fueron la década en que el hip hop chileno redefinió su identidad: sin la vitrina de la industria, la escena volvió a la calle y al rap conciente, formó a la generación que explotaría en los 2010 (nueva escuela, freestyle, trap), y consolidó a sus grandes figuras del rap político (Portavoz, Ana Tijoux). También dejó instalado el circuito de batallas que haría de Chile un país protagonista del freestyle en español (ver `hip-hop-chileno-2010s`).', funFact: 'El «Monumento» de Maipú —punto de encuentro dominical liderado por MC Base, de Distorsión Lírica— fue la escuela de la nueva escuela chilena: cada domingo, raperos de toda Santiago se reunían para freestyle, trueque de música y graffiti, en el circuito del que salieron los artistas que protagonizarían la explosión del hip hop chileno de los 2010.', related: ['BATTLE_RAP', 'CHILE2010S', 'CHILE90S', 'CONSCIOUSRAP', 'DJ', 'FREESTYLE', 'IDENTITY', 'MC', 'MCINGCHILE', 'RESISTANCE', 'SANTIAGO', 'UNDERGROUND'] } },
  { word: 'CHILE2010S', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop chileno en los años 2010', description: 'La década de 2010 fue la de la explosión del hip hop chileno: el freestyle se profesionalizó con competencias nacionales y ligas, el rap femenino alcanzó proyección internacional con Ana Tijoux y, hacia el final de la década, el trap nacido en la calle se convirtió en la música urbana dominante del país. Es el puente entre el underground conciente de los 2000 (ver `hip-hop-chileno-2000s`) y la escena contemporánea (ver `escena-contemporanea-chile`).', importance: 'La década de 2010 demostró la vitalidad de una escena que pasó del underground a la arena global sin perder su anclaje territorial: el freestyle chileno compitió de igual a igual en el circuito hispanoamericano (dos finales internacionales con subcampeones chilenos y una final disputada en Chile), el rap femenino logró hitos internacionales con Ana Tijoux y el trap convirtió la experiencia de las poblaciones en industria musical con proyección continental (ver `latinoamerica`, `evolucion-cultural`).', funFact: 'En 2015, la final internacional de Red Bull Batalla de los Gallos se celebró por primera vez en Chile y el chileno Tom Crowley llegó a la final, cayendo ante el español Arkano — el freestyle chileno ya estaba en el primer nivel mundial (ver `santiago-hip-hop`).', related: ['BATTLE_RAP', 'CHILE2000S', 'CONSCIOUSRAP', 'ESCENACHILE', 'FREESTYLE', 'HIP_HOP', 'IDENTITY', 'LATAM', 'RESISTANCE', 'SANTIAGO', 'TRAP', 'UNDERGROUND'] } },
  { word: 'CHILE80S', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop chileno de los años 80', description: 'La primera ola del hip hop chileno se formó entre 1984 y 1989: b-boys, writers y los primeros grupos nacidos en las poblaciones de Santiago, en pleno fin de la dictadura. Sin discos ni radio, la escena se organizó en torno a puntos de encuentro del centro y de las comunas populares, y dio sus primeras grabaciones cuando el país se preparaba para el plebiscito de 1988 (ver `llegada-hip-hop-chile`, `resistance`).', importance: 'Los años 80 fijaron el ADN del hip hop chileno: nacido en las poblaciones, bajo dictadura, con memoria política y sin industria. La primera ola produjo las crews, los writers, los grupos fundacionales y la primera grabación profesional, y dejó establecido que la cultura se sostenía en la calle y en la organización comunitaria — una base que los 90 convertirían en escena grabada (ver `hip-hop-chileno-90s`).', funFact: 'El 14 de diciembre de 1988, en plena recta final hacia el plebiscito, Panteras Negras dio su primer show en la Población Huamachuco (Renca) en homenaje a Marcelino Marchandón, asesinado por la CNI: el primer rap chileno documentado nació ligado a la memoria de los caídos de la dictadura.', related: ['ANTECEDENTES', 'BOMBEROOSSA', 'B_BOY', 'CHILE90S', 'CULTBARR', 'DJ', 'LLEGADAHH', 'MC', 'PIECE', 'RESISTANCE', 'SANTIAGO', 'TAG', 'UNDERGROUND'] } },
  { word: 'CHILE90S', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop chileno de los años 90', description: 'Los años 90 fueron la década de la consolidación: el rap chileno pasó de la escena callejera de los 80 a los primeros discos, los primeros contratos con sellos, la radio y, desde 1997, el éxito comercial. En paralelo, el rap se afirmó como la voz de las poblaciones: un testimonio en primera persona sobre la pobreza, la cárcel, la represión y la vida de barrio que la transición a la democracia no había resuelto (ver `cultura-de-barrio`, `resistance`, `identity`).', importance: 'Los años 90 convirtieron al rap chileno en una escena grabada y escuchada: primeros discos, primeras multinacionales, primeros videos y primer éxito comercial masivo (Tiro de Gracia, 1997). Al mismo tiempo, fijaron la imagen del rap como voz de las poblaciones y como espacio de denuncia —incluida la crítica a la transición—, en una tensión entre industria y calle que definiría la década siguiente (ver `hip-hop-chileno-2000s`).', funFact: 'El primer concierto de rap de Chile se realizó el 16 de junio de 1990 en el Gimnasio Manuel Plaza (Ñuñoa), apenas tres meses después del retorno a la democracia: la escena que había nacido bajo la dictadura se mostraba públicamente al país con CMC Rappers, Latin Posse y Panteras Negras.', related: ['CHILE2000S', 'CHILE80S', 'CONSCIOUSRAP', 'CULTBARR', 'DJ', 'ECOSISTEMAHH', 'IDENTITY', 'MC', 'RESISTANCE', 'SANTIAGO', 'UNDERGROUND'] } },
  { word: 'LLEGADAHH', category: 'chile', difficulty: 'medium', knowledge: { title: 'La llegada del Hip Hop a Chile', description: 'El Hip Hop llegó a Chile en plena dictadura militar, a mediados de los años 80, y entró primero por el cuerpo y la imagen: el breakdance visto en el cine y la televisión, antes que por los discos de rap. Un estudio académico de Nelson Leandro Rodríguez (2020) documenta la recepción y el aprendizaje de esta cultura musical extranjera en Chile entre 1984 y 1987: el hip hop llegó al país antes que la democracia. La primera ola que siguió a esa llegada se documenta en `hip-hop-chileno-80s`.', importance: 'La llegada del hip hop a Chile bajo dictadura definió el carácter de la escena: una cultura aprendida en la calle, difundida por copias y practicada en espacios públicos del centro de Santiago, con una juventud poblacional que encontró en el baile y el rap un canal de expresión fuera de los medios controlados. Es el punto de partida de toda la historia posterior (ver `hip-hop-chileno-80s`, `hip-hop-chileno-90s`).', funFact: 'El hip hop llegó a Chile antes que la democracia: el estudio académico de Nelson Rodríguez documenta la recepción de la cultura entre 1984 y 1987, y el primer encuentro de crews de breakdance en el Paseo Bombero Ossa, en pleno centro de Santiago, se sitúa hacia 1986 — cuatro años antes del retorno de la democracia (marzo de 1990).', related: ['ANTECEDENTES', 'B_BOY', 'CHILE80S', 'DJ', 'HIP_HOP', 'LATAM', 'MC', 'RESISTANCE', 'SANTIAGO', 'STREETCULT', 'UNDERGROUND'] } },
  { word: 'MCINGCHILE', category: 'chile', difficulty: 'medium', knowledge: { title: 'El MC chileno', description: 'El MC chileno desarrolló una identidad propia dentro del rap en español: una forma de rimar en castellano chileno, con su voseo, sus modismos y su jerga de la calle, y una fuerte tradición de rap conciente nacida en las poblaciones durante y después de la dictadura. Desde los años 80, los MCs chilenos fueron construyendo una escuela que hoy destaca tanto en el rap de estudio como en las batallas de freestyle, donde Chile alcanzó logros internacionales.', importance: 'El MC chileno aportó al hip hop en español una voz territorial: el rap conciente de las poblaciones, que documentó la dictadura y la exclusión social, y una escuela de freestyle que en 2026 llevó la final internacional de Red Bull Batalla a Santiago y consagró a un campeón local. Su forma de rimar en castellano chileno demostró que el rap no necesita traducirse a un español neutro para proyectarse.', funFact: 'El chileno El Menor se coronó campeón internacional de Red Bull Batalla de los Gallos en la final de 2026, disputada en el Movistar Arena de Santiago, imponiéndose como local ante el público de su país.', related: ['BATTLE_RAP', 'CHILE2000S', 'CHILE90S', 'CONSCIOUSRAP', 'CULTBARR', 'ECOSISTEMAHH', 'ESCENACHILE', 'FLOW', 'FREESTYLE', 'HIP_HOP', 'IDENTITY', 'MC', 'RIMA', 'UNDERGROUND'] } },
  { word: 'CIUDADESHH', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop en otras ciudades de Chile', description: 'El hip hop chileno no es solo santiaguino: desde los años 90 se desarrollaron escenas activas en ciudades de todo el país, del norte minero al sur austral. Estas escenas regionales compartieron las mismas coordenadas que la capital —dictadura, poblaciones, cultura de calle— pero con redes, ritmos y territorios propios, y se articularon en encuentros nacionales y festivales locales. Su historia está menos documentada que la de Santiago, por lo que parte de ella vive en la memoria de la propia comunidad.', importance: 'El hip hop de regiones descentralizó la cultura en Chile y demostró que el rap en castellano chileno podía echar raíces en territorios muy distintos: la costa, el desierto y el sur. Los encuentros nacionales y festivales regionales crearon redes de intercambio entre escenas que, sin industria ni medios centrales, sostuvieron la cultura con autogestión. Hoy las regiones siguen aportando artistas y competidores al circuito nacional e internacional.', funFact: 'El Primer Encuentro Nacional de Hip-Hop de Chile se realizó el 5 de junio de 1993 en Coquimbo y reunió a practicantes de varias regiones, lo que evidencia que la organización del hip hop chileno temprano no fue un fenómeno exclusivamente santiaguino.', related: ['COMMUNITY', 'CONCE', 'CULTBARR', 'ECOSISTEMAHH', 'ESTILOSREG', 'HIP_HOP', 'LATAM', 'SANTIAGO', 'UNDERGROUND', 'VALPARAISO'] } },
  { word: 'SANTIAGO', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop en Santiago', description: 'Santiago es el punto de origen del hip hop chileno: los estudios académicos documentan la recepción de la cultura en la capital entre 1984 y 1987, y desde entonces la ciudad concentró la mayor parte de las escenas, los grupos, los sellos y las competencias del país. Esta entrada documenta el hip hop de la capital y su geografía: las comunas y poblaciones donde se desarrolló cada generación (ver `hip-hop-chileno-80s`, `hip-hop-chileno-90s`, `hip-hop-chileno-2010s`).', importance: 'Santiago es el origen y el motor del hip hop chileno: allí llegó la cultura en los 80, allí se grabaron los primeros discos y se formaron los grupos fundacionales, y allí siguen operando las competencias, la industria y la investigación que articulan la escena nacional (ver `latinoamerica`).', funFact: 'La población La Legua, en la comuna de San Joaquín (sur de Santiago), es uno de los territorios más documentados del rap chileno: allí nació Legua York, colectivo de "resistencia cultural" activo desde alrededor del año 2000 que cumplió 25 años en 2025 con el álbum *XXV*.', related: ['BATTLE_RAP', 'BBOYCHILE', 'CHILE2010S', 'CHILE80S', 'CHILE90S', 'CONSCIOUSRAP', 'CULTBARR', 'ECOSISTEMAHH', 'ESCENACHILE', 'FREESTYLE', 'HIP_HOP', 'LATAM', 'MCINGCHILE', 'STREETCULT', 'TRAP', 'UNDERGROUND', 'WRITINGCHILE'] } },
  { word: 'VALPARAISO', category: 'chile', difficulty: 'medium', knowledge: { title: 'Hip hop en Valparaíso y Viña del Mar', description: 'La escena porteña es uno de los polos históricos del hip hop chileno: en Valparaíso y Viña del Mar la cultura llegó en la primera ola de los años 80 — con crews de breaking formadas en 1985, apenas iniciada la recepción nacional — y se desarrolló entre el puerto, los cerros y la calle. Esta entrada documenta el hip hop de la Región de Valparaíso, su historia temprana, su patrimonio gráfico y su escena actual (ver `breaking-chileno`, `writing-chileno`).', importance: 'La escena porteña aportó al hip hop chileno una historia temprana del breaking (crews de 1985), un patrimonio del writing con nombres pioneros (DDC, ACB) y un modelo de festival territorial — Hip Hop al Puerto — que celebra la memoria de la cultura en el espacio público del puerto y los cerros (ver `latinoamerica`).', funFact: 'En 1985, en la primera ola del hip hop chileno, ya existían en Valparaíso cuatro crews de breaking documentadas — Montaña Breakers, B14, TNT y Floor Masters — y Viña del Mar tenía su primera crew de graffiti, DDC, cuyo miembro Boris sigue archivando la historia de la escena (UP Magazine, 2026).', related: ['BBOYCHILE', 'CHILE80S', 'CIUDADESHH', 'CULTBARR', 'ECOSISTEMAHH', 'ESCENACHILE', 'HIP_HOP', 'LATAM', 'SANTIAGO', 'STREETCULT', 'UNDERGROUND', 'WRITINGCHILE'] } },
  { word: 'WRITINGCHILE', category: 'chile', difficulty: 'medium', knowledge: { title: 'Writing en Chile', description: 'El writing chileno une la escritura de graffiti de raíz neoyorquina con la tradición muralista latinoamericana: nació a mediados de los 80, cuando la película *Beat Street* pasó la censura de la dictadura e inspiró a los primeros escritores, y creció hasta convertirse en una escena con crews, encuentros, galerías y museos a cielo abierto. Es, junto al breaking, uno de los elementos que llegaron a Chile antes que el rap.', importance: 'El writing chileno construyó un puente entre la escritura de graffiti neoyorquina y el muralismo latinoamericano, en un contexto político extremo donde pintar era arriesgado. Sus pioneros, encuentros y galerías abrieron el camino a la institucionalización del arte urbano en Chile, y su memoria documenta una parte central de la cultura hip hop local.', funFact: 'El graffiti llegó a Chile con la película *Beat Street* (1984), que pasó la censura de la dictadura, y su primer impulsor documentado, Vampi, comenzó pintando con tiza porque los aerosoles eran inaccesibles para un niño de 14 años.', related: ['CHILE80S', 'CULTBARR', 'ECOSISTEMAHH', 'HIP_HOP', 'MURAL', 'PIECE', 'RESISTANCE', 'SANTIAGO', 'STREETCULT', 'TAG', 'WILDSTYLE', 'WRITERSHIST'] } },
  { word: 'ANATIJOUX', category: 'chile', difficulty: 'medium', knowledge: { title: 'Ana Tijoux', description: 'Ana Tijoux (Anamaría Tijoux Merino, nacida el 12 de junio de 1977 en Lille, Francia) es una MC y cantante chilena, hija de exiliados chilenos, que se hizo conocida como MC del grupo Makiza en los 90 y luego construyó una carrera solista internacional con discos como *1977* (2010), *La Bala* (2011) y *Vengo* (2014). Es la figura chilena del rap con mayor proyección mundial, con nominaciones y premios Latin Grammy documentados.', importance: 'Ana Tijoux es la MC chilena que conectó el rap local con el circuito internacional: llevó el rap conciente en español a audiencias globales, con reconocimientos de la industria (Latin Grammy) y de la crítica, y abrió camino a las generaciones siguientes del rap chileno y latinoamericano.', funFact: 'En 2014, Ana Tijoux ganó el Grammy Latino a Grabación del Año por "Universos paralelos", junto a Jorge Drexler: fue uno de los hitos más altos del rap en español en los premios de la academia latina.', related: ['CHILE90S', 'CONSCIOUSRAP', 'LATAM', 'MAKIZA', 'MCINGCHILE'] } },
  { word: 'BEATSTREET', category: 'historia', difficulty: 'easy', knowledge: { title: 'Beat Street', description: '*Beat Street* es la película de 1984 dirigida por Stan Lathan que llevó el Hip Hop del South Bronx a la gran pantalla con producción de Hollywood: cuenta la historia de dos hermanos y su grupo de amigos, cada uno dedicado a un elemento de la cultura —el breaking, el DJing y el graffiti—, en el Nueva York de comienzos de los 80. Estrenada el 8 de junio de 1984 por Orion Pictures, con 105 minutos de duración y un presupuesto documentado de 9,5 millones de dólares, es junto a *Wild Style* (1983) una de las dos películas que fijaron la imagen del Hip Hop en el cine. El personaje del artista graffiti, Ramo, fue interpretado por Jon Chardiet (no por Lee Quiñones, como a veces se afirma erróneamente).', importance: '*Beat Street* llevó el Hip Hop a un público masivo con producción de estudio: sus escenas de breaking, sus batallas y su retrato del graffiti en los trenes llegaron a países donde la cultura aún no existía, y en Chile, por ejemplo, el estreno de la película (junto a *Flashdance* y *Breakin\'*) fue uno de los detonantes de la primera ola de b-boys a mediados de los 80 (ver `breaking-chileno`). La película también mostró los cuatro elementos de la cultura en pantalla grande, consolidando la imagen del Hip Hop como movimiento completo: baile, DJ, graffiti y rap.', funFact: 'El personaje del artista graffiti en *Beat Street* es Ramo, interpretado por el actor Jon Chardiet, y no Lee Quiñones: la confusión entre ambos circula en algunas fuentes y la corrección ya está documentada en la entrada `writers-historicos`.', related: ['BAMBAATAA', 'B_BOY', 'CRAZYLEGS', 'EXPANSION80S', 'HIP_HOP', 'PIECE', 'PLANETROCK', 'ROCKSTEADY', 'TAG', 'WILDSTYLE', 'WRITERSHIST'] } },
  { word: 'BOMBEROOSSA', category: 'chile', difficulty: 'medium', knowledge: { title: 'Paseo Bombero Ossa', description: 'El Paseo Bombero Ossa es un paseo peatonal del centro de Santiago de Chile que se convirtió, hacia 1986, en el punto de encuentro de los primeros b-boys chilenos: allí se reunían las crews de breakdance a bailar, intercambiar música y competir, en plena dictadura (1973-1990). Es el primer espacio público documentado de la escena hip hop chilena, anterior al auge del rap local de los 90, y funciona como símbolo del origen del movimiento en Chile (ver `breaking-chileno` y `hip-hop-chileno-80s`).', importance: 'El Paseo Bombero Ossa es el lugar fundacional del hip hop chileno: allí se reunió la primera generación de b-boys del país y se sembraron las semillas del rap, el graffiti y el DJing local (ver `ecosistema-hip-hop-chile`). Su historia muestra cómo el hip hop, nacido en las calles de Nueva York, se adaptó a un contexto completamente distinto —el Chile de la dictadura— y encontró en el espacio público del centro de Santiago su primer territorio (ver `hip-hop-chileno-80s` y `santiago-hip-hop`).', funFact: 'Hacia 1986, el Paseo Bombero Ossa, en el centro de Santiago, se convirtió en el punto de encuentro de los primeros b-boys chilenos: el primer espacio público documentado del hip hop en Chile.', related: ['BBOYCHILE', 'BEATSTREET', 'B_BOY', 'CHILE80S', 'CYPHER', 'LLEGADAHH', 'SANTIAGO'] } },
  { word: 'BOTY', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Battle of the Year', description: 'El Battle of the Year (BOTY) es una competencia internacional de breaking fundada en 1990 por Thomas Hergenröther en Hannover, Alemania. Es la competencia de crews —equipos de b-boys y b-girls— más antigua y de mayor tradición del mundo: las crews de cada país se clasifican en torneos regionales y las ganadoras se enfrentan en la final internacional. Junto a la fundación de competencias individuales como Red Bull BC One (2004), el BOTY es uno de los pilares del circuito mundial de batallas de breaking (ver `battle` y `b-boy`).', importance: 'El BOTY es la competencia que internacionalizó el breaking por crews: durante los 90, cuando el baile había desaparecido de los medios masivos, mantuvo vivo el circuito competitivo y creó el modelo de clasificatorios nacionales que luego adoptaron otras competencias (ver `red-bull-bc-one`). Su historia también muestra cómo el breaking, nacido en Nueva York, se convirtió en una cultura global con escenas propias en Europa, Asia y América Latina (ver `europa` y `latinoamerica`).', funFact: 'El Battle of the Year fue fundado en 1990 por Thomas Hergenröther en Hannover, Alemania, con una primera edición de 9 crews y unos 400 visitantes; es la competencia internacional de breaking por crews más antigua del mundo.', related: ['BATTLE', 'BCONE', 'B_BOY', 'COMPETITION', 'CYPHER', 'EUROPA', 'FOUNDATION', 'LINCOLN81', 'ROCKSTEADY'] } },
  { word: 'CINDYCAMP', category: 'historia', difficulty: 'easy', knowledge: { title: 'Cindy Campbell', description: 'Cindy Campbell es la hermana menor de DJ Kool Herc (Clive Campbell) y la organizadora de la fiesta del 11 de agosto de 1973 en el 1520 Sedgwick Avenue, el hito más citado del nacimiento del Hip Hop. Fue ella quien alquiló el salón, cobró la entrada y promovió el evento para recaudar dinero para su ropa de vuelta a clases, con su hermano como DJ.', importance: 'Sin la iniciativa de Cindy Campbell no existiría la fiesta del 11 de agosto de 1973, el hito documentado que la historiografía usa como referencia del nacimiento del Hip Hop. Su testimonio es, junto al flyer, la base del registro de esa fecha, y su rol muestra que las fiestas fundacionales fueron un esfuerzo familiar y comunitario, no un acto individual.', funFact: 'La fiesta del 11 de agosto de 1973 en el 1520 Sedgwick Avenue, organizada por Cindy Campbell para juntar plata para su ropa de vuelta a clases, es el hito más citado del nacimiento del Hip Hop; el edificio fue reconocido oficialmente como "lugar de nacimiento del hip hop" por el estado de Nueva York en 2007.', related: ['BLOCK_PARTY', 'BRONX', 'DJ_KOOL_HERC', 'HIP_HOP', 'SEDGWICK73'] } },
  { word: 'COKE_LA_ROCK', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Coke La Rock', description: 'Coke La Rock es un MC del Bronx, amigo de la infancia de DJ Kool Herc y miembro original de los Herculoids, la crew de Herc. La tradición oral de la escena lo reconoce como el primer MC del Hip Hop: según esa versión, sus saludos improvisados por el micrófono en las fiestas de Herc, desde 1973, dieron origen al MCing. No hay registros contemporáneos que confirmen esa primacía.', importance: 'Coke La Rock representa el eslabón entre la función del DJ animador y el MC como artista: sus saludos improvisados son, según la tradición oral, el germen del rap. Su historia también documenta cómo el MCing nació como práctica oral y efímera —sin grabaciones, sin canciones— antes de convertirse en industria.', funFact: 'Según la tradición oral, la frase "Hotel, motel, you don\'t tell, we won\'t tell", atribuida a los saludos de Coke La Rock, fue inmortalizada sin crédito en "Rapper\'s Delight" (1979), la primera canción de rap en entrar al Top 40 de Billboard.', related: ['DJ_KOOL_HERC', 'HERCULOIDS', 'MC', 'PRIMEROSMCS', 'RAPDELIGHT', 'SEDGWICK73'] } },
  { word: 'CRAZYLEGS', category: 'breaking', difficulty: 'easy', knowledge: { title: 'Crazy Legs', description: 'Crazy Legs (Richard Colón) es un b-boy del Bronx, presidente de la Rock Steady Crew y una de las figuras que llevó el breaking del círculo de la fiesta al escenario mundial en los años 80. Según la historia de la crew, en 1979 creó la rama de Manhattan de la Rock Steady Crew junto a B-Boy Fresh, la que popularizó el nombre a nivel global, y en 1983 llevó el baile a Londres y París.', importance: 'Crazy Legs es el embajador del breaking: como presidente de la Rock Steady Crew difundió el baile por el mundo, lo llevó del cypher a la pantalla y al teatro, y formó generaciones de b-boys. Su figura conecta la era fundacional del Bronx con la profesionalización global del breaking (ver `battle` y `cypher`).', funFact: 'En 1983, con 16 años, Crazy Legs integró la New York City Rap Tour que llevó el Hip Hop —DJs, MCs, graffiti y breaking— por primera vez a París y Londres, un hito en la globalización de la cultura.', related: ['BATTLE', 'BEATSTREET', 'B_BOY', 'CYPHER', 'LINCOLN81', 'ROCKSTEADY', 'STYLEWARS', 'WILD_STYLE'] } },
  { word: 'THEODORE', category: 'djing', difficulty: 'easy', knowledge: { title: 'Grand Wizzard Theodore', description: 'Grand Wizzard Theodore (Theodore Livingston, nacido el 5 de marzo de 1963 en el Bronx, Nueva York) es un DJ pionero del Hip Hop al que la escena atribuye la invención del scratching: frotar el disco contra la aguja para producir un sonido rítmico. Según su propio testimonio, descubrió la técnica por accidente hacia 1975, cuando era un adolescente aprendiendo a pinchar en su habitación.', importance: 'Theodore es la figura de referencia del scratching, la técnica que definió al DJ de Hip Hop como instrumentista: convirtió el error —frotar un disco— en un lenguaje musical. Su frase y su estilo influyeron directamente en la generación del turntablism y en el sonido sampleado del Hip Hop posterior (ver `scratching` y `turntablism`).', funFact: 'La frase "Say turn it up", dicha por Theodore en "Fantastic Freaks at the Dixie" (1980), fue sampleada por Public Enemy ("Bring the Noise") y por innumerables producciones, convirtiendo su voz en uno de los samples más usados de la historia del Hip Hop.', related: ['BREAKBEAT', 'DJ', 'SCRATCHING', 'TURNTABLISM', 'WILD_STYLE'] } },
  { word: 'GMASTERCAZ', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Grandmaster Caz', description: 'Grandmaster Caz (Curtis Brown, nacido el 18 de abril de 1960 en el Bronx, Nueva York) es un MC, DJ y compositor, miembro de The Cold Crush Brothers desde 1979, una de las crews de MCs más influyentes del old school. Es mundialmente conocido por una controversia: según su testimonio, sus rimas fueron rapeadas sin crédito por Big Bank Hank en "Rapper\'s Delight" (1979), la canción que llevó el rap al público masivo.', importance: 'Caz es una figura doble del old school: como MC de los Cold Crush Brothers ayudó a definir la era de las crews escritas, y su caso —rimas usadas sin crédito en la canción más famosa del rap temprano— es el ejemplo canónico de las disputas de autoría que marcaron el paso del rap de la calle a la industria.', funFact: 'En "Rapper\'s Delight" (1979), Big Bank Hank se presenta rapeando "I\'m the C-A-S-A-N-O-V-A" — el apodo de Grandmaster Caz (Casanova Fly)—, la pista más citada de que las rimas venían del cuaderno de Caz, según su testimonio y la prensa.', related: ['CREWS_70S', 'MC', 'OLD_SCHOOL', 'RAPDELIGHT', 'WILD_STYLE'] } },
  { word: 'HARLEMWORLD', category: 'historia', difficulty: 'medium', knowledge: { title: 'Harlem World', description: 'Harlem World fue un club de Nueva York que albergó, en diciembre de 1981, la batalla entre Kool Moe Dee y Busy Bee Starski durante la celebración navideña llamada Christmas Rappers Convention: un enfrentamiento ampliamente citado como el battle que cambió el battle rap (ver `battle-rap`). En ese duelo, Kool Moe Dee rapeó versos escritos y dirigidos directamente contra Busy Bee, en vez de la exhibición amistosa de rimas que era lo habitual, y el público reaccionó como juez. El club quedó en la historia de la cultura como el escenario de uno de los momentos fundacionales del rap competitivo (ver `mc`).', importance: 'Harlem World es el escenario del hito fundacional del battle rap: la batalla de diciembre de 1981 entre Kool Moe Dee y Busy Bee Starski definió el formato del duelo de MCs con rimas escritas y dirigidas al rival (ver `battle-rap` y `diss`), y demostró que el rap podía competir con palabras como el breaking competía con movimientos. El club representa, además, el papel de los espacios de fiesta de Nueva York como laboratorios donde se inventaron las formas del rap (ver `nueva-york`).', funFact: 'En diciembre de 1981, en el club Harlem World de Nueva York, Kool Moe Dee derrotó en la Christmas Rappers Convention a Busy Bee Starski con rimas escritas y dirigidas contra él: el duelo es ampliamente citado como el battle que cambió el battle rap.', related: ['BATTLE_RAP', 'BEEF', 'DISS', 'FREESTYLE', 'MC', 'NUEVA_YORK'] } },
  { word: 'ILLMATIC', category: 'historia', difficulty: 'easy', knowledge: { title: 'Illmatic', description: '*Illmatic* es el álbum debut del rapero Nas, lanzado el 19 de abril de 1994 por Columbia Records. Grabado entre 1992 y 1993 con producción de DJ Premier, Large Professor, Pete Rock, Q-Tip y L.E.S., es uno de los discos más influyentes del rap de Nueva York: sus diez canciones narran la vida en Queensbridge, el complejo de viviendas públicas de Queens donde creció Nas, con un nivel de detalle lírico que lo convirtió en referente del boom bap y del rap conciente de los 90 (ver `boom-bap` y `golden-era`). La crítica lo considera, junto a discos de la misma época, la cima del rap neoyorquino de los 90.', importance: '*Illmatic* redefinió el rap de Nueva York: su combinación de producción de primera línea, narrativa callejera detallada y técnica lírica (rimas internas y multisilábicas, ver `flow` y `rima-multisilabica`) marcó a toda una generación de MCs y productores. Es el disco que consolidó a Queensbridge como territorio del rap, elevó el estándar del álbum de rap como obra (ver `album` y `concept-album`) y sigue siendo citado por artistas de todo el mundo, incluida la escena chilena, como referencia del rap conciente (ver `conscious-rap`).', funFact: '*Illmatic* se grabó entre 1992 y 1993 y se lanzó el 19 de abril de 1994: diez canciones, 39 minutos con 48 segundos, producidas por DJ Premier, Large Professor, Pete Rock, Q-Tip y L.E.S., con una sola colaboración invitada (AZ en "Life\'s a Bitch").', related: ['ALBUM', 'BOOM_BAP', 'CONSCIOUSRAP', 'EXPANSION80S', 'GOLDEN_ERA', 'JAZZ_RAP', 'NUEVA_YORK', 'SAMPLE', 'THEMESSAGE', 'WILD_STYLE'] } },
  { word: 'JDILLA', category: 'produccion', difficulty: 'medium', knowledge: { title: 'J Dilla', description: 'J Dilla (James Dewitt Yancey, 7 de febrero de 1974 – 10 de febrero de 2006) fue un productor, rapero y compositor de Detroit, Míchigan, considerado uno de los productores más influyentes del Hip Hop y de la música popular contemporánea. Su manera de programar la batería —con un swing sutil y "imperfecto" que suena humano— y su tratamiento del sampleo marcaron a generaciones de beatmakers, y su álbum *Donuts* (2006) es una obra de culto del beatmaking instrumental.', importance: 'J Dilla redefinió lo que puede hacer un beatmaker: su tratamiento del ritmo —el "swing de Dilla"— y su forma de samplear influyeron en productores de todo el mundo y en géneros que van del rap al R&B y la electrónica. Su obra demostró que el beat instrumental podía ser una forma artística por derecho propio, y su figura es central para entender el beatmaking moderno (ver `beatmaker` y `beat`).', funFact: '*Donuts* (2006) es una obra instrumental de 31 pistas, hecha en gran parte con un sampler Akai MPC mientras J Dilla estaba hospitalizado; se publicó el día de su cumpleaños, tres días antes de su muerte, y desde entonces es uno de los álbumes de culto del beatmaking.', related: ['BEATMAKER', 'LOFIHIPHOP', 'MPC', 'PRODUCER', 'SAMPLING'] } },
  { word: 'LINCOLN81', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Batalla del Lincoln Center (1981)', description: 'La batalla del Lincoln Center fue un enfrentamiento de breaking entre la Rock Steady Crew (South Bronx) y los Dynamic Rockers (Brooklyn/Queens), celebrado el 15 de agosto de 1981 en el marco del festival Lincoln Center Out of Doors de Nueva York. Es una de las batallas más documentadas de la historia del breaking: se libró a plena luz del día, ante una multitud estimada en unas 18.000 personas según las crónicas de la época, y quedó registrada en filmaciones que circularon por la escena (ver `rock-steady-crew`). Se la recuerda como el momento en que el baile del Bronx saltó a la escena pública masiva.', importance: 'La batalla del Lincoln Center es uno de los hitos fundacionales del breaking como fenómeno público: mostró el baile del Bronx en un escenario cultural de élite de Manhattan, ante un público masivo, y demostró que las crews de barrio podían competir en cualquier terreno. Para la Rock Steady Crew, fue el momento en que su nombre se volvió leyenda urbana (ver `rock-steady-crew`); para la cultura, es el ejemplo más citado de la batalla de breaking como espectáculo público (ver `battle`).', funFact: 'El 15 de agosto de 1981, la Rock Steady Crew y los Dynamic Rockers batallaron a plena luz del día en el Lincoln Center de Nueva York, ante una multitud estimada en unas 18.000 personas según las crónicas de la época.', related: ['BATTLE', 'B_BOY', 'COMPETITION', 'CRAZYLEGS', 'CYPHER', 'NUEVA_YORK', 'ROCKSTEADY', 'STYLEWARS'] } },
  { word: 'MAKIZA', category: 'chile', difficulty: 'medium', knowledge: { title: 'Makiza', description: 'Makiza fue el grupo chileno de rap formado en Santiago en 1997 por Anita Tijoux, Seo2, el DJ Squat y Cenzi, todos provenientes del colectivo Demosapiens. Con «Vida salvaje» (1998) y «Aerolíneas Makiza» (1999, con Sony Music) se convirtió en referencia del rap conciente chileno: un rap crítico con la dictadura de Pinochet y con sus colaboradores, que generó controversia pública (ver `conscious-rap`). El grupo estuvo activo entre 1997 y 2000 y se reunió entre 2004 y 2006.', importance: 'Makiza demostró que el rap chileno podía ser a la vez conciente y exitoso en la industria: «En paro» (1999) abrió un debate público sobre la colaboración con la dictadura desde el rap, y su obra quedó como referencia del rap político chileno (ver `hip-hop-chileno-90s`, `hip-hop-chileno-2000s`). Además, fue la escuela de la MC más internacional del rap chileno: Ana Tijoux construyó desde ahí una carrera reconocida con premios internacionales (ver `ana-tijoux`).', funFact: '«En paro» (1999), single de «Aerolíneas Makiza», atacó por su nombre a figuras públicas que colaboraron con la dictadura de Pinochet: fue uno de los momentos en que el rap chileno llevó la crítica política de la transición directamente a la agenda pública.', related: ['ANATIJOUX', 'CHILE90S', 'CONSCIOUSRAP', 'HIP_HOP', 'LATAM', 'PANTERAS', 'TIRODEGRACIA'] } },
  { word: 'MARLEYMARL', category: 'produccion', difficulty: 'medium', knowledge: { title: 'Marley Marl', description: 'Marley Marl (Marlon Williams, nacido el 30 de septiembre de 1962) es un DJ y productor nacido en los proyectos Queensbridge, en Queens, Nueva York, considerado uno de los pioneros del sampling en el Hip Hop. Según su propio testimonio, descubrió por accidente que se podía tocar un fragmento de un disco viejo como si fuera un instrumento, y con esa técnica construyó el sonido de la Juice Crew y de Cold Chillin\' Records en los 80.', importance: 'Marley Marl es, según su propio testimonio y la historia del género, uno de los arquitectos del sampling: la técnica que convirtió al productor de rap en un músico que compone con fragmentos de otros discos (ver `producer` y `sample`). Su producción con la Juice Crew definió el sonido de Queens en los 80 y abrió el camino a la era del sampleo masivo de los 90.', funFact: 'El sonido característico de Marley Marl combinaba la caja de ritmos Roland TR-808 con samplers disparados por ella; ese empaste, según sus colegas, le daba a cualquier disco sampleado una base pesada y cálida que se volvió su firma.', related: ['BEAT', 'MPC', 'PRODUCER', 'SAMPLE', 'SAMPLING'] } },
  { word: 'MELLEMEL', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Melle Mel', description: 'Melle Mel (Melvin Glover, nacido el 15 de mayo de 1961 en el Bronx, Nueva York) es el vocalista principal y principal escritor de rimas de Grandmaster Flash and the Furious Five, la crew que llevó el rap a las grabaciones de estudio. Es coautor de "The Message" (1982), la canción que demostró que el rap podía contar la vida del barrio con crudeza social y que es considerada la fundadora del rap conciente (conscious rap).', importance: 'Melle Mel definió al MC como escritor y cronista: "The Message" abrió la vena social del rap e influyó en todo el rap conciente posterior (ver `conscious-rap`). Su carrera también documenta la transición del rap de la fiesta a la industria y las disputas de créditos y regalías que marcaron esa era.', funFact: '"The Message" (1982), coescrita y rapeada por Melle Mel sobre el instrumental de Duke Bootee, fue el primer disco de rap en entrar al Registro Nacional de Grabaciones de EE. UU. y al Grammy Hall of Fame.', related: ['CONSCIOUSRAP', 'FLASH', 'MC', 'OLD_SCHOOL', 'THEMESSAGE'] } },
  { word: 'NWA', category: 'mcing', difficulty: 'easy', knowledge: { title: 'N.W.A', description: 'N.W.A (abreviación de «Niggaz Wit Attitudes») es el grupo pionero del gangsta rap, formado en Compton, California, en 1987 por Eazy-E, Dr. Dre, Ice Cube, MC Ren, DJ Yella y Arabian Prince. Su álbum «Straight Outta Compton» (enero de 1989) retrató la vida en los barrios negros de Los Ángeles desde dentro —violencia, narcotráfico, abuso policial— y provocó la primera gran controversia nacional del rap: una carta de advertencia del FBI por el tema «Fuck tha Police» (ver `gangsta-rap`). Vendió más de 10 millones de unidades solo en Estados Unidos y es una de las agrupaciones más influyentes del Hip Hop.', importance: 'N.W.A convirtió el gangsta rap en el subgénero más vendido y más controvertido del Hip Hop: su crudeza narrativa puso en el centro del debate nacional la vida en los barrios negros y la relación con la policía (ver `gangsta-rap`, `resistance`). Su influencia define la Costa Oeste: de sus filas salieron las carreras de Dr. Dre (y con él el g-funk), Ice Cube y Eazy-E, y su historia se volvió referencia obligada del rap callejero en todo el mundo.', funFact: 'El 1 de agosto de 1989, el subdirector asistente del FBI, Milt Ahlerich, envió una carta a Ruthless/Priority Records por «Fuck tha Police»: fue la primera vez que el gobierno federal intervino formalmente contra una canción de rap, y la carta quedó expuesta en el Rock and Roll Hall of Fame.', related: ['CONSOLIDA80', 'EE_UU', 'EXPANSION80S', 'GANGSTA_RAP', 'HARDCORE_RAP', 'HIP_HOP', 'PUBLIC_ENEMY'] } },
  { word: 'PANTERAS', category: 'chile', difficulty: 'medium', knowledge: { title: 'Panteras Negras', description: 'Panteras Negras es un grupo de rap chileno nacido en la Población Huamachuco de Renca (Santiago) a fines de los años 80, en plena fase final de la dictadura de Pinochet. Junto a Los Marginales y Latin Posse, integra la primera ola del hip hop chileno y se disputa la primacía del primer grupo del país, una controversia que el catálogo documenta sin elegir versiones (ver `hip-hop-chileno-80s`). Su historia mezcla el nacimiento del rap chileno, la represión de la dictadura y la censura de la transición.', importance: 'Panteras Negras es una de las piezas fundacionales del rap chileno: su historia condensa el origen poblacional del género, su vínculo con la memoria política de la dictadura y la censura que la transición mantuvo sobre el rap crítico. Su trayectoria aparece en los relatos de la primera ola (ver `hip-hop-chileno-80s`) y de la consolidación de los 90 (ver `hip-hop-chileno-90s`).', funFact: 'El primer show documentado de Panteras Negras fue un acto político: el 14 de diciembre de 1988, en la Población Huamachuco, en homenaje a Marcelino Marchandón, militante asesinado por la CNI, a menos de un año del plebiscito que terminó con la dictadura.', related: ['CHILE80S', 'CHILE90S', 'CONSCIOUSRAP', 'CULTBARR', 'LLEGADAHH', 'MAKIZA', 'RESISTANCE', 'TIRODEGRACIA'] } },
  { word: 'PLANETROCK', category: 'historia', difficulty: 'easy', knowledge: { title: 'Planet Rock', description: '"Planet Rock" es la canción de Afrika Bambaataa & Soulsonic Force publicada en 1982 por Tommy Boy Records y producida por Arthur Baker. Con sus líneas sintetizadas inspiradas en la electrónica alemana, la batería programada de una caja de ritmos y las rimas futuristas de la Soulsonic Force, se la reconoce como la pieza que fundó el electro dentro del Hip Hop y que llevó el sonido sintético al rap. Robert Palmer, crítico de The New York Times, la describió en 1983 como "quizás el disco pop negro más influyente de 1982".', importance: '"Planet Rock" amplió la paleta sonora del Hip Hop: demostró que el rap podía montarse sobre música electrónica sintética y no solo sobre discos de funk y soul, y dio forma al electro como subgénero. También consolidó a Afrika Bambaataa y a la Zulu Nation como fuerza cultural de la escena neoyorquina y abrió el camino para el uso creativo de la caja de ritmos y el sintetizador en el beatmaking (ver `drum-machine` y `synth`). Su influencia se sintió en el rap y en la música negra y electrónica de la década.', funFact: '"Planet Rock" fue descrita por el crítico Robert Palmer (The New York Times, 1983) como "quizás el disco pop negro más influyente de 1982", y su estribillo "rock rock to the planet rock, don\'t stop" sigue siendo uno de los más citados del Hip Hop temprano.', related: ['BAMBAATAA', 'BREAKBEAT', 'DJ', 'DRUM_MACHINE', 'EXPANSION80S', 'GRABACIONES', 'HIP_HOP', 'RAPDELIGHT', 'SAMPLE', 'SYNTH', 'THEMESSAGE', 'ZULU_NATION'] } },
  { word: 'PUBLIC_ENEMY', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Public Enemy', description: 'Public Enemy es un grupo de rap estadounidense formado en Long Island, Nueva York, en 1985 por Chuck D (Carlton Ridenhour) y Flavor Flav (William Drayton), con la producción de The Bomb Squad y el DJ Terminator X. Es el referente máximo del rap político: sus discos de fines de los 80 y comienzos de los 90, encabezados por «It Takes a Nation of Millions to Hold Us Back» (1988), llevaron la crítica al racismo y a los medios de masas a un público masivo (ver `conscious-rap`). Fue inducido al Rock and Roll Hall of Fame en 2013 y recibió el Grammy a la trayectoria en 2020.', importance: 'Public Enemy definió el rap político como corriente central: demostró que el hip hop podía ser a la vez masivo y explícitamente contestatario, y su sonido —capas de samples, sirenas, ruido y MCs en llamada y respuesta— marcó la producción del golden era (ver `golden-era`). Su obra es referencia obligada del rap de denuncia en todo el mundo, incluida la escena chilena (ver `conscious-rap`, `hip-hop-chileno-80s`).', funFact: '«It Takes a Nation of Millions to Hold Us Back» (1988) fue el primer álbum de hip hop en encabezar el Pazz & Jop, la encuesta de críticos del Village Voice, y «Fight the Power» (1989) fue escrita para la película *Do the Right Thing* de Spike Lee, donde suena en la escena final.', related: ['CONSCIOUSRAP', 'CONSOLIDA80', 'EE_UU', 'EXPANSION80S', 'GOLDEN_ERA', 'HARDCORE_RAP', 'HIP_HOP', 'NWA'] } },
  { word: 'RAHZEL', category: 'historia', difficulty: 'medium', knowledge: { title: 'Rahzel', description: 'Rahzel (Rozell Manely Brown, nacido el 6 de octubre de 1964 en Queens, Nueva York) es un beatboxer y rapero estadounidense, conocido mundialmente por su capacidad de cantar o rapear mientras beatboxea al mismo tiempo. Fue miembro de The Roots y es considerado una de las figuras que llevó el beatbox a otro nivel en los años 90, convirtiéndolo en un arte solista con álbumes propios (ver `human-beatbox`).', importance: 'Rahzel es la figura puente del beatbox: demostró que la disciplina podía sostenerse como arte solista grabado —no solo como acompañamiento en vivo— y que se podía cantar y percusionar al mismo tiempo, algo que amplió las posibilidades técnicas del beatbox para toda la generación siguiente. Su álbum de 1999 es referente obligado de la disciplina, y su paso por The Roots lo convirtió en el beatboxer más visible de su generación dentro del Hip Hop mainstream.', funFact: 'Rahzel es conocido por rapear y beatboxear simultáneamente: su tema "If Your Mother Only Knew" (pista oculta de *Make the Music 2000*, 1999) muestra esa habilidad, y su beatbox de "Iron Man" de Black Sabbath es una de sus performances más famosas.', related: ['BASS', 'BEATBOX', 'CYPHER', 'HI_HAT', 'HUMANBEATBOX', 'KICK', 'MC', 'MOUTHDRUM', 'SNARE', 'VOCALPERC'] } },
  { word: 'BCONE', category: 'breaking', difficulty: 'medium', knowledge: { title: 'Red Bull BC One', description: 'El Red Bull BC One es una competencia internacional anual de breaking organizada por la marca Red Bull desde 2004: su primera edición se celebró en Biel, Suiza, y desde entonces se ha convertido en el torneo individual de b-boys más importante del mundo. A diferencia de competencias por crews como el Battle of the Year (ver `boty`), el BC One enfrenta a dieciséis b-boys en un torneo eliminatorio uno contra uno (ver `battle`). Sus finales mundiales recorren distintas ciudades y sus clasificatorios nacionales —los "cyphers"— llevan la competencia a decenas de países, incluido Chile.', importance: 'El Red Bull BC One llevó el breaking individual a un nivel de producción y difusión global sin precedentes: sus finales se transmiten en vivo, sus clasificatorios nacionales dan visibilidad a las escenas locales de cada país y su formato de duelo directo reavivó el interés por la competencia de b-boys en el siglo XXI. Para escenas como la chilena, los cyphers del BC One funcionan como vitrina internacional y como punto de encuentro generacional (ver `breaking-chileno` y `competition`).', funFact: 'El Red Bull BC One celebró su primera edición en 2004 en Biel, Suiza, con Omar (EE. UU.) como primer campeón mundial; desde entonces es el torneo individual de breaking más importante del mundo.', related: ['BATTLE', 'BOTY', 'B_BOY', 'COMPETITION', 'CRAZYLEGS', 'CYPHER', 'EUROPA', 'LINCOLN81', 'ROCKSTEADY'] } },
  { word: 'RUN_DMC', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Run-DMC', description: 'Run-DMC es el grupo de rap formado en Hollis, Queens (Nueva York), en 1983 por Joseph «Run» Simmons, Darryl «D.M.C.» McDaniels y Jason «Jam Master Jay» Mizell. Junto a Beastie Boys, LL Cool J y Public Enemy, lideró el paso del old school a la «nueva escuela» del rap y abrió la edad de oro del género (ver `golden-era`). Fue el primer grupo de rap en lograr discos de oro y platino, en sonar en MTV y en entrar al Rock and Roll Hall of Fame, y su versión de «Walk This Way» con Aerosmith (1986) marcó el cruce del rap con el rock.', importance: 'Run-DMC convirtió el rap en un espectáculo masivo: demostró que el género podía llenar estadios, vender millones y cruzar a la radio y la TV mainstream (ver `expansion-80s`). Su estética de calle definió la imagen del rapero por décadas y su fusión con el rock abrió el camino al rap rock de los 90. Fue el segundo grupo de hip hop en ingresar al Rock and Roll Hall of Fame (2009), después de Grandmaster Flash & The Furious Five (2007), y el primero en recibir el Grammy a la trayectoria (2016).', funFact: '«Walk This Way» (1986), grabada junto a Aerosmith, llegó al puesto 4 del Billboard Hot 100 —más arriba que el original de 1975—, convirtió el rap en un éxito de radio masivo y relanzó la carrera de la banda de rock.', related: ['CONSOLIDA80', 'EXPANSION80S', 'GOLDEN_ERA', 'HIP_HOP', 'OLD_SCHOOL', 'PUBLIC_ENEMY', 'SUGARHILL'] } },
  { word: 'STYLEWARS', category: 'historia', difficulty: 'easy', knowledge: { title: 'Style Wars', description: '*Style Wars* es el documental de 1983 dirigido por Tony Silver y producido en colaboración con Henry Chalfant que registró el graffiti, el breaking y el MCing de Nueva York a comienzos de los 80, en plena expansión de la cultura (ver `expansion-80s`). Emitido por PBS en 1983 y ganador del Grand Prize for Documentaries en el Festival de Cine de Sundance de ese año, se lo considera uno de los documentos audiovisuales más importantes del Hip Hop temprano: muestra a los escritores pintando trenes enteros (wholecars), a los b-boys batallando en las calles y la guerra de la ciudad contra el graffiti. Su co-productor, Henry Chalfant, es el mismo fotógrafo que documentó el graffiti neoyorquino y publicó con Martha Cooper el libro *Subway Art* (1984).', importance: '*Style Wars* es el registro audiovisual de referencia del graffiti y el breaking de la era dorada: sus imágenes de wholecars y de batallas callejeras difundieron la cultura por todo el mundo y sirvieron de modelo para generaciones de writers y b-boys. Para el graffiti en particular, el documental documentó el trabajo de los writers sobre los trenes —el formato central de la era— en un momento en que la ciudad lo combatía, y junto al libro *Subway Art* de Chalfant y Cooper (1984) fijó el canon visual del writing neoyorquino (ver `wholecar`, `piece` y `bombing`).', funFact: '*Style Wars* (1983), dirigido por Tony Silver y producido con Henry Chalfant, ganó el Grand Prize for Documentaries en el Festival de Sundance de 1983 y fue emitido por PBS ese mismo año, convirtiéndose en el registro de referencia del graffiti y el breaking neoyorquino.', related: ['BOMBING', 'B_BOY', 'CRAZYLEGS', 'EXPANSION80S', 'HIP_HOP', 'PIECE', 'ROCKSTEADY', 'TAG', 'TAKI183', 'WHOLECAR', 'WILD_STYLE', 'WRITERSHIST'] } },
  { word: 'SUGARHILL', category: 'mcing', difficulty: 'easy', knowledge: { title: 'Sugarhill Gang', description: 'The Sugarhill Gang es el grupo de rap estadounidense formado en Englewood, Nueva Jersey, en 1979 por la productora Sylvia Robinson, con Henry «Big Bank Hank» Jackson, Michael «Wonder Mike» Wright y Guy «Master Gee» O\'Brien. Su single debut, «Rapper\'s Delight» (1979), fue la primera canción de rap en entrar al Top 40 del Billboard Hot 100 y convirtió al grupo en la cara pública del rap en su salto a la industria (ver `rappers-delight`). Su nombre viene del barrio Sugar Hill de Harlem, igual que el sello Sugar Hill Records.', importance: 'Sugarhill Gang demostró que el rap podía venderse como música grabada y sonar en la radio: su éxito abrió el camino comercial por el que entró la escena neoyorquina y, más tarde, la industria que se consolidó en los 80 (ver `expansion-80s`, `old-school`). Aunque el grupo es recordado casi solo por su debut, ese debut es una de las piezas que definieron la cultura (ver `hip-hop`).', funFact: '«Rapper\'s Delight» fue la primera canción de rap en entrar al Top 40 del Billboard Hot 100 (puesto 36, enero de 1980) y el primer tema del Top 40 estadounidense que solo se vendía en versión extendida de 12 pulgadas, de más de 14 minutos.', related: ['EXPANSION80S', 'GMASTERCAZ', 'GRABACIONES', 'HIP_HOP', 'OLD_SCHOOL', 'RAPDELIGHT'] } },
  { word: 'TAKI183', category: 'graffiti', difficulty: 'easy', knowledge: { title: 'TAKI 183', description: 'TAKI 183 es el tag (firma) de un writer griego-estadounidense de Washington Heights, Manhattan, activo a fines de los 60 y principios de los 70, cuyo nombre de pila es Demetrios y que nunca reveló su nombre completo. Es la figura central del registro documentado más temprano del writing neoyorquino: el artículo del New York Times del 21 de julio de 1971 que llevó el graffiti a la atención del público masivo.', importance: 'TAKI 183 es el writer que le dio nombre público al graffiti: gracias a él, el writing pasó de actividad anónima de barrio a fenómeno documentado y masivo, y su tag es el símbolo del origen de la fama en la cultura del writing (ver `writers-historicos`).', funFact: 'El artículo del New York Times del 21 de julio de 1971, "\'Taki 183\' Spawns Pen Pals", es el registro documentado más famoso del writing: convirtió a TAKI 183 en el primer writer con fama pública y disparó una ola de imitadores en toda la ciudad.', related: ['BOMBING', 'STYLEWARS', 'TAG', 'WRITERS70', 'WRITERSHIST'] } },
  { word: 'THEMESSAGE', category: 'historia', difficulty: 'easy', knowledge: { title: 'The Message', description: '«The Message» es el single publicado por Sugar Hill Records el 1 de julio de 1982, acreditado a Grandmaster Flash & The Furious Five, y considerado el primer gran clásico del rap con contenido social: narra la vida en los barrios pobres de Nueva York —el estrés, la pobreza, la cárcel— con el famoso estribillo «Don\'t push me \'cause I\'m close to the edge». Fue escrita por Duke Bootee (Edward G. Fletcher) y Melle Mel, con créditos también para Jiggs Chase y Sylvia Robinson (ver `conscious-rap`). En 2002 fue una de las 50 grabaciones inaugurales del National Recording Registry de la Biblioteca del Congreso: la primera grabación de hip hop en recibir ese honor.', importance: '«The Message» es la obra que demostró que el rap podía ser testimonio social y no solo fiesta: está considerada por Rolling Stone (2012) la mejor canción de hip hop de todos los tiempos y por la Biblioteca del Congreso la primera grabación de hip hop en ingresar al National Recording Registry (2002). Su influencia llega a todo el rap de denuncia posterior, del rap político estadounidense al rap conciente latinoamericano (ver `conscious-rap`, `storytelling`).', funFact: '«The Message» fue una de las 50 grabaciones inaugurales del National Recording Registry de la Biblioteca del Congreso (2002) —la primera de hip hop en la historia del registro— y en 2004 quedó en el puesto 51 de las 500 mejores canciones de todos los tiempos según Rolling Stone, la posición más alta para una canción de los 80 y para una de rap.', related: ['CONSCIOUSRAP', 'CONSOLIDA80', 'FLASH', 'GRABACIONES', 'HIP_HOP', 'MC', 'MELLEMEL', 'RAPDELIGHT', 'STORYTELLING'] } },
  { word: 'TIRODEGRACIA', category: 'chile', difficulty: 'medium', knowledge: { title: 'Tiro de Gracia', description: 'Tiro de Gracia fue el grupo de rap chileno que marcó el boom comercial del hip hop en Chile: su debut «Ser hümano!!» (1997, EMI) vendió decenas de miles de copias —las cifras exactas son discutidas— y llevó el rap de las poblaciones a la radio y la televisión masiva (ver `hip-hop-chileno-90s`). Formado en Santiago en 1993, activo hasta 2019, es la referencia obligada del rap chileno de los 90 y del rap conciente latinoamericano (ver `conscious-rap`).', importance: 'Tiro de Gracia demostró que el rap chileno podía ser un éxito comercial masivo sin abandonar la crítica social: «Ser hümano!!» abrió la puerta a los lanzamientos con sello de Makiza, Rezonancia, Clan Enigma Oculto, Mamma Soul y De Kiruza (ver `hip-hop-chileno-90s`). Su obra es el puente entre la escena de los 90 y el rap conciente que definió la década siguiente (ver `hip-hop-chileno-2000s`, `conscious-rap`, `latinoamerica`).', funFact: '«Ser hümano!!» (EMI, 1997) fue el primer gran éxito comercial del rap chileno: vendió más de 50.000 copias según una sección del artículo de Wikipedia sobre el hip hop chileno (80.000 según otra sección del mismo artículo) e impulsó la ola de lanzamientos con sello del rap chileno a fines de los 90.', related: ['CHILE90S', 'CONSCIOUSRAP', 'HIP_HOP', 'LATAM', 'MAKIZA', 'PANTERAS'] } },
  { word: 'WILD_STYLE', category: 'historia', difficulty: 'easy', knowledge: { title: 'Wild Style', description: '*Wild Style* es la película dirigida, escrita y producida por Charlie Ahearn que se considera la primera película del Hip Hop: retrata el graffiti, el breaking, el DJing y el MCing del Nueva York de comienzos de los 80, con los propios protagonistas de la cultura interpretando personajes. Filmada en 1981 y completada en 1982, se estrenó en festival en noviembre de 1982 y llegó a los cines de EE. UU. el 23 de noviembre de 1983. Su reparto mezcla a escritores reales como Lee Quiñones y Lady Pink con leyendas de la escena como la Rock Steady Crew, Grandmaster Flash y la Zulu Nation.', importance: '*Wild Style* es el registro cinematográfico más completo del Hip Hop temprano: mostró al mundo los cuatro elementos —graffiti, breaking, DJing y MCing— interpretados por sus propios creadores, y fijó la imagen pública de la cultura antes de que la industria la comercializara. Para el breaking, sus escenas de batallas (con la Rock Steady Crew) y para el graffiti, sus secuencias de trenes y murales, la convirtieron en material de referencia para generaciones de practicantes en todo el mundo, incluida la escena chilena que la vio llegar en los 80 (ver `breaking-chileno`).', funFact: '*Wild Style* se rodó en 1981 con los protagonistas reales de la cultura: Lee Quiñones y Lady Pink en los roles centrales, y la Rock Steady Crew, Grandmaster Flash, la Zulu Nation y Cold Crush Brothers apareciendo como ellos mismos.', related: ['B_BOY', 'CRAZYLEGS', 'EXPANSION80S', 'HIP_HOP', 'PIECE', 'ROCKSTEADY', 'TAG', 'WILDSTYLE', 'WRITERSHIST', 'ZULU_NATION'] } },
  { word: 'WU_TANG_CLAN', category: 'mcing', difficulty: 'medium', knowledge: { title: 'Wu-Tang Clan', description: 'Wu-Tang Clan es el colectivo de rap formado en Staten Island, Nueva York, en 1992, alrededor del productor y líder de facto RZA. Con su debut «Enter the Wu-Tang (36 Chambers)» (1993) revitalizó el rap de la Costa Este y definió el sonido del boom bap de los 90: beats ásperos, samples de películas de kung fu y nueve MCs con identidades propias (ver `boom-bap`). Es considerado uno de los grupos más grandes del Hip Hop y fue inducido al Rock and Roll Hall of Fame en la clase de 2026.', importance: 'Wu-Tang Clan rearmó el rap de Nueva York en los 90: su sonido —el boom bap oscuro de RZA, con samples de kung fu y soul— y su modelo de negocios colectivo marcaron a toda una generación (ver `boom-bap`, `golden-era`). La idea del grupo como «clan» con identidades múltiples influyó en la forma de organizar los colectivos de rap en todo el mundo, incluida la manera en que se entiende el trabajo en equipo dentro de la cultura (ver `crew`).', funFact: '«Enter the Wu-Tang (36 Chambers)» (1993) se publicó tras un single independiente, «Protect Ya Neck», y su sello permitió que cada miembro firmara contratos solistas con discográficas distintas: una estrategia comercial sin precedentes que convirtió al grupo en nueve carreras a la vez.', related: ['BOOM_BAP', 'GOLDEN_ERA', 'HARDCORE_RAP', 'HIP_HOP', 'NUEVA_YORK'] } },
]
